// Konsep 10: Net-Zero Scale — Keseimbangan Karbon Netral
// 2D Flat Vector Single Icon Motion | 16:9 4K Ready | 20s Seamless Loop (3 Scenes)
// Recommended Export: 3840x2160, 60fps, 100 Mbps

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;

  // Color Palette — Pale Rose Ivory, Warm Silver Mist, Crimson Berry, Deep Teal & Champagne Gold (Zero Background Glow)
  const PALETTE = {
    bgTop: '#FAF4F5',
    bgBottom: '#EBE4E6',
    tealDark: '#114E54',
    teal: '#1A6B72',
    tealBright: '#2E949C',
    berryDeep: '#8E2846',
    berry: '#B83B5E',
    berryLight: '#D86485',
    goldDark: '#B8883E',
    gold: '#D4A359',
    goldBright: '#E9C383',
    carbonDark: '#6A646B',
    carbonMid: '#8A838C',
    roseWhite: '#FCF9FA',
    shadow: 'rgba(17, 78, 84, 0.075)'
  };

  // --- Easing & Math Helpers ---
  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function mapRange(v, inMin, inMax) {
    return clamp01((v - inMin) / (inMax - inMin));
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function easeOutCubic(u) {
    const x = 1 - clamp01(u);
    return 1 - x * x * x;
  }

  function easeInCubic(u) {
    const x = clamp01(u);
    return x * x * x;
  }

  function easeInOutCubic(u) {
    const x = clamp01(u);
    return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
  }

  function easeOutQuart(u) {
    const x = 1 - clamp01(u);
    return 1 - x * x * x * x;
  }

  function easeInOutQuart(u) {
    const x = clamp01(u);
    return x < 0.5 ? 8 * x * x * x * x : 1 - Math.pow(-2 * x + 2, 4) / 2;
  }

  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, Math.abs(w) * 0.5, Math.abs(h) * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  }

  function fillDuotoneSplit(x, y, w, h, splitX, leftColor, rightColor) {
    ctx.fillStyle = leftColor;
    ctx.fillRect(x, y, w, h);
    ctx.fillStyle = rightColor;
    ctx.fillRect(splitX, y, x + w - splitX, h);
  }

  function drawDiamond(x, y, rx, ry, leftC, rightC) {
    if (rx <= 0.4 || ry <= 0.4) return;
    ctx.beginPath();
    ctx.moveTo(x, y - ry);
    ctx.lineTo(x + rx, y);
    ctx.lineTo(x, y + ry);
    ctx.lineTo(x - rx, y);
    ctx.closePath();
    ctx.save();
    ctx.clip();
    fillDuotoneSplit(x - rx - 1, y - ry - 1, rx * 2 + 2, ry * 2 + 2, x, leftC, rightC);
    ctx.restore();
  }

  function drawDuotoneLeaf(ox, oy, angle, len, halfW, leftC, rightC) {
    if (len <= 1 || halfW <= 0.5) return;
    ctx.save();
    ctx.translate(ox, oy);
    ctx.rotate(angle);

    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.bezierCurveTo(halfW * 1.15, -len * 0.34, halfW * 0.90, -len * 0.78, 0, -len);
    ctx.bezierCurveTo(-halfW * 0.90, -len * 0.78, -halfW * 1.15, -len * 0.34, 0, 0);
    ctx.closePath();

    ctx.save();
    ctx.clip();
    fillDuotoneSplit(-halfW * 1.3, -len * 1.05, halfW * 2.6, len * 1.1, 0, leftC, rightC);
    ctx.restore();
    ctx.restore();
  }

  function drawGroundShadow(x, y, rx, ry, alphaScale) {
    if (alphaScale <= 0.001 || rx <= 0.5 || ry <= 0.5) return;
    ctx.save();
    ctx.globalAlpha = alphaScale;
    ctx.fillStyle = PALETTE.shadow;
    ctx.beginPath();
    ctx.ellipse(x, y, rx, ry, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  // --- Clean Background (Flat Pale Rose Ivory to Warm Silver Mist, Strictly Zero Glow / Zero Borders) ---
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
  bgGrad.addColorStop(0, PALETTE.bgTop);
  bgGrad.addColorStop(1, PALETTE.bgBottom);
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // Shared Balance Scale & Net-Zero Emblem Dimensions (Roberval Precision Layout — Zero Crossing Rods!)
  const baseY = cy + minSide * 0.228;
  const pivotY = cy + minSide * 0.022;
  const beamHalfSpan = minSide * 0.215;
  const stemLen = minSide * 0.044;
  const panW = minSide * 0.140;
  const panH = minSide * 0.020;
  const shadowBaseY = cy + minSide * 0.305;

  // Reusable Architectural Roberval Balance Scale Renderer (100% Unobstructed Loads, Continuous across Scene 0 & 1)
  function drawBalanceScale(baseProg, pillarProg, beamProg, panProg, tiltAngle, drawLeftLoadFn, drawRightLoadFn) {
    // 1. Stepped Ground Pedestal Base
    if (baseProg > 0.005) {
      const bw = minSide * 0.225 * baseProg;
      const bh = minSide * 0.024 * Math.min(1, baseProg * 1.4);

      ctx.save();
      roundedRectPath(cx - bw * 0.5, baseY, bw, bh, bh * 0.5);
      ctx.clip();
      fillDuotoneSplit(cx - bw * 0.5 - 1, baseY - 1, bw + 2, bh + 2, cx, PALETTE.teal, PALETTE.tealDark);
      ctx.restore();

      const accW = bw * 0.34;
      const accH = bh * 0.32;
      roundedRectPath(cx - accW * 0.5, baseY + (bh - accH) * 0.5, accW, accH, accH * 0.5);
      ctx.fillStyle = PALETTE.gold;
      ctx.fill();
    }

    // 2. Tapered Central Fulcrum Column (Strictly above pedestal, ending cleanly below pivot)
    if (pillarProg > 0.005) {
      const colBotY = baseY - minSide * 0.006;
      const colTopY = lerp(colBotY, pivotY + minSide * 0.022, pillarProg);
      const botHalfW = minSide * 0.022 * Math.min(1, pillarProg * 1.5);
      const topHalfW = lerp(botHalfW, minSide * 0.011, pillarProg);

      ctx.beginPath();
      ctx.moveTo(cx - botHalfW, colBotY);
      ctx.lineTo(cx - topHalfW, colTopY);
      ctx.lineTo(cx + topHalfW, colTopY);
      ctx.lineTo(cx + botHalfW, colBotY);
      ctx.closePath();

      ctx.save();
      ctx.clip();
      fillDuotoneSplit(cx - botHalfW - 2, colTopY - 2, botHalfW * 2 + 4, colBotY - colTopY + 4, cx, PALETTE.teal, PALETTE.tealDark);
      ctx.restore();
    }

    // 3. Tilting Horizontal Balance Beam + Always-Vertical Top-Mounted Weighing Pans (Zero Overlapping Wires!)
    if (beamProg > 0.005) {
      const curHalfSpan = beamHalfSpan * beamProg;
      const beamH = minSide * 0.016;

      // Exact world coordinates of left & right beam end-pins
      const cosA = Math.cos(tiltAngle);
      const sinA = Math.sin(tiltAngle);
      const leftPinX = cx - cosA * curHalfSpan;
      const leftPinY = pivotY - sinA * curHalfSpan;
      const rightPinX = cx + cosA * curHalfSpan;
      const rightPinY = pivotY + sinA * curHalfSpan;

      // Vertical pan stems & top-mounted weighing pans (loads sit completely unobstructed in open air!)
      if (panProg > 0.005) {
        const curStem = stemLen * panProg;
        const curPanW = panW * panProg;
        const curPanH = panH * panProg;

        function drawPanAssembly(pinX, pinY, drawLoadFn) {
          const panBotY = pinY - curStem;
          const panTopY = panBotY - curPanH;

          // Short vertical gold support stem rising cleanly from beam pin to pan underside
          ctx.beginPath();
          ctx.moveTo(pinX, pinY - minSide * 0.006);
          ctx.lineTo(pinX, panBotY + minSide * 0.004);
          ctx.strokeStyle = PALETTE.goldDark;
          ctx.lineWidth = minSide * 0.0075 * panProg;
          ctx.lineCap = 'round';
          ctx.stroke();

          // Sleek Curved Champagne Gold Weighing Pan Dish
          ctx.save();
          ctx.beginPath();
          ctx.moveTo(pinX - curPanW * 0.5, panTopY);
          ctx.lineTo(pinX + curPanW * 0.5, panTopY);
          ctx.bezierCurveTo(
            pinX + curPanW * 0.44,
            panBotY + curPanH * 0.25,
            pinX - curPanW * 0.44,
            panBotY + curPanH * 0.25,
            pinX - curPanW * 0.5,
            panTopY
          );
          ctx.closePath();
          ctx.clip();
          fillDuotoneSplit(pinX - curPanW * 0.5 - 1, panTopY - 1, curPanW + 2, curPanH * 1.5, pinX, PALETTE.gold, PALETTE.goldBright);
          ctx.restore();

          // Unobstructed load resting cleanly ABOVE pan top surface with crisp vertical gap
          if (drawLoadFn) {
            drawLoadFn(pinX, panTopY - minSide * 0.008);
          }
        }

        drawPanAssembly(leftPinX, leftPinY, drawLeftLoadFn);
        drawPanAssembly(rightPinX, rightPinY, drawRightLoadFn);
      }

      // Main Tilted Beam Bar
      ctx.save();
      ctx.translate(cx, pivotY);
      ctx.rotate(tiltAngle);
      roundedRectPath(-curHalfSpan, -beamH * 0.5, curHalfSpan * 2, beamH, beamH * 0.5);
      ctx.save();
      ctx.clip();
      fillDuotoneSplit(-curHalfSpan - 1, -beamH * 0.5 - 1, curHalfSpan * 2 + 2, beamH + 2, 0, PALETTE.teal, PALETTE.tealDark);
      ctx.restore();

      // End Cap Pins
      const pinR = minSide * 0.011 * beamProg;
      ctx.fillStyle = PALETTE.gold;
      ctx.beginPath();
      ctx.arc(-curHalfSpan, 0, pinR, 0, Math.PI * 2);
      ctx.arc(curHalfSpan, 0, pinR, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }

    // 4. Central Fulcrum Pivot Medallion
    if (pillarProg > 0.25) {
      const pivProg = easeOutQuart(mapRange(pillarProg, 0.25, 1.0));
      const pivR = minSide * 0.022 * pivProg;
      ctx.save();
      ctx.beginPath();
      ctx.arc(cx, pivotY, pivR, 0, Math.PI * 2);
      ctx.clip();
      fillDuotoneSplit(cx - pivR - 1, pivotY - pivR - 1, pivR * 2 + 2, pivR * 2 + 2, cx, PALETTE.gold, PALETTE.goldBright);
      ctx.restore();

      ctx.beginPath();
      ctx.arc(cx, pivotY, pivR * 0.42, 0, Math.PI * 2);
      ctx.fillStyle = PALETTE.tealDark;
      ctx.fill();
    }
  }

  // Unified Crisp 2D Stylized Carbon Emission Cloud (Smoothly purifies from dark Carbon -> Clean Teal!)
  function drawCarbonCloud(centerX, baseLineY, scaleVal, purifyAmt) {
    if (scaleVal <= 0.01) return;
    const s = minSide * scaleVal;
    const w = s * 0.105;
    const h = s * 0.064;

    ctx.save();
    ctx.translate(centerX, baseLineY);

    // Unified clean cloud silhouette (single closed rounded path — zero overlapping circle seams!)
    ctx.beginPath();
    ctx.moveTo(-w * 0.36, 0);
    ctx.lineTo(w * 0.36, 0);
    ctx.bezierCurveTo(w * 0.56, 0, w * 0.56, -h * 0.56, w * 0.32, -h * 0.62);
    ctx.bezierCurveTo(w * 0.28, -h * 1.06, -w * 0.22, -h * 1.08, -w * 0.28, -h * 0.66);
    ctx.bezierCurveTo(-w * 0.54, -h * 0.64, -w * 0.54, 0, -w * 0.36, 0);
    ctx.closePath();

    ctx.save();
    ctx.clip();

    // Base Carbon Slate duotone
    fillDuotoneSplit(-w * 0.6, -h * 1.15, w * 1.2, h * 1.25, 0, PALETTE.carbonDark, PALETTE.carbonMid);

    // Smooth analog color purification into Clean Bright Teal as Net-Zero balance is reached!
    const pur = clamp01(purifyAmt);
    if (pur > 0.01) {
      ctx.globalAlpha = pur;
      fillDuotoneSplit(-w * 0.6, -h * 1.15, w * 1.2, h * 1.25, 0, PALETTE.teal, PALETTE.tealBright);
      ctx.globalAlpha = 1;
    }

    // Center indicator diamond (transitions smoothly from Crimson Berry alert -> Champagne Gold clean!)
    const dRx = s * 0.010;
    const dRy = s * 0.014;
    drawDiamond(0, -h * 0.42, dRx, dRy, PALETTE.berry, PALETTE.berryLight);
    if (pur > 0.01) {
      ctx.globalAlpha = pur;
      drawDiamond(0, -h * 0.42, dRx, dRy, PALETTE.gold, PALETTE.goldBright);
      ctx.globalAlpha = 1;
    }

    ctx.restore();
    ctx.restore();
  }

  // Sculptural Bold Typographic "0" (Net-Zero) Oval Ribbon Emblem
  // Bold editorial vertical oval (NOT a thin circular HUD ring!), unified clipped duotone bands!
  function drawNetZeroOval(centerX, centerY, scaleVal) {
    if (scaleVal <= 0.005) return;
    const outRx = minSide * 0.148 * scaleVal;
    const outRy = minSide * 0.204 * scaleVal;
    const inRx = minSide * 0.090 * scaleVal;
    const inRy = minSide * 0.144 * scaleVal;

    ctx.save();
    // Build bold typographic "0" ring with evenodd fill rule (outer oval minus inner oval)
    ctx.beginPath();
    ctx.ellipse(centerX, centerY, outRx, outRy, 0, 0, Math.PI * 2);
    ctx.ellipse(centerX, centerY, inRx, inRy, 0, 0, Math.PI * 2);
    ctx.clip('evenodd');

    // Primary Deep Teal / Dark Teal architectural body
    fillDuotoneSplit(
      centerX - outRx - 2,
      centerY - outRy - 2,
      outRx * 2 + 4,
      outRy * 2 + 4,
      centerX,
      PALETTE.teal,
      PALETTE.tealDark
    );

    // Upper-right Champagne Gold crown ribbon band clipped cleanly inside the oval
    ctx.beginPath();
    ctx.moveTo(centerX, centerY);
    ctx.lineTo(centerX, centerY - outRy - 6);
    ctx.lineTo(centerX + outRx + 6, centerY - outRy - 6);
    ctx.lineTo(centerX + outRx + 6, centerY - outRy * 0.12);
    ctx.closePath();
    ctx.fillStyle = PALETTE.gold;
    ctx.fill();

    // Lower-left Crimson Berry balance accent band (editorial color harmony!)
    ctx.beginPath();
    ctx.moveTo(centerX, centerY);
    ctx.lineTo(centerX - outRx - 6, centerY + outRy * 0.12);
    ctx.lineTo(centerX - outRx - 6, centerY + outRy + 6);
    ctx.lineTo(centerX, centerY + outRy + 6);
    ctx.closePath();
    ctx.fillStyle = PALETTE.berry;
    ctx.fill();

    ctx.restore();
  }

  // =========================================================================
  // SCENE 0: BALANCE SCALE ASSEMBLY & CARBON IMBALANCE (0.00s – 6.67s)
  // =========================================================================
  if (currentScene === 0) {
    const p = sceneProgress;

    // 0.00 - 0.0975 (0.00s - 0.65s): Completely empty canvas (background only)
    if (p < 0.0975) {
      return;
    }

    const baseIn = easeOutQuart(mapRange(p, 0.0975, 0.21));
    const pillarIn = easeOutQuart(mapRange(p, 0.14, 0.27));
    const beamIn = easeOutQuart(mapRange(p, 0.21, 0.33));
    const panIn = easeOutQuart(mapRange(p, 0.26, 0.38));
    const cloudIn = easeOutQuart(mapRange(p, 0.36, 0.50));

    // Smooth physical tip downward to the left as carbon weight lands [-0.21 rad ≈ -12 deg]
    const tipProg = easeInOutCubic(mapRange(p, 0.40, 0.66));
    const tiltAngle = -0.21 * tipProg;

    drawGroundShadow(cx, shadowBaseY, minSide * 0.165 * baseIn, minSide * 0.013 * baseIn, baseIn);

    drawBalanceScale(
      baseIn,
      pillarIn,
      beamIn,
      panIn,
      tiltAngle,
      (lx, ly) => {
        if (cloudIn > 0.01) {
          drawCarbonCloud(lx, ly, cloudIn, 0);
        }
      },
      null
    );

  // =========================================================================
  // SCENE 1: ECO COUNTER-WEIGHT & DAMPED NET-ZERO EQUILIBRIUM (6.67s – 13.33s)
  // =========================================================================
  } else if (currentScene === 1) {
    const p = sceneProgress;

    // Staggered arrival of 3 non-overlapping eco tokens on right pan
    const ecoL = easeOutQuart(mapRange(p, 0.04, 0.18));
    const ecoC = easeOutQuart(mapRange(p, 0.14, 0.28));
    const ecoR = easeOutQuart(mapRange(p, 0.24, 0.38));

    // Smooth damped pendulum swing from -0.21 rad -> gentle +0.038 overshoot -> exact 0.000 equilibrium by p=0.60!
    let tiltAngle = -0.21;
    if (p > 0.08 && p < 0.62) {
      const u = mapRange(p, 0.08, 0.62);
      // Critically/lightly damped smooth cosine decay starting at -0.21 and landing cleanly on 0
      const decay = Math.pow(1 - u, 2.2);
      tiltAngle = -0.21 * decay * Math.cos(u * Math.PI * 1.5);
    } else if (p >= 0.62) {
      tiltAngle = 0;
    }

    // Smooth analog carbon purification as scale reaches Net-Zero balance
    const purifyAmt = easeInOutCubic(mapRange(p, 0.34, 0.62));
    const cloudShrink = lerp(1.0, 0.84, purifyAmt);
    const balanceCrown = easeOutCubic(mapRange(p, 0.54, 0.64)) * (1 - easeInCubic(mapRange(p, 0.70, 0.76)));

    // Clean sequenced retraction BEFORE Scene 2 Net-Zero "0" seed blooms (zero overlap!)
    const loadsOut = 1 - easeInCubic(mapRange(p, 0.70, 0.78));
    const panOut = 1 - easeInCubic(mapRange(p, 0.74, 0.81));
    const beamOut = 1 - easeInCubic(mapRange(p, 0.77, 0.84));
    const pillarOut = 1 - easeInCubic(mapRange(p, 0.80, 0.87));
    const baseOut = 1 - easeInCubic(mapRange(p, 0.83, 0.90));
    const zeroSeedIn = easeOutQuart(mapRange(p, 0.885, 1.0));

    // Ground shadow seamless from Scene 0 -> Scene 1 -> Scene 2
    const shRx = Math.max(minSide * 0.165 * baseOut, minSide * 0.120 * zeroSeedIn);
    const shAlpha = Math.max(baseOut, zeroSeedIn);
    drawGroundShadow(cx, shadowBaseY, shRx, minSide * 0.013 * shAlpha, shAlpha);

    // 1. Balance Confirmation Diamond strictly above fulcrum pin at equilibrium
    if (balanceCrown > 0.01) {
      drawDiamond(
        cx,
        pivotY - minSide * 0.055,
        minSide * 0.012 * balanceCrown,
        minSide * 0.019 * balanceCrown,
        PALETTE.gold,
        PALETTE.goldBright
      );
    }

    // 2. Balance Scale with Purifying Left Cloud & 3 Strictly Separated Right Eco-Tokens
    drawBalanceScale(
      baseOut,
      pillarOut,
      beamOut,
      panOut,
      tiltAngle,
      (lx, ly) => {
        const s = cloudShrink * loadsOut;
        if (s > 0.01) {
          drawCarbonCloud(lx, ly, s, purifyAmt);
        }
      },
      (rx, ry) => {
        // 3 strictly separated tokens perched cleanly above right pan (left leaf, center gold crystal, right leaf)
        const sL = ecoL * loadsOut;
        const sC = ecoC * loadsOut;
        const sR = ecoR * loadsOut;

        if (sL > 0.01) {
          drawDuotoneLeaf(rx - minSide * 0.032, ry, -0.45, minSide * 0.048 * sL, minSide * 0.016 * sL, PALETTE.tealDark, PALETTE.teal);
        }
        if (sR > 0.01) {
          drawDuotoneLeaf(rx + minSide * 0.032, ry, 0.45, minSide * 0.048 * sR, minSide * 0.016 * sR, PALETTE.teal, PALETTE.tealBright);
        }
        if (sC > 0.01) {
          drawDiamond(rx, ry - minSide * 0.026 * sC, minSide * 0.016 * sC, minSide * 0.025 * sC, PALETTE.gold, PALETTE.goldBright);
        }
      }
    );

    // 3. Clean Scene 2 Handoff: Bold Sculptural Net-Zero "0" starts unfolding cleanly from center [0.89 -> 1.00]
    if (zeroSeedIn > 0.005) {
      drawNetZeroOval(cx, cy, 0.42 * zeroSeedIn);
    }

  // =========================================================================
  // SCENE 2: SCULPTURAL NET-ZERO "0" EMBLEM & CLEAN EXIT (13.33s – 20.00s)
  // =========================================================================
  } else {
    const p = sceneProgress;

    // 0.9025 - 1.00 (19.35s - 20.00s): Completely empty canvas (background only)
    if (p > 0.9025) {
      return;
    }

    const ovalExpand = easeOutQuart(mapRange(p, 0.0, 0.22));
    const leavesIn = easeOutQuart(mapRange(p, 0.14, 0.30));
    const barsIn = easeOutCubic(mapRange(p, 0.22, 0.35));

    const barsOut = 1 - easeInCubic(mapRange(p, 0.68, 0.76));
    const leavesOut = 1 - easeInCubic(mapRange(p, 0.72, 0.80));
    const ovalScaleOut = 1 - easeInCubic(mapRange(p, 0.79, 0.9025));

    const curOvalScale = lerp(0.42, 1.0, ovalExpand) * ovalScaleOut;
    const leafVis = leavesIn * leavesOut;
    const barVis = barsIn * barsOut;

    const breathMask = easeInOutCubic(mapRange(p, 0.24, 0.34)) * (1 - easeInOutCubic(mapRange(p, 0.66, 0.76)));
    const floatY = Math.sin(loopT * 2.1) * minSide * 0.005 * breathMask;
    const zeroY = cy + floatY;

    drawGroundShadow(cx, shadowBaseY, minSide * 0.120 * ovalScaleOut, minSide * 0.013 * ovalScaleOut, ovalScaleOut);

    // 1. Flanking Symmetrical Horizontal Balance Bars (Echoing level Net-Zero equilibrium, strictly clear of oval!)
    if (barVis > 0.005) {
      const barYOffs = [-minSide * 0.036, minSide * 0.036];
      const barLens = [minSide * 0.068, minSide * 0.048];
      const barH = minSide * 0.011;
      const pulse = Math.sin(p * Math.PI * 5) * minSide * 0.007;

      for (let side = -1; side <= 1; side += 2) {
        for (let k = 0; k < 2; k++) {
          const bw = barLens[k] * barVis;
          const innerEdge = minSide * 0.212 + k * minSide * 0.014 + pulse;
          const bx = side < 0 ? cx - innerEdge - bw : cx + innerEdge;
          const by = zeroY + barYOffs[k] - barH * 0.5;
          roundedRectPath(bx, by, bw, barH, barH * 0.5);
          ctx.fillStyle = k === 0 ? PALETTE.gold : PALETTE.tealBright;
          ctx.fill();
        }
      }
    }

    // 2. Bold Sculptural Typographic "0" (Net-Zero) Duotone Ribbon Emblem
    drawNetZeroOval(cx, zeroY, curOvalScale);

    // 3. Two Symmetrical Botanical Accent Leaves Strictly Outside Upper-Right & Lower-Left Shoulders (zero overlap!)
    if (leafVis > 0.005) {
      const sway = Math.sin(loopT * 2.4) * 0.045 * breathMask;
      const leafL = minSide * 0.078 * leafVis;
      const leafW = minSide * 0.026 * leafVis;

      // Upper-right Champagne Gold leaf pointing cleanly outward
      drawDuotoneLeaf(
        cx + minSide * 0.132,
        zeroY - minSide * 0.145,
        0.64 + sway,
        leafL,
        leafW,
        PALETTE.gold,
        PALETTE.goldBright
      );

      // Lower-left Deep Teal leaf pointing cleanly outward (180-deg rotational symmetry!)
      drawDuotoneLeaf(
        cx - minSide * 0.132,
        zeroY + minSide * 0.145,
        Math.PI + 0.64 + sway,
        leafL,
        leafW,
        PALETTE.teal,
        PALETTE.tealBright
      );
    }

    // 4. Clean Centered Equilibrium Diamond strictly inside the spacious "0" hollow cavity
    const innerDiamondVis = easeOutCubic(mapRange(p, 0.18, 0.32)) * leavesOut;
    if (innerDiamondVis > 0.01) {
      drawDiamond(
        cx,
        zeroY,
        minSide * 0.016 * innerDiamondVis,
        minSide * 0.025 * innerDiamondVis,
        PALETTE.gold,
        PALETTE.goldBright
      );
    }
  }
}

// Konsep 9: Terra Bloom — Kompos & Siklus Nutrisi Tanah
// 2D Flat Vector Single Icon Motion | 16:9 4K Ready | 20s Seamless Loop (3 Scenes)
// Recommended Export: 3840x2160, 60fps, 100 Mbps

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;

  // Color Palette — Soft Oat Milk, Dusty Peach, Rich Sienna, Golden Wheat & Forest Fern (Zero Background Glow)
  const PALETTE = {
    bgTop: '#F9F4EC',
    bgBottom: '#EFE1D1',
    siennaDeep: '#7A351D',
    sienna: '#A64B2A',
    siennaLight: '#C76642',
    claySand: '#D7B598',
    wheatDark: '#C28520',
    wheat: '#DFA034',
    wheatBright: '#F2BE5A',
    fernDeep: '#2C5135',
    fern: '#3D6B48',
    fernLight: '#5C9168',
    oatCream: '#FAF6EF',
    shadow: 'rgba(122, 53, 29, 0.075)'
  };

  // --- Easing & Math Helpers ---
  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function mapRange(v, inMin, inMax) {
    return clamp01((v - inMin) / (inMax - inMin));
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function easeInOutSine(u) {
    const x = clamp01(u);
    return -(Math.cos(Math.PI * x) - 1) * 0.5;
  }

  function easeOutCubic(u) {
    const x = 1 - clamp01(u);
    return 1 - x * x * x;
  }

  function easeInCubic(u) {
    const x = clamp01(u);
    return x * x * x;
  }

  function easeInOutCubic(u) {
    const x = clamp01(u);
    return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
  }

  function easeOutQuart(u) {
    const x = 1 - clamp01(u);
    return 1 - x * x * x * x;
  }

  function easeInOutQuart(u) {
    const x = clamp01(u);
    return x < 0.5 ? 8 * x * x * x * x : 1 - Math.pow(-2 * x + 2, 4) / 2;
  }

  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, Math.abs(w) * 0.5, Math.abs(h) * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  }

  function fillDuotoneSplit(x, y, w, h, splitX, leftColor, rightColor) {
    ctx.fillStyle = leftColor;
    ctx.fillRect(x, y, w, h);
    ctx.fillStyle = rightColor;
    ctx.fillRect(splitX, y, x + w - splitX, h);
  }

  function drawDiamond(x, y, rx, ry, leftC, rightC) {
    if (rx <= 0.4 || ry <= 0.4) return;
    ctx.beginPath();
    ctx.moveTo(x, y - ry);
    ctx.lineTo(x + rx, y);
    ctx.lineTo(x, y + ry);
    ctx.lineTo(x - rx, y);
    ctx.closePath();
    ctx.save();
    ctx.clip();
    fillDuotoneSplit(x - rx - 1, y - ry - 1, rx * 2 + 2, ry * 2 + 2, x, leftC, rightC);
    ctx.restore();
  }

  function drawGroundShadow(x, y, rx, ry, alphaScale) {
    if (alphaScale <= 0.001 || rx <= 0.5 || ry <= 0.5) return;
    ctx.save();
    ctx.globalAlpha = alphaScale;
    ctx.fillStyle = PALETTE.shadow;
    ctx.beginPath();
    ctx.ellipse(x, y, rx, ry, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  // Unified Clipped 2D Duotone Botanical Leaf
  function drawDuotoneLeaf(ox, oy, angle, len, halfW, leftC, rightC, showMidrib) {
    if (len <= 1 || halfW <= 0.5) return;
    ctx.save();
    ctx.translate(ox, oy);
    ctx.rotate(angle);

    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.bezierCurveTo(halfW * 1.15, -len * 0.34, halfW * 0.90, -len * 0.78, 0, -len);
    ctx.bezierCurveTo(-halfW * 0.90, -len * 0.78, -halfW * 1.15, -len * 0.34, 0, 0);
    ctx.closePath();

    ctx.save();
    ctx.clip();
    fillDuotoneSplit(-halfW * 1.3, -len * 1.05, halfW * 2.6, len * 1.1, 0, leftC, rightC);

    if (showMidrib) {
      ctx.beginPath();
      ctx.moveTo(0, -len * 0.14);
      ctx.lineTo(0, -len * 0.78);
      ctx.strokeStyle = 'rgba(250, 246, 239, 0.58)';
      ctx.lineWidth = Math.max(1, halfW * 0.11);
      ctx.lineCap = 'round';
      ctx.stroke();
    }
    ctx.restore();
    ctx.restore();
  }

  // --- Clean Background (Flat Oat Milk to Dusty Peach Gradient, Strictly Zero Glow / Zero Borders) ---
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
  bgGrad.addColorStop(0, PALETTE.bgTop);
  bgGrad.addColorStop(1, PALETTE.bgBottom);
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // Shared Organic Soil Vessel Architecture (100% Continuous across all 3 Scenes!)
  const rimTopY = cy + minSide * 0.088;
  const rimH = minSide * 0.024;
  const rimW = minSide * 0.348;
  const bowlTopY = rimTopY + rimH + minSide * 0.005;
  const bowlW = minSide * 0.305;
  const bowlH = minSide * 0.155;
  const bowlBotY = bowlTopY + bowlH;
  const shadowBaseY = cy + minSide * 0.312;

  // Reusable Architectural Cross-Section Soil Vessel with Clipped Stratified Organic Soil Waves
  function drawSoilVessel(scaleVal, waveBoost, drawInteriorParticlesFn) {
    if (scaleVal <= 0.005) return;
    const curBowlW = bowlW * scaleVal;
    const curBowlH = bowlH * scaleVal;
    const curBowlTop = bowlBotY - curBowlH;
    const curRimW = rimW * scaleVal;
    const curRimH = rimH * scaleVal;
    const curRimTop = curBowlTop - minSide * 0.005 * scaleVal - curRimH;

    // 1. Rounded Basin Body (Unified Clipped Cross-Section displaying 3 Stratified Soil Waves)
    ctx.save();
    ctx.beginPath();
    ctx.moveTo(cx - curBowlW * 0.5, curBowlTop);
    ctx.lineTo(cx + curBowlW * 0.5, curBowlTop);
    ctx.bezierCurveTo(
      cx + curBowlW * 0.5,
      curBowlTop + curBowlH * 0.72,
      cx + curBowlW * 0.34,
      bowlBotY,
      cx,
      bowlBotY
    );
    ctx.bezierCurveTo(
      cx - curBowlW * 0.34,
      bowlBotY,
      cx - curBowlW * 0.5,
      curBowlTop + curBowlH * 0.72,
      cx - curBowlW * 0.5,
      curBowlTop
    );
    ctx.closePath();

    ctx.save();
    ctx.clip();

    // Top soil stratum (Warm Clay Sand)
    ctx.fillStyle = PALETTE.claySand;
    ctx.fillRect(cx - curBowlW * 0.55, curBowlTop - 2, curBowlW * 1.1, curBowlH + 4);

    // Helper for smooth horizontal soil wave layer clipped inside basin
    function fillStratumWave(yBase, amp, freq, phase, color) {
      const left = cx - curBowlW * 0.55;
      const right = cx + curBowlW * 0.55;
      const steps = 28;
      ctx.beginPath();
      ctx.moveTo(left, bowlBotY + 4);
      for (let s = 0; s <= steps; s++) {
        const u = s / steps;
        const wx = lerp(left, right, u);
        const wy = yBase + Math.sin(u * Math.PI * freq + phase) * amp;
        ctx.lineTo(wx, wy);
      }
      ctx.lineTo(right, bowlBotY + 4);
      ctx.closePath();
      ctx.fillStyle = color;
      ctx.fill();
    }

    const ampBase = minSide * (0.008 + 0.004 * waveBoost) * scaleVal;
    // Middle organic humus stratum (Rich Sienna)
    fillStratumWave(curBowlTop + curBowlH * 0.34, ampBase, 2.0, loopT * 1.8, PALETTE.sienna);
    // Deep fertile compost stratum (Deep Sienna)
    fillStratumWave(curBowlTop + curBowlH * 0.66, ampBase * 0.9, 2.2, -loopT * 2.1 + 1.1, PALETTE.siennaDeep);

    // Optional interior nutrient particles strictly clipped inside soil cross-section
    if (drawInteriorParticlesFn) {
      drawInteriorParticlesFn(curBowlTop, curBowlW, curBowlH);
    }

    ctx.restore();

    // Clean vessel outer rim border (re-traced explicitly for crisp 4K edge)
    ctx.beginPath();
    ctx.moveTo(cx - curBowlW * 0.5, curBowlTop);
    ctx.lineTo(cx + curBowlW * 0.5, curBowlTop);
    ctx.bezierCurveTo(
      cx + curBowlW * 0.5,
      curBowlTop + curBowlH * 0.72,
      cx + curBowlW * 0.34,
      bowlBotY,
      cx,
      bowlBotY
    );
    ctx.bezierCurveTo(
      cx - curBowlW * 0.34,
      bowlBotY,
      cx - curBowlW * 0.5,
      curBowlTop + curBowlH * 0.72,
      cx - curBowlW * 0.5,
      curBowlTop
    );
    ctx.closePath();
    ctx.strokeStyle = PALETTE.siennaDeep;
    ctx.lineWidth = minSide * 0.0038 * scaleVal;
    ctx.stroke();
    ctx.restore();

    // 2. Crisp Duotone Vessel Rim Lip Strictly Above Basin
    ctx.save();
    roundedRectPath(cx - curRimW * 0.5, curRimTop, curRimW, curRimH, curRimH * 0.5);
    ctx.clip();
    fillDuotoneSplit(cx - curRimW * 0.5 - 1, curRimTop - 1, curRimW + 2, curRimH + 2, cx, PALETTE.sienna, PALETTE.siennaDeep);
    ctx.restore();

    // Centered golden wheat accent strip on rim
    const accW = curRimW * 0.26;
    const accH = curRimH * 0.32;
    roundedRectPath(cx - accW * 0.5, curRimTop + (curRimH - accH) * 0.5, accW, accH, accH * 0.5);
    ctx.fillStyle = PALETTE.wheat;
    ctx.fill();
  }

  // =========================================================================
  // SCENE 0: COMPOST VESSEL & S-CURVE FALLING LEAVES (0.00s – 6.67s)
  // =========================================================================
  if (currentScene === 0) {
    const p = sceneProgress;

    // 0.00 - 0.0975 (0.00s - 0.65s): Completely empty canvas (background only)
    if (p < 0.0975) {
      return;
    }

    const vesselIn = easeOutQuart(mapRange(p, 0.0975, 0.27));

    drawGroundShadow(cx, shadowBaseY, minSide * 0.145 * vesselIn, minSide * 0.013 * vesselIn, vesselIn);

    // 1. 3 Dried Botanical Leaves drifting down along graceful non-overlapping S-curves into vessel rim
    const leafDrops = [
      { start: 0.22, dur: 0.28, xOff: -0.075, cL: PALETTE.wheat, cR: PALETTE.wheatBright },
      { start: 0.40, dur: 0.28, xOff: 0.068, cL: PALETTE.siennaLight, cR: PALETTE.wheat },
      { start: 0.58, dur: 0.28, xOff: -0.012, cL: PALETTE.sienna, cR: PALETTE.siennaLight }
    ];

    for (let i = 0; i < leafDrops.length; i++) {
      const ld = leafDrops[i];
      if (p <= ld.start || p >= ld.start + ld.dur) continue;
      const u = (p - ld.start) / ld.dur;
      const env = easeInOutCubic(mapRange(u, 0.0, 0.20)) * (1 - easeInOutCubic(mapRange(u, 0.80, 1.0)));
      const yPos = lerp(cy - minSide * 0.265, rimTopY - minSide * 0.012, easeInOutSine(u));
      const xPos = cx + ld.xOff * minSide + Math.sin(u * Math.PI * 2) * minSide * 0.036;
      const rot = Math.cos(u * Math.PI * 2) * 0.48 + (i - 1) * 0.22;
      const lLen = minSide * 0.068 * env;
      const lW = minSide * 0.025 * env;

      ctx.save();
      ctx.globalAlpha = env;
      drawDuotoneLeaf(xPos, yPos, rot, lLen, lW, ld.cL, ld.cR, true);
      ctx.restore();
    }

    // 2. Soil Vessel (Grounded cleanly below falling leaves)
    drawSoilVessel(vesselIn, 0, null);

  // =========================================================================
  // SCENE 1: STRATIFIED NUTRIENT CYCLE & SPROUT BUD (6.67s – 13.33s)
  // =========================================================================
  } else if (currentScene === 1) {
    const p = sceneProgress;

    const waveBoost = easeInOutSine(mapRange(p, 0.08, 0.46)) * (1 - easeInOutSine(mapRange(p, 0.62, 0.90)));
    const budSprout = easeOutQuart(mapRange(p, 0.72, 1.0));

    drawGroundShadow(cx, shadowBaseY, minSide * 0.145, minSide * 0.013, 1);

    // 1. Emerging Forest Fern Sprout Bud strictly above center of vessel rim [0.72 -> 1.00]
    if (budSprout > 0.005) {
      const stemBot = rimTopY - minSide * 0.005;
      const stemTop = stemBot - minSide * 0.052 * budSprout;
      ctx.beginPath();
      ctx.moveTo(cx, stemBot);
      ctx.lineTo(cx, stemTop);
      ctx.strokeStyle = PALETTE.fernDeep;
      ctx.lineWidth = minSide * 0.011 * Math.min(1, budSprout * 1.4);
      ctx.lineCap = 'round';
      ctx.stroke();

      const budScale = easeOutCubic(mapRange(budSprout, 0.30, 1.0));
      if (budScale > 0.01) {
        drawDiamond(
          cx,
          stemTop - minSide * 0.016 * budScale,
          minSide * 0.015 * budScale,
          minSide * 0.022 * budScale,
          PALETTE.wheat,
          PALETTE.wheatBright
        );
      }
    }

    // 2. Soil Vessel with 5 Strictly Column-Separated Nutrient Granules (Descend -> Transform -> Ascend!)
    drawSoilVessel(1, waveBoost, (curTop, curW, curH) => {
      const colOffsets = [-0.100, -0.050, 0.0, 0.050, 0.100];

      for (let i = 0; i < colOffsets.length; i++) {
        const px = cx + colOffsets[i] * minSide;
        const stagger = Math.abs(i - 2) * 0.045;

        // Phase A: Golden compost nutrients descend cleanly into deep soil [0.06 -> 0.42]
        const downStart = 0.06 + stagger;
        const downDur = 0.30;
        if (p > downStart && p < downStart + downDur) {
          const uD = (p - downStart) / downDur;
          const env = easeInOutCubic(mapRange(uD, 0.0, 0.22)) * (1 - easeInOutCubic(mapRange(uD, 0.78, 1.0)));
          const py = lerp(curTop + curH * 0.14, curTop + curH * 0.80, easeInOutSine(uD));
          drawDiamond(px, py, minSide * 0.0085 * env, minSide * 0.0125 * env, PALETTE.wheat, PALETTE.wheatBright);
        }

        // Phase B: Enriched fertility energy granules ascend cleanly toward surface [0.40 -> 0.78]
        const upStart = 0.40 + stagger;
        const upDur = 0.30;
        if (p > upStart && p < upStart + upDur) {
          const uU = (p - upStart) / upDur;
          const env = easeInOutCubic(mapRange(uU, 0.0, 0.22)) * (1 - easeInOutCubic(mapRange(uU, 0.78, 1.0)));
          const py = lerp(curTop + curH * 0.82, curTop + curH * 0.14, easeInOutSine(uU));
          drawDiamond(px, py, minSide * 0.0095 * env, minSide * 0.014 * env, PALETTE.fernLight, PALETTE.wheatBright);
        }
      }
    });

  // =========================================================================
  // SCENE 2: LAYERED GEOMETRIC BOTANICAL BLOSSOM & CLEAN EXIT (13.33s – 20.00s)
  // =========================================================================
  } else {
    const p = sceneProgress;

    // 0.9025 - 1.00 (19.35s - 20.00s): Completely empty canvas (background only)
    if (p > 0.9025) {
      return;
    }

    const stemExtend = easeOutQuart(mapRange(p, 0.0, 0.20));
    const sideLeavesIn = easeOutQuart(mapRange(p, 0.10, 0.26));
    const outerPetalsIn = easeOutQuart(mapRange(p, 0.14, 0.32));
    const innerPetalsIn = easeOutQuart(mapRange(p, 0.20, 0.36));
    const sparkIn = easeOutCubic(mapRange(p, 0.26, 0.38));

    const sparkOut = 1 - easeInCubic(mapRange(p, 0.67, 0.74));
    const innerPetalsOut = 1 - easeInCubic(mapRange(p, 0.69, 0.77));
    const outerPetalsOut = 1 - easeInCubic(mapRange(p, 0.72, 0.80));
    const sideLeavesOut = 1 - easeInCubic(mapRange(p, 0.75, 0.82));
    const stemOut = 1 - easeInCubic(mapRange(p, 0.77, 0.84));
    const vesselOut = 1 - easeInCubic(mapRange(p, 0.80, 0.9025));

    const sideLeafVis = sideLeavesIn * sideLeavesOut;
    const outerVis = outerPetalsIn * outerPetalsOut;
    const innerVis = innerPetalsIn * innerPetalsOut;
    const sparkVis = sparkIn * sparkOut;

    const stemBotY = rimTopY - minSide * 0.005;
    const flowerCY = cy - minSide * 0.135;
    const stemStartTopY = stemBotY - minSide * 0.052;
    const stemTopY = lerp(stemBotY, lerp(stemStartTopY, flowerCY, stemExtend), stemOut);

    // Calm counter-rotation of outer vs inner blossom rings
    const bloomSpin = easeInOutSine(mapRange(p, 0.20, 0.74)) * 0.36;
    const breathMask = easeInOutCubic(mapRange(p, 0.26, 0.36)) * (1 - easeInOutCubic(mapRange(p, 0.66, 0.74)));
    const leafSway = Math.sin(loopT * 2.4) * 0.045 * breathMask;

    drawGroundShadow(cx, shadowBaseY, minSide * 0.145 * vesselOut, minSide * 0.013 * vesselOut, vesselOut);

    // 1. Central Vertical Botanical Stem
    if (stemOut > 0.01) {
      ctx.beginPath();
      ctx.moveTo(cx, stemBotY);
      ctx.lineTo(cx, stemTopY);
      ctx.strokeStyle = PALETTE.fernDeep;
      ctx.lineWidth = minSide * 0.011 * Math.min(1, stemOut * 1.4);
      ctx.lineCap = 'round';
      ctx.stroke();
    }

    // 2. Two Symmetrical Lower Fern Leaves Strictly Between Vessel Rim & Flower Petals (zero collision!)
    if (sideLeafVis > 0.005) {
      const leafNodeY = cy + minSide * 0.025;
      const leafL = minSide * 0.098 * sideLeafVis;
      const leafW = minSide * 0.032 * sideLeafVis;

      drawDuotoneLeaf(cx - minSide * 0.014, leafNodeY, -(0.98 + leafSway), leafL, leafW, PALETTE.fernDeep, PALETTE.fern, true);
      drawDuotoneLeaf(cx + minSide * 0.014, leafNodeY, 0.98 + leafSway, leafL, leafW, PALETTE.fern, PALETTE.fernLight, true);
    }

    // 3. Sculptural 3-Tier Counter-Rotating Geometric Blossom centered at (cx, flowerCY)
    // Initial bud transitions cleanly into center core disc as petals bloom outward
    const budBlend = 1 - easeOutCubic(mapRange(p, 0.06, 0.20));
    if (budBlend > 0.01) {
      drawDiamond(
        cx,
        stemTopY - minSide * 0.016 * budBlend,
        minSide * 0.015 * budBlend,
        minSide * 0.022 * budBlend,
        PALETTE.wheat,
        PALETTE.wheatBright
      );
    }

    // Outer Tier: 8 Golden Wheat Petals (Strictly clear radial sectors — zero messy overlap)
    if (outerVis > 0.005) {
      const petalCount = 8;
      const pLen = minSide * 0.088 * outerVis;
      const pW = minSide * 0.023 * outerVis;
      const pInnerOffset = minSide * 0.030 * outerVis;

      for (let i = 0; i < petalCount; i++) {
        const a = (i * Math.PI * 2) / petalCount + bloomSpin;
        ctx.save();
        ctx.translate(cx, flowerCY);
        ctx.rotate(a);
        drawDuotoneLeaf(0, -pInnerOffset, 0, pLen, pW, PALETTE.wheat, PALETTE.wheatBright, false);
        ctx.restore();
      }
    }

    // Inner Tier: 8 Alternating Sienna Petals (Offset 22.5 deg, smoothly counter-rotating!)
    if (innerVis > 0.005) {
      const petalCount = 8;
      const pLen = minSide * 0.056 * innerVis;
      const pW = minSide * 0.016 * innerVis;
      const pInnerOffset = minSide * 0.024 * innerVis;

      for (let i = 0; i < petalCount; i++) {
        const a = (i * Math.PI * 2) / petalCount + Math.PI / 8 - bloomSpin;
        ctx.save();
        ctx.translate(cx, flowerCY);
        ctx.rotate(a);
        drawDuotoneLeaf(0, -pInnerOffset, 0, pLen, pW, PALETTE.sienna, PALETTE.siennaLight, false);
        ctx.restore();
      }
    }

    // Center Blossom Core Disc (Deep Fern / Forest Fern + Oat Cream center diamond)
    const coreVis = Math.max(outerVis, innerVis);
    if (coreVis > 0.01) {
      const coreR = minSide * 0.036 * coreVis;
      ctx.save();
      ctx.beginPath();
      ctx.arc(cx, flowerCY, coreR, 0, Math.PI * 2);
      ctx.clip();
      fillDuotoneSplit(cx - coreR - 1, flowerCY - coreR - 1, coreR * 2 + 2, coreR * 2 + 2, cx, PALETTE.fernDeep, PALETTE.fern);
      ctx.restore();

      drawDiamond(cx, flowerCY, coreR * 0.44, coreR * 0.44, PALETTE.oatCream, PALETTE.wheatBright);
    }

    // 4. 4 Flanking Diamond Accents Strictly Outside Blossom Envelope
    if (sparkVis > 0.005) {
      const specs = [
        { x: cx - minSide * 0.185, y: flowerCY - minSide * 0.055, phase: 0.0 },
        { x: cx + minSide * 0.185, y: flowerCY - minSide * 0.055, phase: 1.5 },
        { x: cx - minSide * 0.165, y: flowerCY + minSide * 0.075, phase: 3.0 },
        { x: cx + minSide * 0.165, y: flowerCY + minSide * 0.075, phase: 4.5 }
      ];
      for (let i = 0; i < specs.length; i++) {
        const sp = specs[i];
        const pulse = 0.82 + 0.18 * Math.sin(loopT * 2.8 + sp.phase);
        const drift = Math.sin(loopT * 2.2 + sp.phase) * minSide * 0.007;
        drawDiamond(
          sp.x,
          sp.y + drift,
          minSide * 0.009 * sparkVis * pulse,
          minSide * 0.014 * sparkVis * pulse,
          i % 2 === 0 ? PALETTE.wheat : PALETTE.fern,
          i % 2 === 0 ? PALETTE.wheatBright : PALETTE.fernLight
        );
      }
    }

    // 5. Soil Vessel (Retracts smoothly at very end of Scene 2)
    drawSoilVessel(vesselOut, 0, null);
  }
}

// Konsep 7: Eco Tower — Arsitektur & Kota Berkelanjutan
// 2D Flat Vector Single Icon Motion | 16:9 4K Ready | 20s Seamless Loop (3 Scenes)
// Recommended Export: 3840x2160, 60fps, 100 Mbps

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;

  // Color Palette — Soft Limestone, Warm Greige, Sage Eucalyptus, Ochre Mustard & Architectural Slate (Zero Background Glow)
  const PALETTE = {
    bgTop: '#F4F2ED',
    bgBottom: '#E4DFD5',
    slateDark: '#364147',
    slateMid: '#4C5A62',
    sageDeep: '#396B59',
    sage: '#4E8A74',
    sageLight: '#73AC97',
    ochreDark: '#BF841A',
    ochre: '#D99B26',
    ochreBright: '#F0BA4F',
    facadeL: '#FAF8F4',
    facadeR: '#E6E2DA',
    glassDark: '#3E4C53',
    shadow: 'rgba(54, 65, 71, 0.075)'
  };

  // --- Easing & Math Helpers ---
  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function mapRange(v, inMin, inMax) {
    return clamp01((v - inMin) / (inMax - inMin));
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function easeInOutSine(u) {
    const x = clamp01(u);
    return -(Math.cos(Math.PI * x) - 1) * 0.5;
  }

  function easeOutCubic(u) {
    const x = 1 - clamp01(u);
    return 1 - x * x * x;
  }

  function easeInCubic(u) {
    const x = clamp01(u);
    return x * x * x;
  }

  function easeInOutCubic(u) {
    const x = clamp01(u);
    return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
  }

  function easeOutQuart(u) {
    const x = 1 - clamp01(u);
    return 1 - x * x * x * x;
  }

  function easeInOutQuart(u) {
    const x = clamp01(u);
    return x < 0.5 ? 8 * x * x * x * x : 1 - Math.pow(-2 * x + 2, 4) / 2;
  }

  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, Math.abs(w) * 0.5, Math.abs(h) * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  }

  // Seamless duotone vertical split fill inside any already-clipped region (zero center anti-alias hairline!)
  function fillDuotoneSplit(x, y, w, h, splitX, leftColor, rightColor) {
    ctx.fillStyle = leftColor;
    ctx.fillRect(x, y, w, h);
    ctx.fillStyle = rightColor;
    ctx.fillRect(splitX, y, x + w - splitX, h);
  }

  function drawDiamond(x, y, rx, ry, leftC, rightC) {
    if (rx <= 0.4 || ry <= 0.4) return;
    ctx.beginPath();
    ctx.moveTo(x, y - ry);
    ctx.lineTo(x + rx, y);
    ctx.lineTo(x, y + ry);
    ctx.lineTo(x - rx, y);
    ctx.closePath();
    ctx.save();
    ctx.clip();
    fillDuotoneSplit(x - rx - 1, y - ry - 1, rx * 2 + 2, ry * 2 + 2, x, leftC, rightC);
    ctx.restore();
  }

  function drawGroundShadow(x, y, rx, ry, alphaScale) {
    if (alphaScale <= 0.001 || rx <= 0.5 || ry <= 0.5) return;
    ctx.save();
    ctx.globalAlpha = alphaScale;
    ctx.fillStyle = PALETTE.shadow;
    ctx.beginPath();
    ctx.ellipse(x, y, rx, ry, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  // Smooth analog window pane fill with continuous highlight blend (zero flickering!)
  function drawSmoothWindow(wx, wy, ww, wh, baseColor, highlightColor, highlightIntensity) {
    const rad = minSide * 0.005;
    roundedRectPath(wx, wy, ww, wh, rad);
    ctx.fillStyle = baseColor;
    ctx.fill();

    const amt = clamp01(highlightIntensity);
    if (amt > 0.01) {
      ctx.save();
      ctx.globalAlpha = amt * 0.92;
      roundedRectPath(wx, wy, ww, wh, rad);
      ctx.fillStyle = highlightColor;
      ctx.fill();
      ctx.restore();
    }
  }

  // --- Clean Background (Flat Elegant Limestone-Greige Gradient, Strictly Zero Glow / Zero Borders) ---
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
  bgGrad.addColorStop(0, PALETTE.bgTop);
  bgGrad.addColorStop(1, PALETTE.bgBottom);
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // Shared Architectural Tower Dimensions (Exact Scene 0 -> Scene 1 Continuity)
  const baseY = cy + minSide * 0.242;
  const plinthH = minSide * 0.022;
  const tierGap = minSide * 0.008;

  const t1W = minSide * 0.285;
  const t1H = minSide * 0.112;
  const t1BotY = baseY - minSide * 0.006;
  const t1TopY = t1BotY - t1H;

  const t2W = minSide * 0.222;
  const t2H = minSide * 0.128;
  const t2BotY = t1TopY - tierGap;
  const t2TopY = t2BotY - t2H;

  const t3W = minSide * 0.168;
  const t3H = minSide * 0.104;
  const t3BotY = t2TopY - tierGap;
  const t3TopY = t3BotY - t3H;

  const shadowBaseY = cy + minSide * 0.305;
  const seedR = minSide * 0.105;

  // Exact Mathematical Circle (m=0, kappa=0.55228475) -> Architectural Shield (m=1) Morph Path
  // Guarantees 100% seamless transition with ZERO jump or snap between Scene 1 and Scene 2!
  function traceCircleToShield(centerX, centerY, scale, morphAmt) {
    const m = clamp01(morphAmt);
    const k = 0.55228475;
    const r = seedR * scale;

    // Target Shield coordinates scaled cleanly
    const shW = minSide * 0.165 * scale;
    const shTop = minSide * 0.190 * scale;
    const shShoulderY = -minSide * 0.126 * scale;
    const shBot = minSide * 0.200 * scale;

    // Interpolated anchor points (m=0 -> exact circle of radius r; m=1 -> crisp architectural shield)
    const topY = centerY - lerp(r, shTop, m);
    const rightX = centerX + lerp(r, shW, m);
    const leftX = centerX - lerp(r, shW, m);
    const sideY = centerY + lerp(0, shShoulderY, m);
    const botY = centerY + lerp(r, shBot, m);

    // Interpolated Bezier handles (m=0 -> exact quarter-circle kappa; m=1 -> refined shield curves)
    const c1x = lerp(k * r, shW * 0.44, m);
    const c1y = centerY - lerp(r, shTop - minSide * 0.012 * scale, m);
    const c2x = lerp(r, shW * 0.90, m);
    const c2y = centerY + lerp(-k * r, shShoulderY - minSide * 0.012 * scale, m);

    const c3x = lerp(r, shW, m);
    const c3y = centerY + lerp(k * r, minSide * 0.032 * scale, m);
    const c4x = lerp(k * r, shW * 0.56, m);
    const c4y = centerY + lerp(r, shBot - minSide * 0.036 * scale, m);

    ctx.beginPath();
    // Top apex -> Right shoulder
    ctx.moveTo(centerX, topY);
    ctx.bezierCurveTo(centerX + c1x, c1y, centerX + c2x, c2y, rightX, sideY);
    // Right shoulder -> Bottom point
    ctx.bezierCurveTo(centerX + c3x, c3y, centerX + c4x, c4y, centerX, botY);
    // Bottom point -> Left shoulder
    ctx.bezierCurveTo(centerX - c4x, c4y, centerX - c3x, c3y, leftX, sideY);
    // Left shoulder -> Top apex
    ctx.bezierCurveTo(centerX - c2x, c2y, centerX - c1x, c1y, centerX, topY);
    ctx.closePath();
  }

  // Reusable Architectural 3-Tier Eco-Tower Renderer (NO diagonal sweep, razor-sharp edges!)
  function drawEcoTower(plinthProg, t1Prog, t2Prog, t3Prog, waveTime) {
    // 1. Ground Architectural Plinth
    if (plinthProg > 0.005) {
      const pw = minSide * 0.355 * plinthProg;
      const ph = plinthH * Math.min(1, plinthProg * 1.4);

      ctx.save();
      roundedRectPath(cx - pw * 0.5, baseY, pw, ph, ph * 0.5);
      ctx.clip();
      fillDuotoneSplit(cx - pw * 0.5 - 1, baseY - 1, pw + 2, ph + 2, cx, PALETTE.slateDark, PALETTE.slateMid);
      ctx.restore();

      const accW = pw * 0.32;
      const accH = ph * 0.32;
      roundedRectPath(cx - accW * 0.5, baseY + (ph - accH) * 0.5, accW, accH, accH * 0.5);
      ctx.fillStyle = PALETTE.ochre;
      ctx.fill();
    }

    // Helper: true upward architectural elevation out of a clean horizontal floor-line clip mask
    function drawTierBlock(w, fullH, botY, prog, cornerR, drawInteriorFn) {
      if (prog <= 0.005) return;
      const riseOffset = (1 - prog) * (fullH + minSide * 0.004);
      const xL = cx - w * 0.5;
      const fullTopY = botY - fullH;

      ctx.save();
      ctx.beginPath();
      ctx.rect(xL - 4, fullTopY - 4, w + 8, fullH + 5);
      ctx.clip();

      ctx.translate(0, riseOffset);

      // Fill facade & clipped windows
      roundedRectPath(xL, fullTopY, w, fullH, cornerR);
      ctx.save();
      ctx.clip();

      fillDuotoneSplit(xL - 1, fullTopY - 1, w + 2, fullH + 2, cx, PALETTE.facadeL, PALETTE.facadeR);

      // Clean architectural roof cornice bar
      ctx.fillStyle = PALETTE.slateDark;
      ctx.fillRect(xL, fullTopY, w, minSide * 0.009);

      // Interior windows & portal
      drawInteriorFn(xL, fullTopY, w, fullH);
      ctx.restore();

      // Explicitly re-trace tier outline before stroking (guarantees razor-sharp architectural contour!)
      roundedRectPath(xL, fullTopY, w, fullH, cornerR);
      ctx.strokeStyle = PALETTE.slateMid;
      ctx.lineWidth = minSide * 0.0026;
      ctx.stroke();

      ctx.restore();
    }

    function waveGlow(centerOffset) {
      if (waveTime < 0) return 0;
      const dist = Math.abs(waveTime - centerOffset);
      return easeInOutSine(Math.max(0, 1 - dist / 0.42));
    }

    // Tier 1: Ground Podium
    drawTierBlock(t1W, t1H, t1BotY, t1Prog, minSide * 0.010, (xL, yT, w, h) => {
      const doorW = minSide * 0.046;
      const doorH = h * 0.64;
      roundedRectPath(cx - doorW * 0.5, yT + h - doorH, doorW, doorH + 4, minSide * 0.008);
      ctx.fillStyle = PALETTE.slateDark;
      ctx.fill();

      const inW = doorW * 0.64;
      const inH = doorH * 0.78;
      roundedRectPath(cx - inW * 0.5, yT + h - inH, inW, inH + 2, minSide * 0.005);
      ctx.fillStyle = PALETTE.sage;
      ctx.fill();

      const winW = minSide * 0.028;
      const winH = h * 0.44;
      const winY = yT + h * 0.30;
      const offsets = [-0.098, -0.056, 0.056, 0.098];
      for (let i = 0; i < offsets.length; i++) {
        const wx = cx + offsets[i] * minSide - winW * 0.5;
        drawSmoothWindow(wx, winY, winW, winH, PALETTE.glassDark, PALETTE.ochreBright, waveGlow(0.22 + i * 0.14));
      }
    });

    // Tier 2: Mid Eco-Office Block (4x2 precision glass grid)
    drawTierBlock(t2W, t2H, t2BotY, t2Prog, minSide * 0.010, (xL, yT, w, h) => {
      const cols = 4;
      const rows = 2;
      const padX = minSide * 0.022;
      const padTop = minSide * 0.024;
      const padBot = minSide * 0.016;
      const gapX = minSide * 0.014;
      const gapY = minSide * 0.014;
      const cw = (w - padX * 2 - gapX * (cols - 1)) / cols;
      const ch = (h - padTop - padBot - gapY * (rows - 1)) / rows;

      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
          const wx = xL + padX + c * (cw + gapX);
          const wy = yT + padTop + r * (ch + gapY);
          const baseC = (c + r) % 2 === 0 ? PALETTE.sage : PALETTE.glassDark;
          const hlC = (c + r) % 2 === 0 ? PALETTE.sageLight : PALETTE.ochreBright;
          drawSmoothWindow(wx, wy, cw, ch, baseC, hlC, waveGlow(0.42 + (1 - r) * 0.22 + c * 0.12));
        }
      }
    });

    // Tier 3: Upper Atrium Crown Block (3 vertical glass bays)
    drawTierBlock(t3W, t3H, t3BotY, t3Prog, minSide * 0.010, (xL, yT, w, h) => {
      const cols = 3;
      const padX = minSide * 0.020;
      const padTop = minSide * 0.024;
      const padBot = minSide * 0.016;
      const gapX = minSide * 0.013;
      const cw = (w - padX * 2 - gapX * (cols - 1)) / cols;
      const ch = h - padTop - padBot;

      for (let c = 0; c < cols; c++) {
        const wx = xL + padX + c * (cw + gapX);
        const wy = yT + padTop;
        drawSmoothWindow(wx, wy, cw, ch, PALETTE.sageDeep, PALETTE.ochreBright, waveGlow(0.86 + c * 0.14));
      }
    });
  }

  // =========================================================================
  // SCENE 0: ARCHITECTURAL ECO-TOWER ELEVATION (0.00s – 6.67s)
  // =========================================================================
  if (currentScene === 0) {
    const p = sceneProgress;

    // 0.00 - 0.0975 (0.00s - 0.65s): Completely empty canvas (background only)
    if (p < 0.0975) {
      return;
    }

    const plinthIn = easeOutQuart(mapRange(p, 0.0975, 0.22));
    const t1In = easeOutQuart(mapRange(p, 0.17, 0.31));
    const t2In = easeOutQuart(mapRange(p, 0.27, 0.41));
    const t3In = easeOutQuart(mapRange(p, 0.37, 0.51));

    // Smooth analog window efficiency wave (no sweep!)
    const waveT = p >= 0.48 && p <= 0.90 ? mapRange(p, 0.48, 0.90) * 1.65 : -1;

    // Subtle Flanking Architectural Elevation Ticks strictly outside tower width
    const guideVis = easeOutCubic(mapRange(p, 0.18, 0.30)) * (1 - easeInCubic(mapRange(p, 0.74, 0.84)));
    if (guideVis > 0.005) {
      const tierLevels = [t1TopY, t2TopY, t3TopY];
      const tickInner = t1W * 0.5 + minSide * 0.044;
      const tickLen = minSide * 0.036 * guideVis;
      const tickH = minSide * 0.0065;

      ctx.save();
      ctx.globalAlpha = guideVis * 0.72;
      for (let side = -1; side <= 1; side += 2) {
        for (let k = 0; k < 3; k++) {
          const levelProg = k === 0 ? t1In : k === 1 ? t2In : t3In;
          if (levelProg <= 0.05) continue;
          const tw = tickLen * levelProg;
          const tx = side < 0 ? cx - tickInner - tw : cx + tickInner;
          const ty = tierLevels[k] - tickH * 0.5;
          roundedRectPath(tx, ty, tw, tickH, tickH * 0.5);
          ctx.fillStyle = k === 1 ? PALETTE.ochre : PALETTE.sageLight;
          ctx.fill();
        }
      }
      ctx.restore();
    }

    drawGroundShadow(cx, shadowBaseY, minSide * 0.205 * plinthIn, minSide * 0.013 * plinthIn, plinthIn);
    drawEcoTower(plinthIn, t1In, t2In, t3In, waveT);

  // =========================================================================
  // SCENE 1: ROOFTOP GARDEN, MICRO-SOLAR & SUN PASSAGE (6.67s – 13.33s)
  // =========================================================================
  } else if (currentScene === 1) {
    const p = sceneProgress;

    const roofIn = easeOutQuart(mapRange(p, 0.02, 0.19));
    const terraceIn = easeOutQuart(mapRange(p, 0.08, 0.23));

    // Strictly ordered reverse retraction (zero floating rooftop elements!)
    const roofOut = 1 - easeInCubic(mapRange(p, 0.68, 0.76));
    const t3Out = 1 - easeInCubic(mapRange(p, 0.76, 0.82));
    const t2Out = 1 - easeInCubic(mapRange(p, 0.79, 0.85));
    const t1Out = 1 - easeInCubic(mapRange(p, 0.82, 0.88));
    const plinthOut = 1 - easeInCubic(mapRange(p, 0.85, 0.90));

    // Seamless Green Circle Seed emerges cleanly AFTER tower clears [0.90 -> 1.00]
    const seedHandoffIn = easeOutQuart(mapRange(p, 0.90, 1.0));

    const roofVis = roofIn * roofOut;
    const terraceVis = terraceIn * roofOut;

    const shRx = Math.max(minSide * 0.205 * plinthOut, minSide * 0.125 * seedHandoffIn);
    const shAlpha = Math.max(plinthOut, seedHandoffIn);
    drawGroundShadow(cx, shadowBaseY, shRx, minSide * 0.013 * shAlpha, shAlpha);

    // 1. Passing 2D Editorial Sun Arc (Strictly high above rooftop)
    const sunArcU = mapRange(p, 0.15, 0.66);
    const sunVis = easeOutCubic(mapRange(p, 0.15, 0.24)) * (1 - easeInCubic(mapRange(p, 0.58, 0.66)));
    if (sunVis > 0.01) {
      const sunX = lerp(cx - minSide * 0.22, cx + minSide * 0.22, easeInOutCubic(sunArcU));
      const sunY = cy - minSide * 0.270 - Math.sin(sunArcU * Math.PI) * minSide * 0.045;
      const sunR = minSide * 0.028 * sunVis;

      const tickCount = 8;
      const tickInR = sunR + minSide * 0.009;
      const tickLen = minSide * 0.013 * sunVis;
      const tickRot = sunArcU * Math.PI * 0.5;
      ctx.save();
      ctx.translate(sunX, sunY);
      ctx.rotate(tickRot);
      ctx.strokeStyle = PALETTE.ochre;
      ctx.lineWidth = minSide * 0.005 * sunVis;
      ctx.lineCap = 'round';
      for (let k = 0; k < tickCount; k++) {
        const a = (k * Math.PI * 2) / tickCount;
        ctx.beginPath();
        ctx.moveTo(Math.cos(a) * tickInR, Math.sin(a) * tickInR);
        ctx.lineTo(Math.cos(a) * (tickInR + tickLen), Math.sin(a) * (tickInR + tickLen));
        ctx.stroke();
      }
      ctx.restore();

      ctx.save();
      ctx.beginPath();
      ctx.arc(sunX, sunY, sunR, 0, Math.PI * 2);
      ctx.clip();
      fillDuotoneSplit(sunX - sunR - 1, sunY - sunR - 1, sunR * 2 + 2, sunR * 2 + 2, sunX, PALETTE.ochre, PALETTE.ochreBright);
      ctx.restore();
    }

    // 2. Eco-Tower Body (100% seamless continuation from Scene 0, zero diagonal sweep!)
    drawEcoTower(plinthOut, t1Out, t2Out, t3Out, -1);

    // 3. Rooftop Architectural Bonsai Garden (Left-Center) & Sun-Tracking Micro-Solar Panel (Right)
    if (roofVis > 0.005) {
      const roofBaseY = t3TopY - minSide * 0.006;

      const bedW = minSide * 0.092 * roofVis;
      const bedH = minSide * 0.014 * roofVis;
      const bedX = cx - t3W * 0.46;
      roundedRectPath(bedX, roofBaseY - bedH, bedW, bedH, bedH * 0.4);
      ctx.fillStyle = PALETTE.slateDark;
      ctx.fill();

      const bushSpecs = [
        { ox: 0.14, r: 0.0115, stem: 0.006, cL: PALETTE.sageDeep, cR: PALETTE.sage },
        { ox: 0.50, r: 0.0155, stem: 0.008, cL: PALETTE.sage, cR: PALETTE.sageLight },
        { ox: 0.86, r: 0.0115, stem: 0.006, cL: PALETTE.sageDeep, cR: PALETTE.sage }
      ];
      for (let b = 0; b < bushSpecs.length; b++) {
        const bs = bushSpecs[b];
        const bx = bedX + bedW * bs.ox;
        const br = minSide * bs.r * roofVis;
        const stemH = minSide * bs.stem * roofVis;
        const by = roofBaseY - bedH - stemH - br;

        ctx.fillStyle = PALETTE.slateMid;
        ctx.fillRect(bx - minSide * 0.0022 * roofVis, roofBaseY - bedH - stemH - 1, minSide * 0.0044 * roofVis, stemH + 1);

        ctx.save();
        ctx.beginPath();
        ctx.arc(bx, by, br, 0, Math.PI * 2);
        ctx.clip();
        fillDuotoneSplit(bx - br - 1, by - br - 1, br * 2 + 2, br * 2 + 2, bx, bs.cL, bs.cR);
        ctx.restore();
      }

      const solarCenterX = cx + t3W * 0.30;
      const strutH = minSide * 0.026 * roofVis;
      const strutW = minSide * 0.008 * roofVis;
      ctx.fillStyle = PALETTE.slateMid;
      ctx.fillRect(solarCenterX - strutW * 0.5, roofBaseY - strutH, strutW, strutH);

      const trackEnvelope = easeInOutCubic(mapRange(p, 0.10, 0.20)) * (1 - easeInOutCubic(mapRange(p, 0.62, 0.70)));
      const tiltAngle = lerp(-0.26, 0.26, easeInOutCubic(sunArcU)) * trackEnvelope;
      const spW = minSide * 0.052 * roofVis;
      const spH = minSide * 0.013 * roofVis;

      ctx.save();
      ctx.translate(solarCenterX, roofBaseY - strutH);
      ctx.rotate(tiltAngle);
      roundedRectPath(-spW * 0.5, -spH, spW, spH, spH * 0.35);
      ctx.fillStyle = PALETTE.slateDark;
      ctx.fill();

      roundedRectPath(-spW * 0.44, -spH, spW * 0.88, spH * 0.48, spH * 0.22);
      ctx.fillStyle = PALETTE.ochreBright;
      ctx.fill();
      ctx.restore();
    }

    // 4. Symmetrical Setback Terrace Greenery
    if (terraceVis > 0.005) {
      const shoulderSpecs = [
        { x: cx - (t1W + t2W) * 0.25, y: t1TopY - minSide * 0.004, r: minSide * 0.015 },
        { x: cx + (t1W + t2W) * 0.25, y: t1TopY - minSide * 0.004, r: minSide * 0.015 },
        { x: cx - (t2W + t3W) * 0.25, y: t2TopY - minSide * 0.004, r: minSide * 0.013 },
        { x: cx + (t2W + t3W) * 0.25, y: t2TopY - minSide * 0.004, r: minSide * 0.013 }
      ];
      for (let i = 0; i < shoulderSpecs.length; i++) {
        const s = shoulderSpecs[i];
        const sr = s.r * terraceVis;
        if (sr <= 0.8) continue;
        ctx.save();
        ctx.beginPath();
        ctx.arc(s.x, s.y, sr, Math.PI, 0, false);
        ctx.closePath();
        ctx.clip();
        fillDuotoneSplit(s.x - sr - 1, s.y - sr - 1, sr * 2 + 2, sr + 2, s.x, PALETTE.sage, PALETTE.sageLight);
        ctx.restore();
      }
    }

    // 5. Seamless Green Circle Seed (Uses EXACT same traceCircleToShield(m=0) & seamless fillDuotoneSplit as Scene 2!)
    if (seedHandoffIn > 0.005) {
      const span = minSide * 0.25;
      ctx.save();
      traceCircleToShield(cx, cy, seedHandoffIn, 0);
      ctx.clip();
      fillDuotoneSplit(cx - span, cy - span, span * 2, span * 2, cx, PALETTE.sage, PALETTE.sageDeep);
      ctx.restore();
    }

  // =========================================================================
  // SCENE 2: ECO-ARCHITECTURE CERTIFICATION SHIELD (13.33s – 20.00s)
  // Silky exact Circle -> Shield morph, zero center seam, zero diagonal sweep!
  // =========================================================================
  } else {
    const p = sceneProgress;

    // 0.9025 - 1.00 (19.35s - 20.00s): Completely empty canvas (background only)
    if (p > 0.9025) {
      return;
    }

    // Smooth C1 Circle (m=0) -> Architectural Shield (m=1) morph
    const shieldMorph = easeInOutQuart(mapRange(p, 0.0, 0.22));
    const plateIn = easeOutQuart(mapRange(p, 0.14, 0.28));
    const emblemIn = easeOutQuart(mapRange(p, 0.20, 0.34));
    const flankIn = easeOutCubic(mapRange(p, 0.25, 0.37));

    const flankOut = 1 - easeInCubic(mapRange(p, 0.69, 0.77));
    const emblemOut = 1 - easeInCubic(mapRange(p, 0.72, 0.81));
    const shieldScaleOut = 1 - easeInCubic(mapRange(p, 0.79, 0.9025));

    const plateVis = plateIn * shieldScaleOut;
    const emblemVis = emblemIn * emblemOut;
    const flankVis = flankIn * flankOut;

    const breathMask = easeInOutCubic(mapRange(p, 0.24, 0.34)) * (1 - easeInOutCubic(mapRange(p, 0.68, 0.78)));
    const floatY = Math.sin(loopT * 2.1) * minSide * 0.005 * breathMask;
    const shY = cy + floatY;

    drawGroundShadow(cx, shadowBaseY, minSide * 0.125 * shieldScaleOut, minSide * 0.013 * shieldScaleOut, shieldScaleOut);

    // 1. Flanking Symmetrical Architectural Balance Bars (Strictly outside shield: |x - cx| >= 0.228*minSide)
    if (flankVis > 0.005) {
      const yOffs = [-minSide * 0.048, minSide * 0.042];
      const lens = [minSide * 0.072, minSide * 0.050];
      const barH = minSide * 0.011;
      const pulse = Math.sin(p * Math.PI * 5) * minSide * 0.007;

      for (let side = -1; side <= 1; side += 2) {
        for (let k = 0; k < 2; k++) {
          const bw = lens[k] * flankVis;
          const innerX = minSide * 0.228 + k * minSide * 0.016 + pulse;
          const bx = side < 0 ? cx - innerX - bw : cx + innerX;
          const by = shY + yOffs[k] - barH * 0.5;
          roundedRectPath(bx, by, bw, barH, barH * 0.5);
          ctx.fillStyle = k === 0 ? PALETTE.ochre : PALETTE.sageLight;
          ctx.fill();
        }
      }
    }

    // 2. Outer Duotone Sage Shield Frame (100% seamless morph from Scene 1 green circle!)
    if (shieldScaleOut > 0.005) {
      const span = minSide * 0.26;
      ctx.save();
      traceCircleToShield(cx, shY, shieldScaleOut, shieldMorph);
      ctx.clip();
      fillDuotoneSplit(cx - span, shY - span, span * 2, span * 2, cx, PALETTE.sage, PALETTE.sageDeep);
      ctx.restore();
    }

    // 3. Inset Clean Inner Crest Plate (No diagonal sweep!)
    if (plateVis > 0.005) {
      const span = minSide * 0.24;
      ctx.save();
      traceCircleToShield(cx, shY, 0.80 * plateVis, shieldMorph);
      ctx.clip();
      fillDuotoneSplit(cx - span, shY - span, span * 2, span * 2, cx, PALETTE.facadeL, '#EFECE5');
      ctx.restore();
    }

    // 4. Inner Emblem: 3-Pillar Eco-Skyline + Ground Sill (Lower) & Symmetrical Harmony Leaf Crest (Upper)
    if (emblemVis > 0.005) {
      const baseLineY = shY + minSide * 0.095;

      const sillW = minSide * 0.132 * emblemVis;
      const sillH = minSide * 0.009 * emblemVis;
      roundedRectPath(cx - sillW * 0.5, baseLineY + minSide * 0.006, sillW, sillH, sillH * 0.5);
      ctx.fillStyle = PALETTE.ochre;
      ctx.fill();

      const pillars = [
        { ox: -0.044, w: 0.028, h: 0.056, c: PALETTE.slateMid },
        { ox: 0.0, w: 0.036, h: 0.084, c: PALETTE.slateDark },
        { ox: 0.044, w: 0.028, h: 0.066, c: PALETTE.slateMid }
      ];
      for (let i = 0; i < pillars.length; i++) {
        const pl = pillars[i];
        const pw = minSide * pl.w * emblemVis;
        const ph = minSide * pl.h * emblemVis;
        const px = cx + minSide * pl.ox - pw * 0.5;
        roundedRectPath(px, baseLineY - ph, pw, ph, minSide * 0.005 * emblemVis);
        ctx.fillStyle = pl.c;
        ctx.fill();
      }

      const leafOriginY = shY - minSide * 0.024;
      const symBreath = Math.sin(loopT * 2.4) * 0.045 * breathMask;
      const leafLen = minSide * 0.064 * emblemVis;
      const leafW = minSide * 0.023 * emblemVis;

      for (let side = -1; side <= 1; side += 2) {
        ctx.save();
        ctx.translate(cx + side * minSide * 0.011, leafOriginY);
        ctx.rotate(side * (0.58 + symBreath));

        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.bezierCurveTo(leafW * 1.15, -leafLen * 0.35, leafW * 0.9, -leafLen * 0.78, 0, -leafLen);
        ctx.bezierCurveTo(-leafW * 0.9, -leafLen * 0.78, -leafW * 1.15, -leafLen * 0.35, 0, 0);
        ctx.closePath();

        ctx.save();
        ctx.clip();
        fillDuotoneSplit(
          -leafW * 1.3,
          -leafLen * 1.05,
          leafW * 2.6,
          leafLen * 1.1,
          0,
          side < 0 ? PALETTE.ochre : PALETTE.sage,
          side < 0 ? PALETTE.ochreBright : PALETTE.sageLight
        );
        ctx.restore();
        ctx.restore();
      }

      drawDiamond(
        cx,
        leafOriginY - minSide * 0.056 * emblemVis,
        minSide * 0.0085 * emblemVis,
        minSide * 0.013 * emblemVis,
        PALETTE.ochre,
        PALETTE.ochreBright
      );
    }
  }
}

// Konsep 8: Bio-Cell Energy — Penyimpanan Daya Ramah Lingkungan
// 2D Flat Vector Single Icon Motion | 16:9 4K Ready | 20s Seamless Loop (3 Scenes)
// Recommended Export: 3840x2160, 60fps, 100 Mbps

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;

  // Color Palette — Crisp Mint Snow, Pale Aqua, Jade Green, Canary Sun & Deep Petrol (Zero Background Glow)
  const PALETTE = {
    bgTop: '#F1FAF7',
    bgBottom: '#D9F0E8',
    petrolDark: '#133C42',
    petrolMid: '#1F555D',
    jadeDeep: '#007C5B',
    jade: '#009B72',
    jadeBright: '#16BA8E',
    canaryDark: '#D9A71C',
    canary: '#F4C430',
    canaryBright: '#FAD966',
    snowWhite: '#FAFEFD',
    snowTint: '#E9F6F2',
    slotEmpty: '#CEE8E0',
    shadow: 'rgba(19, 60, 66, 0.075)'
  };

  // --- Easing & Math Helpers ---
  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function mapRange(v, inMin, inMax) {
    return clamp01((v - inMin) / (inMax - inMin));
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function easeOutCubic(u) {
    const x = 1 - clamp01(u);
    return 1 - x * x * x;
  }

  function easeInCubic(u) {
    const x = clamp01(u);
    return x * x * x;
  }

  function easeInOutCubic(u) {
    const x = clamp01(u);
    return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
  }

  function easeOutQuart(u) {
    const x = 1 - clamp01(u);
    return 1 - x * x * x * x;
  }

  function easeInOutQuart(u) {
    const x = clamp01(u);
    return x < 0.5 ? 8 * x * x * x * x : 1 - Math.pow(-2 * x + 2, 4) / 2;
  }

  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, Math.abs(w) * 0.5, Math.abs(h) * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  }

  function drawFourPointStar(x, y, outerR, innerR, color) {
    if (outerR <= 0.6) return;
    ctx.beginPath();
    for (let i = 0; i < 8; i++) {
      const a = (i * Math.PI) / 4 - Math.PI * 0.5;
      const r = i % 2 === 0 ? outerR : innerR;
      const px = x + Math.cos(a) * r;
      const py = y + Math.sin(a) * r;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.closePath();
    ctx.fillStyle = color;
    ctx.fill();
  }

  function drawGroundShadow(x, y, rx, ry, alphaScale) {
    if (alphaScale <= 0.001 || rx <= 0.5 || ry <= 0.5) return;
    ctx.save();
    ctx.globalAlpha = alphaScale;
    ctx.fillStyle = PALETTE.shadow;
    ctx.beginPath();
    ctx.ellipse(x, y, rx, ry, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  // --- Clean Background (Flat Crisp Mint Snow to Pale Aqua, Strictly Zero Glow / Zero Borders) ---
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
  bgGrad.addColorStop(0, PALETTE.bgTop);
  bgGrad.addColorStop(1, PALETTE.bgBottom);
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // Shared Bio-Cell Battery Architecture Dimensions (Exact continuity across all 3 Scenes!)
  const cellW = minSide * 0.245;
  const cellH = minSide * 0.378;
  const cellCY = cy + minSide * 0.018;
  const cellTopY = cellCY - cellH * 0.5;
  const cellBotY = cellCY + cellH * 0.5;
  const cellRad = minSide * 0.036;
  const wallPad = minSide * 0.023;
  const shadowBaseY = cy + minSide * 0.292;

  const innerX = cx - cellW * 0.5 + wallPad;
  const innerY = cellTopY + wallPad;
  const innerW = cellW - wallPad * 2;
  const innerH = cellH - wallPad * 2;
  const innerRad = minSide * 0.018;

  // Reusable Crisp Battery Casing & Terminal Renderer
  // Supports modular split-shell assembly (splitOffset > 0) AND unified clipped silhouette (splitOffset === 0)
  function drawBatteryCasing(scaleVal, splitOffset, capProg, sheenProg) {
    if (scaleVal <= 0.005) return;
    const curW = cellW * scaleVal;
    const curH = cellH * scaleVal;
    const curTop = cellCY - curH * 0.5;
    const curRad = cellRad * scaleVal;
    const curPad = wallPad * scaleVal;

    // 1. Positive Terminal Cap Strictly Above Top Wall (with crisp 0.006*minSide seam!)
    if (capProg > 0.005) {
      const capW = minSide * 0.104 * scaleVal;
      const capH = minSide * 0.030 * capProg * scaleVal;
      const capY = curTop - minSide * 0.006 * scaleVal - capH;

      ctx.save();
      roundedRectPath(cx - capW * 0.5, capY, capW, capH, minSide * 0.009 * scaleVal);
      ctx.clip();
      ctx.fillStyle = PALETTE.petrolDark;
      ctx.fillRect(cx - capW * 0.5, capY, capW * 0.5, capH);
      ctx.fillStyle = PALETTE.petrolMid;
      ctx.fillRect(cx, capY, capW * 0.5, capH);

      // Centered canary accent strip on terminal
      const accW = capW * 0.42;
      const accH = capH * 0.34;
      roundedRectPath(cx - accW * 0.5, capY + (capH - accH) * 0.5, accW, accH, accH * 0.5);
      ctx.fillStyle = PALETTE.canary;
      ctx.fill();
      ctx.restore();
    }

    // 2. Main Battery Casing Shell
    if (splitOffset > 0.4) {
      // Modular Left & Right Half-Shells gliding cleanly inward to meet at cx
      for (let side = -1; side <= 1; side += 2) {
        const shiftX = side * splitOffset;
        ctx.save();
        ctx.beginPath();
        if (side < 0) {
          ctx.rect(cx - curW * 0.5 + shiftX - 2, curTop - 2, curW * 0.5 + 2, curH + 4);
        } else {
          ctx.rect(cx + shiftX, curTop - 2, curW * 0.5 + 2, curH + 4);
        }
        ctx.clip();

        roundedRectPath(cx - curW * 0.5 + shiftX, curTop, curW, curH, curRad);
        ctx.fillStyle = side < 0 ? PALETTE.petrolDark : PALETTE.petrolMid;
        ctx.fill();

        roundedRectPath(
          cx - curW * 0.5 + curPad + shiftX,
          curTop + curPad,
          curW - curPad * 2,
          curH - curPad * 2,
          innerRad * scaleVal
        );
        ctx.fillStyle = side < 0 ? PALETTE.snowWhite : PALETTE.snowTint;
        ctx.fill();
        ctx.restore();
      }
    } else {
      // Unified Clipped Silhouette (Zero center anti-alias seam!)
      ctx.save();
      roundedRectPath(cx - curW * 0.5, curTop, curW, curH, curRad);
      ctx.clip();
      ctx.fillStyle = PALETTE.petrolDark;
      ctx.fillRect(cx - curW * 0.5, curTop, curW * 0.5, curH);
      ctx.fillStyle = PALETTE.petrolMid;
      ctx.fillRect(cx, curTop, curW * 0.5, curH);

      // Inset clean bright battery chamber
      const inX = cx - curW * 0.5 + curPad;
      const inY = curTop + curPad;
      const inW = curW - curPad * 2;
      const inH = curH - curPad * 2;
      roundedRectPath(inX, inY, inW, inH, innerRad * scaleVal);
      ctx.save();
      ctx.clip();
      ctx.fillStyle = PALETTE.snowWhite;
      ctx.fillRect(inX, inY, inW * 0.5, inH);
      ctx.fillStyle = PALETTE.snowTint;
      ctx.fillRect(cx, inY, inW * 0.5, inH);
      ctx.restore();

      // Optional vertical/diagonal specular sheen sweep strictly clipped to outer casing
      if (sheenProg > 0 && sheenProg < 1) {
        const sy = lerp(curTop + curH + minSide * 0.08, curTop - minSide * 0.08, sheenProg);
        const sh = minSide * 0.045;
        ctx.beginPath();
        ctx.moveTo(cx - curW * 0.6, sy + sh);
        ctx.lineTo(cx + curW * 0.6, sy - sh);
        ctx.lineTo(cx + curW * 0.6, sy - sh * 2.4);
        ctx.lineTo(cx - curW * 0.6, sy - sh * 0.4);
        ctx.closePath();
        ctx.fillStyle = 'rgba(250, 254, 253, 0.22)';
        ctx.fill();
      }

      ctx.restore();
    }
  }

  // Reusable 4-Bar Tiered Energy Slots & Liquid-Wave Fill Renderer
  function drawEnergySlots(slotVis, fillLevels, rippleBoosts) {
    if (slotVis <= 0.005) return;
    const barCount = 4;
    const padX = minSide * 0.018;
    const padY = minSide * 0.020;
    const gap = minSide * 0.014;
    const bw = innerW - padX * 2;
    const bh = (innerH - padY * 2 - gap * (barCount - 1)) / barCount;
    const bx = innerX + padX;
    const bRad = minSide * 0.010;

    const barPalettes = [
      { left: PALETTE.jadeDeep, right: PALETTE.jade, crest: PALETTE.jadeBright },
      { left: PALETTE.jade, right: PALETTE.jadeBright, crest: '#4AD7AF' },
      { left: PALETTE.jadeBright, right: '#29CCA0', crest: PALETTE.canaryBright },
      { left: PALETTE.canary, right: PALETTE.canaryBright, crest: PALETTE.snowWhite }
    ];

    for (let i = 0; i < barCount; i++) {
      // i = 0 is bottom bar, i = 3 is top bar
      const by = innerY + innerH - padY - (i + 1) * bh - i * gap;
      const curW = bw * slotVis;
      const curX = cx - curW * 0.5;

      // Empty cell track
      ctx.save();
      roundedRectPath(curX, by, curW, bh, bRad);
      ctx.fillStyle = PALETTE.slotEmpty;
      ctx.fill();

      // Liquid-wave fill strictly clipped inside this bar's rounded slot
      const fill = clamp01(fillLevels[i]);
      if (fill > 0.005) {
        ctx.clip();
        const pal = barPalettes[i];
        const surfaceY = lerp(by + bh + 2, by - 2, fill);
        const waveAmp = minSide * 0.0045 * Math.sin(fill * Math.PI);
        const phase = loopT * 4.2 + i * 1.4;

        // Build smooth wavy top fill polygon
        ctx.beginPath();
        ctx.moveTo(curX - 2, by + bh + 2);
        const steps = 20;
        for (let s = 0; s <= steps; s++) {
          const u = s / steps;
          const wx = lerp(curX - 2, curX + curW + 2, u);
          const wy = surfaceY + Math.sin(u * Math.PI * 2 + phase) * waveAmp;
          ctx.lineTo(wx, wy);
        }
        ctx.lineTo(curX + curW + 2, by + bh + 2);
        ctx.closePath();

        // Duotone fill via clip
        ctx.save();
        ctx.clip();
        ctx.fillStyle = pal.left;
        ctx.fillRect(curX - 2, by - 4, curW * 0.5 + 2, bh + 8);
        ctx.fillStyle = pal.right;
        ctx.fillRect(cx, by - 4, curW * 0.5 + 2, bh + 8);

        // Clean top liquid highlight crest while filling
        if (fill < 0.96) {
          ctx.fillStyle = pal.crest;
          ctx.fillRect(curX - 2, surfaceY - waveAmp, curW + 4, minSide * 0.004);
        }

        // Full-charge rhythmic confirmation ripple highlight
        const boost = rippleBoosts[i];
        if (boost > 0.01) {
          ctx.globalAlpha = boost * 0.35;
          ctx.fillStyle = PALETTE.snowWhite;
          ctx.fillRect(curX - 2, by - 2, curW + 4, bh + 4);
        }
        ctx.restore();
      }
      ctx.restore();
    }
  }

  // =========================================================================
  // SCENE 0: MODULAR BIO-CELL CASING ASSEMBLY (0.00s – 6.67s)
  // =========================================================================
  if (currentScene === 0) {
    const p = sceneProgress;

    // 0.00 - 0.0975 (0.00s - 0.65s): Completely empty canvas (background only)
    if (p < 0.0975) {
      return;
    }

    const shellIn = easeOutQuart(mapRange(p, 0.0975, 0.28));
    const snapClose = easeInOutQuart(mapRange(p, 0.14, 0.32));
    const capIn = easeOutQuart(mapRange(p, 0.28, 0.42));
    const slotsIn = easeOutQuart(mapRange(p, 0.38, 0.56));
    const sheenP = p >= 0.58 && p <= 0.80 ? easeInOutCubic(mapRange(p, 0.58, 0.80)) : -1;

    const splitOff = lerp(minSide * 0.075, 0, snapClose);

    // Ground shadow
    drawGroundShadow(cx, shadowBaseY, minSide * 0.145 * shellIn, minSide * 0.013 * shellIn, shellIn);

    // 1. Modular Battery Casing & Terminal Cap
    drawBatteryCasing(shellIn, splitOff, capIn, sheenP);

    // 2. Empty Cell Slots Reveal Smoothly Inside Chamber (Ready for Scene 1 Charge!)
    if (slotsIn > 0.005) {
      drawEnergySlots(slotsIn, [0, 0, 0, 0], [0, 0, 0, 0]);
    }

  // =========================================================================
  // SCENE 1: TIERED LIQUID-WAVE CELL CHARGE (6.67s – 13.33s)
  // =========================================================================
  } else if (currentScene === 1) {
    const p = sceneProgress;

    // Ground shadow exact continuity
    drawGroundShadow(cx, shadowBaseY, minSide * 0.145, minSide * 0.013, 1);

    // 1. Flanking Side Power Indicator Bars (Strictly outside battery casing: |x - cx| >= 0.172*minSide)
    const flankVis = easeOutCubic(mapRange(p, 0.14, 0.26)) * (1 - easeInCubic(mapRange(p, 0.76, 0.86)));
    if (flankVis > 0.005) {
      const barYOffs = [minSide * 0.088, minSide * 0.018, -minSide * 0.052];
      const barLens = [minSide * 0.044, minSide * 0.062, minSide * 0.044];
      const barH = minSide * 0.010;
      const innerEdge = cellW * 0.5 + minSide * 0.048;

      for (let side = -1; side <= 1; side += 2) {
        for (let k = 0; k < 3; k++) {
          const litProg = easeOutCubic(mapRange(p, 0.14 + k * 0.12, 0.24 + k * 0.12));
          const pulse = Math.sin(loopT * 3.2 - k * 0.9) * minSide * 0.005 * litProg;
          const bw = (barLens[k] + pulse) * flankVis * litProg;
          if (bw <= 1) continue;
          const bx = side < 0 ? cx - innerEdge - bw : cx + innerEdge;
          const by = cellCY + barYOffs[k] - barH * 0.5;
          roundedRectPath(bx, by, bw, barH, barH * 0.5);
          ctx.fillStyle = k === 2 ? PALETTE.canary : PALETTE.jadeBright;
          ctx.fill();
        }
      }
    }

    // 2. Battery Casing (100% seamless continuation from Scene 0)
    const sheenP = p >= 0.52 && p <= 0.72 ? easeInOutCubic(mapRange(p, 0.52, 0.72)) : -1;
    drawBatteryCasing(1, 0, 1, sheenP);

    // 3. 4 Stacked Energy Slots Fill Sequentially Bottom-to-Top, then Clear Cleanly Before Scene 2!
    const clearSlots = 1 - easeInCubic(mapRange(p, 0.82, 0.96));
    if (clearSlots > 0.005) {
      const fills = [
        easeOutQuart(mapRange(p, 0.02, 0.18)),
        easeOutQuart(mapRange(p, 0.13, 0.29)),
        easeOutQuart(mapRange(p, 0.24, 0.40)),
        easeOutQuart(mapRange(p, 0.35, 0.51))
      ];
      const rippleP = mapRange(p, 0.54, 0.74);
      const boosts = [0, 1, 2, 3].map((idx) => {
        if (rippleP <= 0 || rippleP >= 1) return 0;
        const center = 0.18 + idx * 0.21;
        return Math.max(0, 1 - Math.abs(rippleP - center) / 0.22);
      });
      drawEnergySlots(clearSlots, fills, boosts);
    }

  // =========================================================================
  // SCENE 2: SPLIT BIO-BOLT & LEAF RADIANCE + CLEAN CLOSE-OUT (13.33s – 20.00s)
  // =========================================================================
  } else {
    const p = sceneProgress;

    // 0.9025 - 1.00 (19.35s - 20.00s): Completely empty canvas (background only)
    if (p > 0.9025) {
      return;
    }

    const coreIn = easeOutQuart(mapRange(p, 0.02, 0.22));
    const sparksIn = easeOutCubic(mapRange(p, 0.16, 0.30));

    const sparksOut = 1 - easeInCubic(mapRange(p, 0.66, 0.75));
    const coreOut = 1 - easeInCubic(mapRange(p, 0.70, 0.79));
    const capOut = 1 - easeInCubic(mapRange(p, 0.75, 0.83));
    const casingOut = 1 - easeInCubic(mapRange(p, 0.79, 0.9025));

    const coreVis = coreIn * coreOut;
    const sparkVis = sparksIn * sparksOut;

    // Ground shadow fades smoothly to zero on exit
    drawGroundShadow(cx, shadowBaseY, minSide * 0.145 * casingOut, minSide * 0.013 * casingOut, casingOut);

    // 1. Symmetrical Outer Clean-Energy Stars & Capsules (Strictly clear of battery casing!)
    if (sparkVis > 0.005) {
      const starSpecs = [
        { ox: -0.205, oy: -0.115, r: 0.018, phase: 0.0, c: PALETTE.canary },
        { ox: 0.205, oy: -0.115, r: 0.018, phase: 1.1, c: PALETTE.canary },
        { ox: -0.225, oy: 0.035, r: 0.014, phase: 2.2, c: PALETTE.jadeBright },
        { ox: 0.225, oy: 0.035, r: 0.014, phase: 3.3, c: PALETTE.jadeBright },
        { ox: -0.185, oy: 0.155, r: 0.013, phase: 4.4, c: PALETTE.jade },
        { ox: 0.185, oy: 0.155, r: 0.013, phase: 5.5, c: PALETTE.jade }
      ];

      for (let i = 0; i < starSpecs.length; i++) {
        const sp = starSpecs[i];
        const pulse = 0.78 + 0.22 * Math.sin(loopT * 3.0 + sp.phase);
        const drift = Math.sin(loopT * 2.2 + sp.phase) * minSide * 0.008;
        const sx = cx + sp.ox * minSide;
        const sy = cellCY + sp.oy * minSide + drift;
        const rOut = sp.r * minSide * sparkVis * pulse;
        drawFourPointStar(sx, sy, rOut, rOut * 0.36, sp.c);
      }
    }

    // 2. Battery Casing (Cleanly continues from Scene 1, retracts cleanly on exit)
    const sheenP = p >= 0.36 && p <= 0.56 ? easeInOutCubic(mapRange(p, 0.36, 0.56)) : -1;
    drawBatteryCasing(casingOut, 0, capOut, sheenP);

    // 3. Split Bio-Bolt (Left) & Jade Eco-Leaf (Right) Strictly Inset Inside Open Battery Chamber!
    if (coreVis > 0.005) {
      const s = minSide * coreVis;
      const breathMask = easeInOutCubic(mapRange(p, 0.22, 0.32)) * (1 - easeInOutCubic(mapRange(p, 0.65, 0.72)));
      const innerFloat = Math.sin(loopT * 2.4) * minSide * 0.005 * breathMask;
      const midY = cellCY + innerFloat;

      // Left-center: Crisp 6-vertex Canary Sun Lightning Bolt (in-place scaling, strictly separated from leaf!)
      const boltX = cx - minSide * 0.036;
      ctx.save();
      ctx.translate(boltX, midY);
      ctx.beginPath();
      ctx.moveTo(s * 0.014, -s * 0.088);
      ctx.lineTo(s * 0.004, -s * 0.007);
      ctx.lineTo(s * 0.035, -s * 0.007);
      ctx.lineTo(-s * 0.014, s * 0.088);
      ctx.lineTo(-s * 0.004, s * 0.006);
      ctx.lineTo(-s * 0.035, s * 0.006);
      ctx.closePath();

      ctx.save();
      ctx.clip();
      ctx.fillStyle = PALETTE.canary;
      ctx.fillRect(-s * 0.05, -s * 0.10, s * 0.10, s * 0.20);
      ctx.fillStyle = PALETTE.canaryBright;
      ctx.fillRect(-s * 0.05, -s * 0.10, s * 0.10, s * 0.10);
      ctx.restore();
      ctx.restore();

      // Right-center: Crisp Jade Eco-Leaf (in-place scaling, generous vertical air gap from bolt & casing wall!)
      const leafX = cx + minSide * 0.038;
      const leafY = midY + minSide * 0.062;
      const sway = Math.sin(loopT * 2.6) * 0.045 * breathMask;

      ctx.save();
      ctx.translate(leafX, leafY);
      ctx.rotate(0.22 + sway);

      const leafL = s * 0.128;
      const leafW = s * 0.036;

      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.bezierCurveTo(leafW * 1.15, -leafL * 0.35, leafW * 0.9, -leafL * 0.78, 0, -leafL);
      ctx.bezierCurveTo(-leafW * 0.9, -leafL * 0.78, -leafW * 1.15, -leafL * 0.35, 0, 0);
      ctx.closePath();

      ctx.save();
      ctx.clip();
      ctx.fillStyle = PALETTE.jade;
      ctx.fillRect(-leafW * 1.3, -leafL * 1.05, leafW * 1.3, leafL * 1.1);
      ctx.fillStyle = PALETTE.jadeBright;
      ctx.fillRect(0, -leafL * 1.05, leafW * 1.3, leafL * 1.1);

      ctx.beginPath();
      ctx.moveTo(0, -leafL * 0.14);
      ctx.lineTo(0, -leafL * 0.78);
      ctx.strokeStyle = 'rgba(250, 254, 253, 0.72)';
      ctx.lineWidth = minSide * 0.0032 * coreVis;
      ctx.lineCap = 'round';
      ctx.stroke();
      ctx.restore();
      ctx.restore();
    }
  }
}

// Konsep 5: Volt Mobility — Transportasi Nol Emisi
// 2D Flat Vector Single Icon Motion | 16:9 4K Ready | 20s Seamless Loop (3 Scenes)
// Recommended Export: 3840x2160, 60fps, 100 Mbps

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;

  // Color Palette — Cool Platinum, Lavender Mist, Electric Violet, Vivid Turquoise & Deep Plum (Zero Background Glow)
  const PALETTE = {
    bgTop: '#F5F6F9',
    bgBottom: '#E7E4F3',
    plumDark: '#2A2344',
    plumMid: '#3E3563',
    violetDeep: '#5632A8',
    violet: '#6A42C2',
    violetLight: '#8B68DA',
    turquoiseDark: '#009689',
    turquoise: '#00B8A9',
    turquoiseBright: '#3CD6C9',
    iceWhite: '#FAFBFE',
    lavenderTint: '#DDD9EE',
    shadow: 'rgba(42, 35, 68, 0.075)'
  };

  // --- Easing & Math Helpers ---
  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function mapRange(v, inMin, inMax) {
    return clamp01((v - inMin) / (inMax - inMin));
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function easeInOutSine(u) {
    const x = clamp01(u);
    return -(Math.cos(Math.PI * x) - 1) * 0.5;
  }

  function easeOutCubic(u) {
    const x = 1 - clamp01(u);
    return 1 - x * x * x;
  }

  function easeInCubic(u) {
    const x = clamp01(u);
    return x * x * x;
  }

  function easeInOutCubic(u) {
    const x = clamp01(u);
    return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
  }

  function easeOutQuart(u) {
    const x = 1 - clamp01(u);
    return 1 - x * x * x * x;
  }

  function easeInOutQuart(u) {
    const x = clamp01(u);
    return x < 0.5 ? 8 * x * x * x * x : 1 - Math.pow(-2 * x + 2, 4) / 2;
  }

  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, Math.abs(w) * 0.5, Math.abs(h) * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  }

  function drawGroundShadow(x, y, rx, ry, alphaScale) {
    if (alphaScale <= 0.001 || rx <= 0.5 || ry <= 0.5) return;
    ctx.save();
    ctx.globalAlpha = alphaScale;
    ctx.fillStyle = PALETTE.shadow;
    ctx.beginPath();
    ctx.ellipse(x, y, rx, ry, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  function cubicPoint(p0, p1, p2, p3, u) {
    const inv = 1 - u;
    const inv2 = inv * inv;
    const inv3 = inv2 * inv;
    const u2 = u * u;
    const u3 = u2 * u;
    return {
      x: inv3 * p0.x + 3 * inv2 * u * p1.x + 3 * inv * u2 * p2.x + u3 * p3.x,
      y: inv3 * p0.y + 3 * inv2 * u * p1.y + 3 * inv * u2 * p2.y + u3 * p3.y
    };
  }

  function strokeCubicTrim(p0, p1, p2, p3, u0, u1, strokeColor, strokeW, alpha) {
    if (u1 - u0 <= 0.004 || alpha <= 0.005) return;
    const steps = 36;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.beginPath();
    for (let s = 0; s <= steps; s++) {
      const u = lerp(u0, u1, s / steps);
      const pt = cubicPoint(p0, p1, p2, p3, u);
      if (s === 0) ctx.moveTo(pt.x, pt.y);
      else ctx.lineTo(pt.x, pt.y);
    }
    ctx.strokeStyle = strokeColor;
    ctx.lineWidth = strokeW;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.stroke();
    ctx.restore();
  }

  function traceHexagonPath(centerX, centerY, radius, cornerSmooth) {
    const pts = [];
    for (let i = 0; i < 6; i++) {
      const a = -Math.PI * 0.5 + (i * Math.PI) / 3;
      pts.push({ x: centerX + Math.cos(a) * radius, y: centerY + Math.sin(a) * radius });
    }
    ctx.beginPath();
    const cs = clamp01(cornerSmooth) * 0.18;
    for (let i = 0; i < 6; i++) {
      const prev = pts[(i + 5) % 6];
      const curr = pts[i];
      const next = pts[(i + 1) % 6];
      const pA = { x: lerp(curr.x, prev.x, cs), y: lerp(curr.y, prev.y, cs) };
      const pB = { x: lerp(curr.x, next.x, cs), y: lerp(curr.y, next.y, cs) };
      if (i === 0) ctx.moveTo(pA.x, pA.y);
      else ctx.lineTo(pA.x, pA.y);
      ctx.quadraticCurveTo(curr.x, curr.y, pB.x, pB.y);
    }
    ctx.closePath();
  }

  // --- Clean Background (Flat Cool Platinum to Lavender Mist, Strictly Zero Glow / Zero Borders) ---
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
  bgGrad.addColorStop(0, PALETTE.bgTop);
  bgGrad.addColorStop(1, PALETTE.bgBottom);
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // Shared Architectural Layout Geometry
  const roadY = cy + minSide * 0.155;
  const roadFullW = minSide * 0.62;
  const roadH = minSide * 0.009;
  const hexSeedR = minSide * 0.135;
  const shadowBaseY = cy + minSide * 0.268;

  // =========================================================================
  // SCENE 0: EV CHARGING PLUG, DOCKING & POWER PULSE (0.00s – 6.67s)
  // Clean sequenced entry, true recessed socket docking, zero-overlap exit to Road Bar
  // =========================================================================
  if (currentScene === 0) {
    const p = sceneProgress;

    // 0.00 - 0.0975 (0.00s - 0.65s): Completely empty canvas (background only)
    if (p < 0.0975) {
      return;
    }

    const portIn = easeOutQuart(mapRange(p, 0.0975, 0.22));
    const plugIn = easeOutQuart(mapRange(p, 0.13, 0.25));
    const cableDraw = easeOutQuart(mapRange(p, 0.16, 0.29));
    const dockMove = easeInOutQuart(mapRange(p, 0.30, 0.43));

    // Clean reverse exit (zero ghosting / zero crossfade overlap!)
    const cableRetract = easeInOutQuart(mapRange(p, 0.72, 0.82));
    const undockMove = easeInOutCubic(mapRange(p, 0.75, 0.83));
    const plugOut = 1 - easeInCubic(mapRange(p, 0.78, 0.86));
    const portOut = 1 - easeInCubic(mapRange(p, 0.80, 0.88));

    // Scene 1 road bar unfolds cleanly AFTER charging assembly finishes clearing [0.88 -> 1.00]
    const roadHandoffIn = easeOutQuart(mapRange(p, 0.88, 1.0));

    const portVis = portIn * portOut;
    const plugVis = plugIn * plugOut;
    const activeDock = dockMove * (1 - undockMove);

    // Ground shadow smoothly transitions from charging assembly to Scene 1 road bar
    const shRx = Math.max(minSide * 0.19 * Math.max(portVis, plugVis), minSide * 0.22 * roadHandoffIn);
    const shAlpha = Math.max(portVis, plugVis, roadHandoffIn);
    drawGroundShadow(cx, shadowBaseY, shRx, minSide * 0.013 * shAlpha, shAlpha);

    // Fixed architectural dimensions
    const portW = minSide * 0.148;
    const portH = minSide * 0.198;
    const portCenterX = cx + minSide * 0.138;
    const portLeftX = portCenterX - portW * 0.5;

    const plugW = minSide * 0.104;
    const plugH = minSide * 0.084;
    const prongLen = minSide * 0.032;
    const bezelW = minSide * 0.014;
    const socketFaceX = portLeftX - bezelW;

    const plugRestFrontX = socketFaceX - prongLen - minSide * 0.048;
    const plugDockedFrontX = socketFaceX - minSide * 0.004;
    const plugFrontX = lerp(plugRestFrontX, plugDockedFrontX, activeDock);
    const plugLeftX = plugFrontX - plugW;

    // 1. Sleek S-Curve Charging Cable (Left to Plug Rear Collar — Zero-Pop Trim Path)
    const cableHeadU = cableDraw;
    const cableTailU = cableRetract;
    const cableAlpha = easeOutCubic(mapRange(p, 0.16, 0.22)) * (1 - easeInCubic(mapRange(p, 0.78, 0.83)));
    if (cableHeadU > cableTailU + 0.005 && cableAlpha > 0.01) {
      const p0 = { x: cx - minSide * 0.39, y: cy + minSide * 0.088 };
      const p1 = { x: cx - minSide * 0.28, y: cy + minSide * 0.088 };
      const p2 = { x: plugLeftX - minSide * 0.095, y: cy };
      const p3 = { x: plugLeftX + minSide * 0.006, y: cy };

      strokeCubicTrim(p0, p1, p2, p3, cableTailU, cableHeadU, PALETTE.plumDark, minSide * 0.021, cableAlpha);
      strokeCubicTrim(p0, p1, p2, p3, cableTailU, cableHeadU, PALETTE.violet, minSide * 0.007, cableAlpha);

      // Two silky zero-pop Turquoise energy pulses traveling cleanly along cable into docked plug
      const pulseStarts = [0.43, 0.56];
      const pulseDur = 0.15;
      for (let k = 0; k < pulseStarts.length; k++) {
        const ps = pulseStarts[k];
        if (p > ps && p < ps + pulseDur) {
          const uP = (p - ps) / pulseDur;
          const hU = easeInOutSine(mapRange(uP, 0.0, 0.70));
          const tU = easeInOutSine(mapRange(uP, 0.30, 1.0));
          const env = easeInOutCubic(mapRange(uP, 0.0, 0.18)) * (1 - easeInOutCubic(mapRange(uP, 0.82, 1.0)));
          strokeCubicTrim(p0, p1, p2, p3, tU, hU, PALETTE.turquoiseBright, minSide * 0.0095, env * cableAlpha);
        }
      }
    }

    // 2. Charging Plug & Dual Prongs (Prongs clip cleanly into socket bezel — zero distortion!)
    if (plugVis > 0.005) {
      const curW = plugW * plugVis;
      const curH = plugH * plugVis;
      const curLeft = plugFrontX - curW;
      const curTop = cy - curH * 0.5;

      // Dual Prongs strictly clipped to the left of socketFaceX so they slide physically into the receptacle!
      ctx.save();
      ctx.beginPath();
      ctx.rect(0, 0, socketFaceX + 1, height);
      ctx.clip();

      const prongH = minSide * 0.012 * plugVis;
      const prongGap = minSide * 0.032 * plugVis;
      const curProngLen = prongLen * plugVis;
      roundedRectPath(plugFrontX - 2, cy - prongGap * 0.5 - prongH * 0.5, curProngLen + 2, prongH, prongH * 0.4);
      ctx.fillStyle = PALETTE.turquoise;
      ctx.fill();
      roundedRectPath(plugFrontX - 2, cy + prongGap * 0.5 - prongH * 0.5, curProngLen + 2, prongH, prongH * 0.4);
      ctx.fillStyle = PALETTE.turquoise;
      ctx.fill();
      ctx.restore();

      // Unified Clipped Duotone Plug Body
      ctx.save();
      roundedRectPath(curLeft, curTop, curW, curH, minSide * 0.016 * plugVis);
      ctx.clip();
      ctx.fillStyle = PALETTE.violet;
      ctx.fillRect(curLeft, curTop, curW, curH * 0.5);
      ctx.fillStyle = PALETTE.violetDeep;
      ctx.fillRect(curLeft, cy, curW, curH * 0.5);
      ctx.restore();

      // Crisp rear collar band inset cleanly on plug back
      const colW = curW * 0.19;
      roundedRectPath(curLeft + curW * 0.10, curTop + curH * 0.18, colW, curH * 0.64, colW * 0.4);
      ctx.fillStyle = PALETTE.plumDark;
      ctx.fill();
    }

    // 3. EV Charging Socket / Power Port Station
    if (portVis > 0.005) {
      const curW = portW * portVis;
      const curH = portH * portVis;
      const curLeft = portCenterX - curW * 0.5;
      const curTop = cy - curH * 0.5;

      // Left socket bezel lip (receives the prongs cleanly)
      const curBezelW = bezelW * portVis;
      const curBezelH = plugH * 0.92 * portVis;
      roundedRectPath(curLeft - curBezelW + 2, cy - curBezelH * 0.5, curBezelW + 2, curBezelH, minSide * 0.008 * portVis);
      ctx.fillStyle = PALETTE.plumDark;
      ctx.fill();

      // Main architectural vertical housing
      ctx.save();
      roundedRectPath(curLeft, curTop, curW, curH, minSide * 0.024 * portVis);
      ctx.clip();
      ctx.fillStyle = PALETTE.plumDark;
      ctx.fillRect(curLeft, curTop, curW * 0.5, curH);
      ctx.fillStyle = PALETTE.plumMid;
      ctx.fillRect(curLeft + curW * 0.5, curTop, curW * 0.5, curH);
      ctx.restore();

      // Inset Bright Charge Meter Display
      const pad = minSide * 0.022 * portVis;
      const scrX = curLeft + pad;
      const scrY = curTop + pad;
      const scrW = Math.max(0, curW - pad * 2);
      const scrH = Math.max(0, curH - pad * 2);

      if (scrW > 2 && scrH > 2) {
        roundedRectPath(scrX, scrY, scrW, scrH, minSide * 0.012 * portVis);
        ctx.fillStyle = PALETTE.iceWhite;
        ctx.fill();

        const bPadX = scrW * 0.18;
        const bPadY = scrH * 0.15;
        const bGap = scrH * 0.09;
        const bW = scrW - bPadX * 2;
        const bH = (scrH - bPadY * 2 - bGap * 2) / 3;

        for (let b = 0; b < 3; b++) {
          const by = scrY + scrH - bPadY - (b + 1) * bH - b * bGap;
          const fillProg = easeOutCubic(mapRange(p, 0.47 + b * 0.075, 0.56 + b * 0.075));

          roundedRectPath(scrX + bPadX, by, bW, bH, bH * 0.45);
          ctx.fillStyle = PALETTE.lavenderTint;
          ctx.fill();

          if (fillProg > 0.01) {
            roundedRectPath(scrX + bPadX, by, bW * fillProg, bH, bH * 0.45);
            ctx.fillStyle = b === 2 ? PALETTE.turquoiseBright : PALETTE.turquoise;
            ctx.fill();
          }
        }
      }
    }

    // 4. Clean Scene 1 Handoff: Road Bar unfolds smoothly from center after charging station clears
    if (roadHandoffIn > 0.005) {
      const rw = roadFullW * roadHandoffIn;
      roundedRectPath(cx - rw * 0.5, roadY, rw, roadH, roadH * 0.5);
      ctx.fillStyle = PALETTE.plumDark;
      ctx.fill();
    }

  // =========================================================================
  // SCENE 1: SLEEK 2D ELECTRIC VEHICLE & CLEAN ECO-BREEZE (6.67s – 13.33s)
  // Baked vector wheel-arch cutouts (zero overlap), smooth C1 cruise, clean exit to Hexagon Seed
  // =========================================================================
  } else if (currentScene === 1) {
    const p = sceneProgress;

    // Sequenced clean entry: wheels first -> EV body rises cleanly into place -> cruise -> body & wheels retract -> hex blooms!
    const wheelsIn = easeOutQuart(mapRange(p, 0.0, 0.14));
    const bodyReveal = easeOutQuart(mapRange(p, 0.08, 0.24));

    const bodyRetract = 1 - easeInCubic(mapRange(p, 0.77, 0.85));
    const wheelsOut = 1 - easeInCubic(mapRange(p, 0.80, 0.88));
    const roadOut = 1 - easeInCubic(mapRange(p, 0.83, 0.90));
    const hexHandoffIn = easeOutQuart(mapRange(p, 0.90, 1.0));

    const wheelVis = wheelsIn * wheelsOut;
    const bodyVis = bodyReveal * bodyRetract;
    const roadVis = roadOut;

    // Smooth C1 driving motion across [0.18 -> 0.78] (exactly 3 full wheel revolutions)
    const driveU = easeInOutCubic(mapRange(p, 0.18, 0.78));
    const wheelAngle = driveU * Math.PI * 6;
    const roadScroll = driveU * 4.5;

    // Subtle balanced suspension ride on body only while wheels stay tangent on roadY
    const rideMask = easeInOutCubic(mapRange(p, 0.20, 0.29)) * (1 - easeInOutCubic(mapRange(p, 0.70, 0.78)));
    const bodyFloat = Math.sin(loopT * 4.8) * (minSide * 0.003) * rideMask;

    const wheelFullR = minSide * 0.048;
    const wheelR = wheelFullR * wheelVis;
    const wheelCenterY = roadY - wheelFullR;
    const wheelOffsetX = minSide * 0.130;

    // Ground shadow seamless from Scene 0 -> Scene 1 -> Scene 2
    const shRx = Math.max(minSide * 0.22 * roadVis, minSide * 0.125 * hexHandoffIn);
    const shAlpha = Math.max(roadVis, hexHandoffIn);
    drawGroundShadow(cx, shadowBaseY, shRx, minSide * 0.013 * shAlpha, shAlpha);

    // 1. Minimalist Road Surface & Zero-Pop Scrolling Dashes
    if (roadVis > 0.005) {
      const rw = roadFullW * roadVis;
      roundedRectPath(cx - rw * 0.5, roadY, rw, roadH, roadH * 0.5);
      ctx.fillStyle = PALETTE.plumDark;
      ctx.fill();

      const dashVis = easeOutCubic(mapRange(p, 0.12, 0.22)) * (1 - easeInCubic(mapRange(p, 0.74, 0.82)));
      if (dashVis > 0.01) {
        const dashY = roadY + minSide * 0.028;
        const dashH = minSide * 0.008;
        const dashW = minSide * 0.056;
        const trackHalfW = minSide * 0.275;
        const dashCount = 4;

        for (let d = 0; d < dashCount; d++) {
          const uDash = (d / dashCount - (roadScroll % 1) + 1) % 1;
          const dx = lerp(cx - trackHalfW, cx + trackHalfW, uDash) - dashW * 0.5;
          const edgeFade = clamp01(Math.sin(uDash * Math.PI) * 2.4);
          const alpha = edgeFade * dashVis;
          if (alpha > 0.02) {
            ctx.save();
            ctx.globalAlpha = alpha;
            roundedRectPath(dx, dashY, dashW, dashH, dashH * 0.5);
            ctx.fillStyle = d % 2 === 0 ? PALETTE.violetLight : PALETTE.turquoise;
            ctx.fill();
            ctx.restore();
          }
        }
      }
    }

    // 2. Zero-Pop Clean-Air Streamlines + Eco-Leaves Strictly Behind Rear Bumper (x <= cx - 0.255 * minSide)
    const airLanes = [
      { yOff: -minSide * 0.012, color: PALETTE.turquoise, starts: [0.22, 0.47] },
      { yOff: minSide * 0.052, color: PALETTE.violetLight, starts: [0.30, 0.54] }
    ];
    const airDur = 0.22;
    const airStartX = cx - minSide * 0.255; // Rear bumper is at cx - 0.215*minSide -> 0.04*minSide open gap!
    const airEndX = cx - minSide * 0.465;

    ctx.save();
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    for (let l = 0; l < airLanes.length; l++) {
      const lane = airLanes[l];
      for (let k = 0; k < lane.starts.length; k++) {
        const ts = lane.starts[k];
        if (p <= ts || p >= ts + airDur) continue;
        const uA = (p - ts) / airDur;
        const hU = easeInOutSine(mapRange(uA, 0.0, 0.72));
        const tU = easeInOutSine(mapRange(uA, 0.28, 1.0));
        if (hU - tU <= 0.005) continue;
        const alpha = easeInOutCubic(mapRange(uA, 0.0, 0.18)) * (1 - easeInOutCubic(mapRange(uA, 0.82, 1.0)));
        const steps = 28;
        ctx.beginPath();
        for (let s = 0; s <= steps; s++) {
          const u = lerp(tU, hU, s / steps);
          const ax = lerp(airStartX, airEndX, u);
          const ay = cy + lane.yOff - u * minSide * 0.022 + Math.sin(u * Math.PI * 1.5) * minSide * 0.009;
          if (s === 0) ctx.moveTo(ax, ay);
          else ctx.lineTo(ax, ay);
        }
        ctx.strokeStyle = lane.color;
        ctx.lineWidth = minSide * 0.0085 * (0.5 + 0.5 * alpha);
        ctx.globalAlpha = alpha;
        ctx.stroke();
      }
    }
    ctx.restore();

    // Two calm zero-pop turquoise eco-leaves drifting strictly in clean space behind car
    const leafStarts = [0.26, 0.48];
    const leafDur = 0.24;
    for (let l = 0; l < leafStarts.length; l++) {
      const ls = leafStarts[l];
      if (p > ls && p < ls + leafDur) {
        const uL = (p - ls) / leafDur;
        const travel = easeOutCubic(uL);
        const env = easeInOutCubic(mapRange(uL, 0.0, 0.20)) * (1 - easeInOutCubic(mapRange(uL, 0.78, 1.0)));
        const lx = lerp(cx - minSide * 0.262, cx - minSide * 0.435, travel);
        const ly = cy + minSide * (0.022 - l * 0.024) - travel * minSide * 0.058 + Math.sin(uL * Math.PI * 1.5) * minSide * 0.010;
        const lSize = minSide * 0.028 * env;

        if (lSize > 1) {
          ctx.save();
          ctx.globalAlpha = env;
          ctx.translate(lx, ly);
          ctx.rotate(-0.62 - travel * 0.35);
          ctx.beginPath();
          ctx.moveTo(0, 0);
          ctx.quadraticCurveTo(lSize * 0.52, -lSize * 0.5, 0, -lSize * 1.12);
          ctx.quadraticCurveTo(-lSize * 0.52, -lSize * 0.5, 0, 0);
          ctx.closePath();
          ctx.save();
          ctx.clip();
          ctx.fillStyle = PALETTE.turquoise;
          ctx.fillRect(-lSize, -lSize * 1.3, lSize, lSize * 1.4);
          ctx.fillStyle = PALETTE.turquoiseBright;
          ctx.fillRect(0, -lSize * 1.3, lSize, lSize * 1.4);
          ctx.restore();
          ctx.restore();
        }
      }
    }

    // 3. Sleek 2D Flat Vector EV Car Body with True Baked Concentric Wheel-Arch Cutouts (Zero Overlap!)
    if (bodyVis > 0.005) {
      const halfLen = minSide * 0.215;
      const bodyBaseY = wheelCenterY + bodyFloat;
      const bodyTopY = cy - minSide * 0.015 + bodyFloat;
      const cabinTopY = cy - minSide * 0.108 + bodyFloat;
      const archR = wheelFullR + minSide * 0.012; // Crisp uniform 0.012*minSide concentric clearance around tires!

      // Reveal vertically upward from bodyBaseY via clean architectural clip mask
      const revealTopY = lerp(bodyBaseY, cabinTopY - minSide * 0.01, bodyVis);

      ctx.save();
      ctx.beginPath();
      ctx.rect(cx - halfLen - 4, revealTopY, halfLen * 2 + 8, bodyBaseY - revealTopY + 2);
      ctx.clip();

      // Unified EV Body Path with exact circular wheel arches baked directly into bottom contour
      ctx.beginPath();
      ctx.moveTo(cx - halfLen + minSide * 0.016, bodyBaseY);
      // Rear lower bumper corner up to rear deck
      ctx.quadraticCurveTo(cx - halfLen, bodyBaseY, cx - halfLen, bodyBaseY - minSide * 0.018);
      ctx.lineTo(cx - halfLen, bodyTopY + minSide * 0.022);
      ctx.quadraticCurveTo(cx - halfLen, bodyTopY, cx - halfLen * 0.72, bodyTopY);
      // Slept fastback rear roofline
      ctx.quadraticCurveTo(cx - halfLen * 0.50, cabinTopY, cx - halfLen * 0.24, cabinTopY);
      // Cabin roof to sloped windshield
      ctx.lineTo(cx + halfLen * 0.16, cabinTopY);
      ctx.quadraticCurveTo(cx + halfLen * 0.42, cabinTopY, cx + halfLen * 0.62, bodyTopY);
      // Sculpted aerodynamic hood & front nose
      ctx.lineTo(cx + halfLen * 0.90, bodyTopY + minSide * 0.010);
      ctx.quadraticCurveTo(cx + halfLen, bodyTopY + minSide * 0.018, cx + halfLen, bodyBaseY - minSide * 0.018);
      ctx.quadraticCurveTo(cx + halfLen, bodyBaseY, cx + halfLen - minSide * 0.016, bodyBaseY);
      // Front wheel-arch cutout (clean concentric arc over front wheel)
      ctx.lineTo(cx + wheelOffsetX + archR, bodyBaseY);
      ctx.arc(cx + wheelOffsetX, bodyBaseY, archR, 0, Math.PI, true);
      // Center rocker sill between wheels
      ctx.lineTo(cx - wheelOffsetX + archR, bodyBaseY);
      // Rear wheel-arch cutout (clean concentric arc over rear wheel)
      ctx.arc(cx - wheelOffsetX, bodyBaseY, archR, 0, Math.PI, true);
      ctx.closePath();

      ctx.save();
      ctx.clip();

      // Duotone Electric Violet paintwork
      ctx.fillStyle = PALETTE.violet;
      ctx.fillRect(cx - halfLen - 2, cabinTopY - 2, halfLen * 2 + 4, (bodyBaseY - cabinTopY) * 0.66);
      ctx.fillStyle = PALETTE.violetDeep;
      ctx.fillRect(cx - halfLen - 2, bodyTopY + minSide * 0.048, halfLen * 2 + 4, bodyBaseY - bodyTopY);

      // Crisp upper shoulder highlight strip
      ctx.fillStyle = PALETTE.violetLight;
      ctx.fillRect(cx - halfLen - 2, bodyTopY, halfLen * 2 + 4, minSide * 0.0095);

      // Panoramic Dark Plum Cabin Glass
      const winBot = bodyTopY - minSide * 0.005;
      const winTop = cabinTopY + minSide * 0.017;
      ctx.beginPath();
      ctx.moveTo(cx - halfLen * 0.54, winBot);
      ctx.lineTo(cx - halfLen * 0.27, winTop);
      ctx.lineTo(cx + halfLen * 0.15, winTop);
      ctx.lineTo(cx + halfLen * 0.47, winBot);
      ctx.closePath();
      ctx.fillStyle = PALETTE.plumDark;
      ctx.fill();

      // Diagonal glass specular reflection + crisp B-pillar divider
      ctx.save();
      ctx.clip();
      ctx.beginPath();
      ctx.moveTo(cx - halfLen * 0.01, winTop);
      ctx.lineTo(cx + halfLen * 0.14, winTop);
      ctx.lineTo(cx - halfLen * 0.02, winBot);
      ctx.lineTo(cx - halfLen * 0.17, winBot);
      ctx.closePath();
      ctx.fillStyle = 'rgba(250, 251, 254, 0.28)';
      ctx.fill();

      ctx.fillStyle = PALETTE.violet;
      ctx.fillRect(cx - halfLen * 0.06, winTop, minSide * 0.0085, winBot - winTop + 2);
      ctx.restore();

      // Crisp Turquoise LED Front Headlamp Bar
      const ledH = minSide * 0.0115;
      roundedRectPath(cx + halfLen * 0.78, bodyTopY + minSide * 0.022, halfLen * 0.23, ledH, ledH * 0.5);
      ctx.fillStyle = PALETTE.turquoiseBright;
      ctx.fill();

      // Clean Lower Door Turquoise Accent Strip strictly centered between arches
      const trimW = minSide * 0.115;
      const trimH = minSide * 0.008;
      roundedRectPath(cx - trimW * 0.5, bodyTopY + minSide * 0.056, trimW, trimH, trimH * 0.5);
      ctx.fillStyle = PALETTE.turquoise;
      ctx.fill();

      ctx.restore();
      ctx.restore();
    }

    // 4. Precision 2D Flat Vector Rotating Wheels (Strictly tangent on roadY, concentric inside baked arches!)
    if (wheelVis > 0.01) {
      for (let side = -1; side <= 1; side += 2) {
        const wx = cx + side * wheelOffsetX;
        const wy = wheelCenterY;

        ctx.save();
        ctx.translate(wx, wy);

        ctx.beginPath();
        ctx.arc(0, 0, wheelR, 0, Math.PI * 2);
        ctx.fillStyle = PALETTE.plumDark;
        ctx.fill();

        ctx.beginPath();
        ctx.arc(0, 0, wheelR * 0.62, 0, Math.PI * 2);
        ctx.fillStyle = PALETTE.iceWhite;
        ctx.fill();

        ctx.rotate(wheelAngle);
        const spokeL = wheelR * 0.50;
        const spokeW = wheelR * 0.18;
        ctx.fillStyle = PALETTE.turquoise;
        roundedRectPath(-spokeL, -spokeW * 0.5, spokeL * 2, spokeW, spokeW * 0.5);
        ctx.fill();
        roundedRectPath(-spokeW * 0.5, -spokeL, spokeW, spokeL * 2, spokeW * 0.5);
        ctx.fill();

        ctx.beginPath();
        ctx.arc(0, 0, wheelR * 0.22, 0, Math.PI * 2);
        ctx.fillStyle = PALETTE.violet;
        ctx.fill();

        ctx.restore();
      }
    }

    // 5. Clean Scene 2 Handoff: Hexagon Seed blooms cleanly at center AFTER car & road clear [0.90 -> 1.00]
    if (hexHandoffIn > 0.005) {
      const curR = hexSeedR * hexHandoffIn;
      ctx.save();
      traceHexagonPath(cx, cy, curR, 0.55);
      ctx.clip();
      ctx.fillStyle = PALETTE.violet;
      ctx.fillRect(cx - curR, cy - curR, curR, curR * 2);
      ctx.fillStyle = PALETTE.violetDeep;
      ctx.fillRect(cx, cy - curR, curR, curR * 2);
      ctx.restore();
    }

  // =========================================================================
  // SCENE 2: HEXAGONAL CLEAN-VOLT EMBLEM (13.33s – 20.00s)
  // =========================================================================
  } else {
    const p = sceneProgress;

    // 0.9025 - 1.00 (19.35s - 20.00s): Completely empty canvas (background only)
    if (p > 0.9025) {
      return;
    }

    const hexExpand = easeOutQuart(mapRange(p, 0.0, 0.20));
    const plateIn = easeOutQuart(mapRange(p, 0.08, 0.24));
    const emblemIn = easeOutQuart(mapRange(p, 0.16, 0.32));
    const flankIn = easeOutCubic(mapRange(p, 0.22, 0.35));

    const flankOut = 1 - easeInCubic(mapRange(p, 0.69, 0.77));
    const emblemOut = 1 - easeInCubic(mapRange(p, 0.72, 0.81));
    const hexScaleOut = 1 - easeInCubic(mapRange(p, 0.79, 0.9025));

    const plateVis = plateIn * hexScaleOut;
    const emblemVis = emblemIn * emblemOut;
    const flankVis = flankIn * flankOut;

    const breathMask = easeInOutCubic(mapRange(p, 0.22, 0.34)) * (1 - easeInOutCubic(mapRange(p, 0.68, 0.78)));
    const floatY = Math.sin(loopT * 2.2) * minSide * 0.0055 * breathMask;
    const hexCenterY = cy + floatY;
    const outerR = lerp(hexSeedR, minSide * 0.205, hexExpand) * hexScaleOut;

    // Ground shadow
    drawGroundShadow(cx, shadowBaseY, minSide * 0.125 * hexScaleOut, minSide * 0.013 * hexScaleOut, hexScaleOut);

    // 1. Flanking Symmetrical Clean-Volt Chevrons (Strictly outside outer hexagon: |x - cx| >= 0.252*minSide)
    if (flankVis > 0.005) {
      const pulse = Math.sin(p * Math.PI * 5) * minSide * 0.008;
      const chevThick = minSide * 0.012 * flankVis;

      for (let side = -1; side <= 1; side += 2) {
        for (let k = 0; k < 2; k++) {
          const baseDist = minSide * 0.252 + k * minSide * 0.032 + pulse;
          const xTip = cx + side * (baseDist + minSide * 0.022);
          const xBack = cx + side * baseDist;
          const halfH = minSide * (0.044 - k * 0.010) * flankVis;

          ctx.beginPath();
          ctx.moveTo(xBack, hexCenterY - halfH);
          ctx.lineTo(xTip, hexCenterY);
          ctx.lineTo(xBack, hexCenterY + halfH);
          ctx.strokeStyle = k === 0 ? PALETTE.turquoise : PALETTE.violetLight;
          ctx.lineWidth = chevThick;
          ctx.lineCap = 'round';
          ctx.lineJoin = 'round';
          ctx.stroke();
        }
      }
    }

    // 2. Outer Duotone Hexagon Frame
    if (outerR > 1) {
      ctx.save();
      traceHexagonPath(cx, hexCenterY, outerR, 0.55);
      ctx.clip();
      ctx.fillStyle = PALETTE.violet;
      ctx.fillRect(cx - outerR, hexCenterY - outerR, outerR, outerR * 2);
      ctx.fillStyle = PALETTE.violetDeep;
      ctx.fillRect(cx, hexCenterY - outerR, outerR, outerR * 2);
      ctx.restore();
    }

    // 3. Inset Clean Inner Hexagon Plate
    if (plateVis > 0.005) {
      const innerR = outerR * 0.78 * plateVis;
      if (innerR > 1) {
        ctx.save();
        traceHexagonPath(cx, hexCenterY, innerR, 0.55);
        ctx.clip();
        ctx.fillStyle = PALETTE.iceWhite;
        ctx.fillRect(cx - innerR, hexCenterY - innerR, innerR, innerR * 2);
        ctx.fillStyle = '#EEEBF7';
        ctx.fillRect(cx, hexCenterY - innerR, innerR, innerR * 2);

        const sheenP = mapRange(p, 0.42, 0.64);
        if (sheenP > 0 && sheenP < 1) {
          const sx = lerp(cx - innerR * 1.4, cx + innerR * 1.4, easeInOutCubic(sheenP));
          const sw = innerR * 0.24;
          ctx.beginPath();
          ctx.moveTo(sx - sw + innerR * 0.35, hexCenterY - innerR);
          ctx.lineTo(sx + sw + innerR * 0.35, hexCenterY - innerR);
          ctx.lineTo(sx + sw - innerR * 0.35, hexCenterY + innerR);
          ctx.lineTo(sx - sw - innerR * 0.35, hexCenterY + innerR);
          ctx.closePath();
          ctx.fillStyle = 'rgba(255, 255, 255, 0.65)';
          ctx.fill();
        }
        ctx.restore();
      }
    }

    // 4. Split Electric Bolt + Turquoise Eco-Leaf (Each scales cleanly in-place, strictly separated!)
    if (emblemVis > 0.005) {
      const s = minSide * emblemVis;
      const boltAnchorX = cx - minSide * 0.040;
      const boltAnchorY = hexCenterY;

      // Left: Crisp 6-vertex Duotone Electric Bolt
      ctx.save();
      ctx.translate(boltAnchorX, boltAnchorY);
      ctx.beginPath();
      ctx.moveTo(s * 0.015, -s * 0.086);
      ctx.lineTo(s * 0.004, -s * 0.007);
      ctx.lineTo(s * 0.038, -s * 0.007);
      ctx.lineTo(-s * 0.015, s * 0.086);
      ctx.lineTo(-s * 0.004, s * 0.006);
      ctx.lineTo(-s * 0.038, s * 0.006);
      ctx.closePath();

      ctx.save();
      ctx.clip();
      ctx.fillStyle = PALETTE.violet;
      ctx.fillRect(-s * 0.06, -s * 0.10, s * 0.12, s * 0.20);
      ctx.fillStyle = PALETTE.violetLight;
      ctx.fillRect(-s * 0.06, -s * 0.10, s * 0.12, s * 0.10);
      ctx.restore();
      ctx.restore();

      // Right: Crisp Duotone Eco-Leaf (Strictly separated from bolt at all scales!)
      const leafAnchorX = cx + minSide * 0.044;
      const leafAnchorY = hexCenterY + minSide * 0.056;
      const leafSway = Math.sin(p * Math.PI * 4) * 0.04 * emblemVis;

      ctx.save();
      ctx.translate(leafAnchorX, leafAnchorY);
      ctx.rotate(0.28 + leafSway);

      const leafL = s * 0.118;
      const leafW = s * 0.036;

      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.bezierCurveTo(leafW * 1.15, -leafL * 0.35, leafW * 0.9, -leafL * 0.78, 0, -leafL);
      ctx.bezierCurveTo(-leafW * 0.9, -leafL * 0.78, -leafW * 1.15, -leafL * 0.35, 0, 0);
      ctx.closePath();

      ctx.save();
      ctx.clip();
      ctx.fillStyle = PALETTE.turquoiseDark;
      ctx.fillRect(-leafW * 1.3, -leafL * 1.05, leafW * 1.3, leafL * 1.1);
      ctx.fillStyle = PALETTE.turquoiseBright;
      ctx.fillRect(0, -leafL * 1.05, leafW * 1.3, leafL * 1.1);

      ctx.beginPath();
      ctx.moveTo(0, -leafL * 0.15);
      ctx.lineTo(0, -leafL * 0.76);
      ctx.strokeStyle = 'rgba(250, 251, 254, 0.7)';
      ctx.lineWidth = minSide * 0.0032 * emblemVis;
      ctx.lineCap = 'round';
      ctx.stroke();
      ctx.restore();
      ctx.restore();
    }
  }
}

// Konsep 6: Botanical Canopy — Reboisasi & Pertumbuhan Hutan Mikro
// 2D Flat Vector Single Icon Motion | 16:9 4K Ready | 20s Seamless Loop (3 Scenes)
// Recommended Export: 3840x2160, 60fps, 100 Mbps

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;

  // Color Palette — Champagne Linen, Blush Sand, Olive Moss, Terracotta Clay & Warm Espresso (Zero Background Glow)
  const PALETTE = {
    bgTop: '#FBF6EE',
    bgBottom: '#F0E2D2',
    espressoDark: '#4A3525',
    espressoMid: '#684C37',
    terracottaDark: '#B0573B',
    terracotta: '#C86D51',
    terracottaSoft: '#DF8E73',
    mossDeep: '#455E24',
    moss: '#5B7B32',
    sageLeaf: '#7A9E49',
    sageLight: '#97B866',
    oceanSoft: '#71A69E',
    oceanLight: '#8BBDB5',
    ivory: '#FCF9F4',
    shadow: 'rgba(74, 53, 37, 0.075)'
  };

  // --- Easing & Math Helpers ---
  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function mapRange(v, inMin, inMax) {
    return clamp01((v - inMin) / (inMax - inMin));
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function easeOutCubic(u) {
    const x = 1 - clamp01(u);
    return 1 - x * x * x;
  }

  function easeInCubic(u) {
    const x = clamp01(u);
    return x * x * x;
  }

  function easeInOutCubic(u) {
    const x = clamp01(u);
    return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
  }

  function easeOutQuart(u) {
    const x = 1 - clamp01(u);
    return 1 - x * x * x * x;
  }

  function easeInOutQuart(u) {
    const x = clamp01(u);
    return x < 0.5 ? 8 * x * x * x * x : 1 - Math.pow(-2 * x + 2, 4) / 2;
  }

  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, Math.abs(w) * 0.5, Math.abs(h) * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  }

  function drawDiamond(x, y, rx, ry, leftC, rightC) {
    if (rx <= 0.4 || ry <= 0.4) return;
    ctx.beginPath();
    ctx.moveTo(x, y - ry);
    ctx.lineTo(x + rx, y);
    ctx.lineTo(x, y + ry);
    ctx.lineTo(x - rx, y);
    ctx.closePath();
    ctx.save();
    ctx.clip();
    ctx.fillStyle = leftC;
    ctx.fillRect(x - rx - 1, y - ry - 1, rx + 1, ry * 2 + 2);
    ctx.fillStyle = rightC;
    ctx.fillRect(x, y - ry - 1, rx + 1, ry * 2 + 2);
    ctx.restore();
  }

  function drawGroundShadow(x, y, rx, ry, alphaScale) {
    if (alphaScale <= 0.001 || rx <= 0.5 || ry <= 0.5) return;
    ctx.save();
    ctx.globalAlpha = alphaScale;
    ctx.fillStyle = PALETTE.shadow;
    ctx.beginPath();
    ctx.ellipse(x, y, rx, ry, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  // --- Clean Background (Flat Elegant Champagne Linen to Blush Sand, Strictly Zero Glow / Zero Borders) ---
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
  bgGrad.addColorStop(0, PALETTE.bgTop);
  bgGrad.addColorStop(1, PALETTE.bgBottom);
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // Shared Botanical Architecture Geometry
  const groundY = cy + minSide * 0.242;
  const plinthH = minSide * 0.022;
  const trunkTopY = cy - minSide * 0.032;
  const shadowBaseY = cy + minSide * 0.305;
  const globeR = minSide * 0.192;

  // Reusable Architectural Ground Soil Plinth & Tapered Tree Trunk + Symmetrical Branches
  function drawSoilAndTrunk(plinthProg, trunkProg, branchProg) {
    // 1. Ground Soil Plinth (Strictly below trunk)
    if (plinthProg > 0.005) {
      const pw = minSide * 0.24 * plinthProg;
      const ph = plinthH * Math.min(1, plinthProg * 1.4);

      ctx.save();
      roundedRectPath(cx - pw * 0.5, groundY, pw, ph, ph * 0.5);
      ctx.clip();
      ctx.fillStyle = PALETTE.espressoDark;
      ctx.fillRect(cx - pw * 0.5, groundY, pw * 0.5, ph);
      ctx.fillStyle = PALETTE.espressoMid;
      ctx.fillRect(cx, groundY, pw * 0.5, ph);
      ctx.restore();

      const accW = pw * 0.34;
      const accH = ph * 0.32;
      roundedRectPath(cx - accW * 0.5, groundY + (ph - accH) * 0.5, accW, accH, accH * 0.5);
      ctx.fillStyle = PALETTE.terracotta;
      ctx.fill();
    }

    // 2. Tapered Architectural Trunk (Rises cleanly from above soil plinth)
    if (trunkProg > 0.005) {
      const trunkBotY = groundY - minSide * 0.006;
      const curTopY = lerp(trunkBotY, trunkTopY, trunkProg);
      const botHalfW = minSide * 0.022 * Math.min(1, trunkProg * 1.5);
      const topHalfW = lerp(botHalfW, minSide * 0.011, trunkProg);

      ctx.beginPath();
      ctx.moveTo(cx - botHalfW, trunkBotY);
      ctx.lineTo(cx - topHalfW, curTopY);
      ctx.lineTo(cx + topHalfW, curTopY);
      ctx.lineTo(cx + botHalfW, trunkBotY);
      ctx.closePath();

      ctx.save();
      ctx.clip();
      ctx.fillStyle = PALETTE.espressoDark;
      ctx.fillRect(cx - botHalfW - 2, curTopY - 2, botHalfW + 2, trunkBotY - curTopY + 4);
      ctx.fillStyle = PALETTE.espressoMid;
      ctx.fillRect(cx, curTopY - 2, botHalfW + 2, trunkBotY - curTopY + 4);
      ctx.restore();
    }

    // 3. Symmetrical Upper & Lower Geometric Branches (Anchored cleanly along trunk, ending strictly before canopy medallions)
    if (branchProg > 0.005) {
      const branchThick = minSide * 0.0105 * Math.min(1, branchProg * 1.4);
      ctx.save();
      ctx.strokeStyle = PALETTE.espressoDark;
      ctx.lineWidth = branchThick;
      ctx.lineCap = 'round';

      // Upper symmetrical branches pointing toward upper-left/right medallions
      const upperOriginY = cy + minSide * 0.022;
      const upperEndX = minSide * 0.078 * branchProg;
      const upperEndY = upperOriginY - minSide * 0.048 * branchProg;
      ctx.beginPath();
      ctx.moveTo(cx - minSide * 0.008, upperOriginY);
      ctx.lineTo(cx - minSide * 0.008 - upperEndX, upperEndY);
      ctx.moveTo(cx + minSide * 0.008, upperOriginY);
      ctx.lineTo(cx + minSide * 0.008 + upperEndX, upperEndY);
      ctx.stroke();

      // Lower symmetrical short twigs pointing toward lower medallions
      const lowerOriginY = cy + minSide * 0.110;
      const lowerEndX = minSide * 0.056 * branchProg;
      const lowerEndY = lowerOriginY - minSide * 0.032 * branchProg;
      ctx.beginPath();
      ctx.moveTo(cx - minSide * 0.011, lowerOriginY);
      ctx.lineTo(cx - minSide * 0.011 - lowerEndX, lowerEndY);
      ctx.moveTo(cx + minSide * 0.011, lowerOriginY);
      ctx.lineTo(cx + minSide * 0.011 + lowerEndX, lowerEndY);
      ctx.stroke();
      ctx.restore();
    }
  }

  // Reusable Crisp 2D Botanical Foliage Medallion (Unified clipped duotone disc + inset geometric leaf vein)
  function drawCanopyMedallion(mx, my, r, leftC, rightC, veinAlpha) {
    if (r <= 0.8) return;
    ctx.save();
    ctx.beginPath();
    ctx.arc(mx, my, r, 0, Math.PI * 2);
    ctx.clip();

    ctx.fillStyle = leftC;
    ctx.fillRect(mx - r - 1, my - r - 1, r + 1, r * 2 + 2);
    ctx.fillStyle = rightC;
    ctx.fillRect(mx, my - r - 1, r + 1, r * 2 + 2);

    if (veinAlpha > 0.01) {
      ctx.globalAlpha = veinAlpha * 0.45;
      ctx.strokeStyle = PALETTE.ivory;
      ctx.lineWidth = Math.max(1.2, r * 0.065);
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(mx, my + r * 0.42);
      ctx.lineTo(mx, my - r * 0.42);
      ctx.moveTo(mx, my + r * 0.08);
      ctx.lineTo(mx - r * 0.28, my - r * 0.16);
      ctx.moveTo(mx, my + r * 0.08);
      ctx.lineTo(mx + r * 0.28, my - r * 0.16);
      ctx.stroke();
    }
    ctx.restore();
  }

  // =========================================================================
  // SCENE 0: BOTANICAL SEED DROP, HUSK SPLIT & TRUNK GROWTH (0.00s – 6.67s)
  // =========================================================================
  if (currentScene === 0) {
    const p = sceneProgress;

    // 0.00 - 0.0975 (0.00s - 0.65s): Completely empty canvas (background only)
    if (p < 0.0975) {
      return;
    }

    const plinthIn = easeOutQuart(mapRange(p, 0.0975, 0.24));
    const seedFall = easeOutQuart(mapRange(p, 0.15, 0.34));
    const seedAppear = easeOutCubic(mapRange(p, 0.15, 0.22));
    const huskSplit = easeInOutQuart(mapRange(p, 0.36, 0.56));
    const huskRetract = 1 - easeInCubic(mapRange(p, 0.68, 0.80));
    const trunkGrow = easeOutQuart(mapRange(p, 0.52, 0.82));
    const branchGrow = easeOutQuart(mapRange(p, 0.72, 0.94));

    // Ground shadow
    drawGroundShadow(cx, shadowBaseY, minSide * 0.155 * plinthIn, minSide * 0.013 * plinthIn, plinthIn);

    // 1. Soil Plinth, Rising Trunk & Branches
    drawSoilAndTrunk(plinthIn, trunkGrow, branchGrow);

    // 2. Terracotta Botanical Seed -> Splits Symmetrically & Retracts Cleanly
    const huskVis = seedAppear * huskRetract;
    if (huskVis > 0.01) {
      const seedRestBotY = groundY - minSide * 0.010;
      const seedStartBotY = cy - minSide * 0.12;
      const pivotY = lerp(seedStartBotY, seedRestBotY, seedFall);
      const seedH = minSide * 0.115 * huskVis;
      const seedHalfW = minSide * 0.046 * huskVis;
      const splitAngle = huskSplit * 0.62; // Opens cleanly ±35.5 deg
      const splitGapX = huskSplit * minSide * 0.022;

      for (let side = -1; side <= 1; side += 2) {
        ctx.save();
        ctx.translate(cx + side * splitGapX, pivotY);
        ctx.rotate(side * splitAngle);

        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.bezierCurveTo(
          side * seedHalfW * 1.25,
          -seedH * 0.18,
          side * seedHalfW * 1.10,
          -seedH * 0.74,
          0,
          -seedH
        );
        ctx.closePath();
        ctx.fillStyle = side < 0 ? PALETTE.terracotta : PALETTE.terracottaSoft;
        ctx.fill();

        // Crisp subtle seed rib line strictly inset
        ctx.beginPath();
        ctx.moveTo(side * seedHalfW * 0.35, -seedH * 0.24);
        ctx.quadraticCurveTo(side * seedHalfW * 0.52, -seedH * 0.50, side * seedHalfW * 0.24, -seedH * 0.76);
        ctx.strokeStyle = 'rgba(252, 249, 244, 0.48)';
        ctx.lineWidth = minSide * 0.0038 * huskVis;
        ctx.lineCap = 'round';
        ctx.stroke();

        ctx.restore();
      }
    }

  // =========================================================================
  // SCENE 1: CASCADE BLOOMING LAYERED DUOTONE CANOPY (6.67s – 13.33s)
  // =========================================================================
  } else if (currentScene === 1) {
    const p = sceneProgress;

    // Trunk & plinth remain seamless from Scene 0 until globe convergence [0.74 -> 0.87]
    const branchRetract = 1 - easeInCubic(mapRange(p, 0.72, 0.81));
    const trunkRetract = 1 - easeInCubic(mapRange(p, 0.74, 0.84));
    const plinthRetract = 1 - easeInCubic(mapRange(p, 0.76, 0.86));
    const globeConverge = easeInOutQuart(mapRange(p, 0.80, 1.0));

    // Ground shadow seamless from Scene 0 -> Scene 1 -> Scene 2
    const shRx = lerp(minSide * 0.155, minSide * 0.135, globeConverge);
    drawGroundShadow(cx, shadowBaseY, shRx, minSide * 0.013, 1);

    // 1. Soil Plinth, Trunk & Branches
    drawSoilAndTrunk(plinthRetract, trunkRetract, branchRetract);

    // Calm breeze sway strictly inside canopy hold window (preserves all negative-space air gaps!)
    const breezeMask = easeInOutCubic(mapRange(p, 0.28, 0.38)) * (1 - easeInOutCubic(mapRange(p, 0.68, 0.76)));
    const swayX = Math.sin(loopT * 2.1) * minSide * 0.006 * breezeMask;
    const swayY = Math.cos(loopT * 2.1) * minSide * 0.003 * breezeMask;

    // 2. 4 Outer Architectural Foliage Medallions (Strictly separated from Center Crown & each other!)
    const outerMedallions = [
      { ox: -0.144, oy: -0.068, r: 0.056, tIn: 0.07, leftC: PALETTE.sageLeaf, rightC: PALETTE.sageLight },
      { ox: 0.144, oy: -0.068, r: 0.056, tIn: 0.10, leftC: PALETTE.sageLeaf, rightC: PALETTE.sageLight },
      { ox: -0.118, oy: 0.044, r: 0.044, tIn: 0.15, leftC: PALETTE.mossDeep, rightC: PALETTE.moss },
      { ox: 0.118, oy: 0.044, r: 0.044, tIn: 0.18, leftC: PALETTE.mossDeep, rightC: PALETTE.moss }
    ];

    const outerRetract = 1 - easeInCubic(mapRange(p, 0.74, 0.86));
    for (let i = 0; i < outerMedallions.length; i++) {
      const m = outerMedallions[i];
      const mIn = easeOutQuart(mapRange(p, m.tIn, m.tIn + 0.16));
      const mScale = mIn * outerRetract;
      if (mScale <= 0.01) continue;

      const mx = cx + m.ox * minSide * lerp(0.88, 1.0, mIn) + swayX * (i < 2 ? 1.0 : 0.7);
      const my = cy + m.oy * minSide + swayY;
      drawCanopyMedallion(mx, my, m.r * minSide * mScale, m.leftC, m.rightC, mScale);
    }

    // 3. Center Crown Medallion -> Morphs Smoothly into Centered Scene 2 Globe!
    const crownIn = easeOutQuart(mapRange(p, 0.0, 0.18));
    if (crownIn > 0.01) {
      const crownX = cx + swayX * 1.1 * (1 - globeConverge);
      const crownY = lerp(cy - minSide * 0.136 + swayY, cy, globeConverge);
      const crownR = lerp(minSide * 0.088 * crownIn, globeR, globeConverge);
      const veinFade = crownIn * (1 - easeOutCubic(mapRange(globeConverge, 0.0, 0.45)));

      // Base medallion seamlessly transitions into ocean sphere colors for Scene 2
      drawCanopyMedallion(crownX, crownY, crownR, PALETTE.moss, PALETTE.sageLeaf, veinFade);

      if (globeConverge > 0.05) {
        const oceanAlpha = easeInOutCubic(mapRange(globeConverge, 0.15, 0.92));
        ctx.save();
        ctx.globalAlpha = oceanAlpha;
        ctx.beginPath();
        ctx.arc(crownX, crownY, crownR, 0, Math.PI * 2);
        ctx.clip();
        ctx.fillStyle = PALETTE.oceanSoft;
        ctx.fillRect(crownX - crownR, crownY - crownR, crownR, crownR * 2);
        ctx.fillStyle = PALETTE.oceanLight;
        ctx.fillRect(crownX, crownY - crownR, crownR, crownR * 2);
        ctx.restore();
      }
    }

    // 4. 4 Crisp Diamond Pollen Accents Strictly Outside Canopy Envelope
    const pollenVis = easeOutCubic(mapRange(p, 0.24, 0.34)) * (1 - easeInCubic(mapRange(p, 0.66, 0.74)));
    if (pollenVis > 0.01) {
      const specs = [
        { x: cx - minSide * 0.245, y: cy - minSide * 0.145, phase: 0.0 },
        { x: cx + minSide * 0.245, y: cy - minSide * 0.145, phase: 1.5 },
        { x: cx - minSide * 0.215, y: cy + minSide * 0.125, phase: 3.0 },
        { x: cx + minSide * 0.215, y: cy + minSide * 0.125, phase: 4.5 }
      ];
      for (let k = 0; k < specs.length; k++) {
        const sp = specs[k];
        const drift = Math.sin(loopT * 2.3 + sp.phase) * minSide * 0.010;
        const pulse = 0.80 + 0.20 * Math.cos(loopT * 2.6 + sp.phase);
        drawDiamond(
          sp.x,
          sp.y + drift,
          minSide * 0.0095 * pollenVis * pulse,
          minSide * 0.015 * pollenVis * pulse,
          k % 2 === 0 ? PALETTE.terracotta : PALETTE.moss,
          k % 2 === 0 ? PALETTE.terracottaSoft : PALETTE.sageLight
        );
      }
    }

  // =========================================================================
  // SCENE 2: 2D EDITORIAL GREEN EARTH GLOBE & BOTANICAL CREST (13.33s – 20.00s)
  // =========================================================================
  } else {
    const p = sceneProgress;

    // 0.9025 - 1.00 (19.35s - 20.00s): Completely empty canvas (background only)
    if (p > 0.9025) {
      return;
    }

    const landIn = easeOutQuart(mapRange(p, 0.02, 0.22));
    const crestIn = easeOutQuart(mapRange(p, 0.12, 0.28));

    const crestOut = 1 - easeInCubic(mapRange(p, 0.68, 0.78));
    const globeScaleOut = 1 - easeInCubic(mapRange(p, 0.78, 0.9025));

    const crestVis = crestIn * crestOut;
    const curGlobeR = globeR * globeScaleOut;

    const breathMask = easeInOutCubic(mapRange(p, 0.20, 0.32)) * (1 - easeInOutCubic(mapRange(p, 0.68, 0.78)));
    const floatY = Math.sin(loopT * 2.1) * minSide * 0.005 * breathMask;
    const globeY = cy + floatY;

    // Ground shadow
    drawGroundShadow(cx, shadowBaseY, minSide * 0.135 * globeScaleOut, minSide * 0.013 * globeScaleOut, globeScaleOut);

    // 1. Flanking Symmetrical Botanical Crest Leaves (Strictly outside globe: r >= globeR + 0.044*minSide!)
    if (crestVis > 0.005) {
      const sway = Math.sin(loopT * 2.3) * 0.045 * breathMask;
      const leafPairAngles = [-0.36, 0.36]; // Clean upper & lower pair on each side

      for (let side = -1; side <= 1; side += 2) {
        for (let k = 0; k < 2; k++) {
          const anchorAngle = (side < 0 ? Math.PI : 0) + leafPairAngles[k] * side;
          const dist = globeR + minSide * 0.046;
          const ax = cx + Math.cos(anchorAngle) * dist;
          const ay = globeY + Math.sin(anchorAngle) * dist;
          const len = minSide * (k === 0 ? 0.072 : 0.056) * crestVis;
          const wid = minSide * (k === 0 ? 0.024 : 0.019) * crestVis;
          const rot = anchorAngle + Math.PI * 0.5 + side * (k === 0 ? -0.35 : 0.35) + sway * side;

          ctx.save();
          ctx.translate(ax, ay);
          ctx.rotate(rot);

          ctx.beginPath();
          ctx.moveTo(0, 0);
          ctx.bezierCurveTo(wid * 1.15, -len * 0.35, wid * 0.9, -len * 0.78, 0, -len);
          ctx.bezierCurveTo(-wid * 0.9, -len * 0.78, -wid * 1.15, -len * 0.35, 0, 0);
          ctx.closePath();

          ctx.save();
          ctx.clip();
          ctx.fillStyle = k === 0 ? PALETTE.moss : PALETTE.terracotta;
          ctx.fillRect(-wid * 1.3, -len * 1.05, wid * 1.3, len * 1.1);
          ctx.fillStyle = k === 0 ? PALETTE.sageLight : PALETTE.terracottaSoft;
          ctx.fillRect(0, -len * 1.05, wid * 1.3, len * 1.1);
          ctx.restore();
          ctx.restore();
        }
      }
    }

    // 2. Clipped 2D Editorial Green Earth Globe
    if (curGlobeR > 1) {
      ctx.save();
      ctx.beginPath();
      ctx.arc(cx, globeY, curGlobeR, 0, Math.PI * 2);
      ctx.clip();

      // Duotone soft ocean base
      ctx.fillStyle = PALETTE.oceanSoft;
      ctx.fillRect(cx - curGlobeR, globeY - curGlobeR, curGlobeR, curGlobeR * 2);
      ctx.fillStyle = PALETTE.oceanLight;
      ctx.fillRect(cx, globeY - curGlobeR, curGlobeR, curGlobeR * 2);

      // Subtle architectural latitude guides strictly inside globe (faint warm ivory)
      ctx.save();
      ctx.globalAlpha = 0.24 * landIn;
      ctx.strokeStyle = PALETTE.ivory;
      ctx.lineWidth = minSide * 0.003 * globeScaleOut;
      const latY = [-0.46, 0, 0.46];
      for (let i = 0; i < latY.length; i++) {
        ctx.beginPath();
        ctx.moveTo(cx - curGlobeR, globeY + latY[i] * curGlobeR);
        ctx.lineTo(cx + curGlobeR, globeY + latY[i] * curGlobeR);
        ctx.stroke();
      }
      ctx.restore();

      // Smoothly drifting 2D Flat Vector Botanical Continent Bands (2D rotation illusion, strictly non-overlapping rows!)
      const driftX = easeInOutCubic(mapRange(p, 0.14, 0.78)) * curGlobeR * 0.48;
      const bandScale = landIn * globeScaleOut;

      const continents = [
        // Upper-left & upper-right green belts
        { x: -0.58, y: -0.50, w: 0.88, h: 0.27, c: PALETTE.moss },
        { x: 0.46, y: -0.44, w: 0.62, h: 0.23, c: PALETTE.sageLeaf },
        // Mid-equatorial green belts
        { x: -0.22, y: -0.06, w: 0.96, h: 0.28, c: PALETTE.sageLeaf },
        { x: -1.35, y: -0.04, w: 0.72, h: 0.25, c: PALETTE.moss },
        // Lower hemisphere green belt
        { x: -0.78, y: 0.40, w: 0.82, h: 0.26, c: PALETTE.mossDeep },
        { x: 0.26, y: 0.42, w: 0.68, h: 0.24, c: PALETTE.moss }
      ];

      ctx.save();
      ctx.globalAlpha = landIn;
      for (let i = 0; i < continents.length; i++) {
        const ct = continents[i];
        const bx = cx + ct.x * curGlobeR + driftX;
        const by = globeY + ct.y * curGlobeR;
        const bw = ct.w * curGlobeR * (0.4 + 0.6 * bandScale);
        const bh = ct.h * curGlobeR;
        roundedRectPath(bx, by - bh * 0.5, bw, bh, bh * 0.5);
        ctx.fillStyle = ct.c;
        ctx.fill();
      }
      ctx.restore();

      // Crisp curved specular arc along upper-left interior edge
      ctx.beginPath();
      ctx.arc(cx, globeY, curGlobeR * 0.82, Math.PI * 1.05, Math.PI * 1.38, false);
      ctx.strokeStyle = 'rgba(252, 249, 244, 0.58)';
      ctx.lineWidth = minSide * 0.010 * globeScaleOut;
      ctx.lineCap = 'round';
      ctx.stroke();

      ctx.restore();
    }
  }
}

// Konsep 4: Circular Weave — Ekonomi Sirkular & Daur Ulang
// 2D Flat Vector Single Icon Motion | 16:9 4K Ready | 20s Seamless Loop (3 Scenes)
// Recommended Export: 3840x2160, 60fps, 100 Mbps

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;

  // Color Palette — Warm Alabaster, Emerald Pine, Fresh Lime & Deep Spruce (Zero Background Glow)
  const PALETTE = {
    bgTop: '#F6F8F3',
    bgBottom: '#E4ECE0',
    forestDark: '#1A362C',
    spruce: '#1E523F',
    emeraldDark: '#176244',
    emerald: '#1E7A56',
    emeraldMid: '#2D9B6E',
    limeDark: '#6CA632',
    lime: '#8BC34A',
    limeBright: '#A6D668',
    glassL: '#B9D6BE',
    glassR: '#D1E7D5',
    ivory: '#F9FBF7',
    shadow: 'rgba(26, 54, 44, 0.075)'
  };

  // --- Easing & Math Helpers ---
  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function mapRange(v, inMin, inMax) {
    return clamp01((v - inMin) / (inMax - inMin));
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function easeInOutSine(u) {
    const x = clamp01(u);
    return -(Math.cos(Math.PI * x) - 1) * 0.5;
  }

  function easeOutCubic(u) {
    const x = 1 - clamp01(u);
    return 1 - x * x * x;
  }

  function easeInCubic(u) {
    const x = clamp01(u);
    return x * x * x;
  }

  function easeInOutCubic(u) {
    const x = clamp01(u);
    return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
  }

  function easeOutQuart(u) {
    const x = 1 - clamp01(u);
    return 1 - x * x * x * x;
  }

  function easeInOutQuart(u) {
    const x = clamp01(u);
    return x < 0.5 ? 8 * x * x * x * x : 1 - Math.pow(-2 * x + 2, 4) / 2;
  }

  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, Math.abs(w) * 0.5, Math.abs(h) * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  }

  function drawDiamond(x, y, rx, ry, leftC, rightC) {
    if (rx <= 0.4 || ry <= 0.4) return;
    ctx.beginPath();
    ctx.moveTo(x, y - ry);
    ctx.lineTo(x + rx, y);
    ctx.lineTo(x, y + ry);
    ctx.lineTo(x - rx, y);
    ctx.closePath();
    ctx.save();
    ctx.clip();
    ctx.fillStyle = leftC;
    ctx.fillRect(x - rx - 1, y - ry - 1, rx + 1, ry * 2 + 2);
    ctx.fillStyle = rightC;
    ctx.fillRect(x, y - ry - 1, rx + 1, ry * 2 + 2);
    ctx.restore();
  }

  function drawGroundShadow(x, y, rx, ry, alphaScale) {
    if (alphaScale <= 0.001 || rx <= 0.5 || ry <= 0.5) return;
    ctx.save();
    ctx.globalAlpha = alphaScale;
    ctx.fillStyle = PALETTE.shadow;
    ctx.beginPath();
    ctx.ellipse(x, y, rx, ry, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  // --- Clean Background (Flat Elegant Sage-Alabaster Gradient, Strictly Zero Glow / Zero Borders) ---
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
  bgGrad.addColorStop(0, PALETTE.bgTop);
  bgGrad.addColorStop(1, PALETTE.bgBottom);
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // Shared Circular Economy & Botanical Transition Geometry
  const ribbonRIn = minSide * 0.184;
  const ribbonROut = minSide * 0.242;
  const seedBaseY = cy + minSide * 0.148;
  const shadowBaseY = cy + minSide * 0.312;

  // C1-Continuous Majestic Orbital Rotation across Scene 0 -> Scene 1 (zero scene-boundary hitch!)
  // Smoothly rotates exactly 1 full 360-deg revolution across [2.1s, 12.1s]
  function getContinuousOrbitAngle(curLoopT) {
    const u = mapRange(curLoopT, 2.1, 12.1);
    return easeInOutCubic(u) * Math.PI * 2;
  }

  // Seamless Single-Path Circular Recycling Arrow (Zero anti-alias cracks, exact tangent-aligned arrowhead!)
  // Each arrow module supports independent trimStart [0..1] and trimEnd [0..1] for silky zero-pop entry & wipe-out!
  function drawCircularRibbons(rotAngle, trimStarts, trimEnds, radialOffsets, alphas) {
    const moduleStyles = [
      { outer: PALETTE.emerald, inner: PALETTE.emeraldDark },
      { outer: PALETTE.lime, inner: PALETTE.limeDark },
      { outer: PALETTE.spruce, inner: PALETTE.forestDark }
    ];

    const bandFullArc = (74 * Math.PI) / 180; // Plus tangent arrowhead (~18 deg) -> 28 deg crisp open gap between modules!

    ctx.save();
    ctx.translate(cx, cy);

    for (let i = 0; i < 3; i++) {
      const tStart = clamp01(trimStarts[i]);
      const tEnd = clamp01(trimEnds[i]);
      const span = tEnd - tStart;
      const aVal = clamp01(alphas[i]);
      if (span <= 0.015 || aVal <= 0.005) continue;

      const style = moduleStyles[i];
      const baseAngle = rotAngle - Math.PI * 0.5 + (i * Math.PI * 2) / 3;
      const a0 = baseAngle + bandFullArc * tStart;
      const a1 = baseAngle + bandFullArc * tEnd;

      const rIn = ribbonRIn + radialOffsets[i];
      const rOut = ribbonROut + radialOffsets[i];
      const rMid = (rIn + rOut) * 0.5;
      const bandHalfW = (rOut - rIn) * 0.5;

      // Arrowhead scales cleanly with visible span so entry/exit is silky with zero sudden pop
      const headScale = easeOutCubic(mapRange(span, 0.0, 0.45));
      const barbExtra = minSide * 0.020 * headScale;
      const headLen = minSide * 0.068 * headScale;

      // Exact unit radial outward normal & clockwise unit tangent at leading edge a1
      const nx = Math.cos(a1);
      const ny = Math.sin(a1);
      const tx = -Math.sin(a1);
      const ty = Math.cos(a1);

      const midX = nx * rMid;
      const midY = ny * rMid;
      const tipX = midX + tx * headLen;
      const tipY = midY + ty * headLen;

      const outBarbX = nx * (rOut + barbExtra);
      const outBarbY = ny * (rOut + barbExtra);
      const inBarbX = nx * (rIn - barbExtra);
      const inBarbY = ny * (rIn - barbExtra);

      ctx.save();
      ctx.globalAlpha = aVal;

      // Build ONE unified seamless silhouette (Outer Arc -> Outer Barb -> Tangent Tip -> Inner Barb -> Inner Arc -> Close)
      ctx.beginPath();
      ctx.arc(0, 0, rOut, a0, a1, false);
      ctx.lineTo(outBarbX, outBarbY);
      ctx.lineTo(tipX, tipY);
      ctx.lineTo(inBarbX, inBarbY);
      ctx.arc(0, 0, rIn, a1, a0, true);
      ctx.closePath();

      // Fill entire unified silhouette with outer tone (zero hairline gaps!)
      ctx.fillStyle = style.outer;
      ctx.fill();

      // Clip to unified silhouette and paint exact inner duotone fold cleanly inside (r <= rMid + inner half of arrowhead)
      ctx.save();
      ctx.clip();

      ctx.beginPath();
      ctx.arc(0, 0, rMid, a0 - 0.02, a1, false);
      ctx.lineTo(tipX, tipY);
      ctx.lineTo(inBarbX - nx * 4, inBarbY - ny * 4);
      ctx.arc(0, 0, Math.max(1, rIn - barbExtra - 4), a1, a0 - 0.02, true);
      ctx.closePath();
      ctx.fillStyle = style.inner;
      ctx.fill();

      ctx.restore();
      ctx.restore();
    }

    ctx.restore();
  }

  // Unified Seamless 2D Flat Vector Eco-Bottle (One continuous curved silhouette — zero disconnected trapezoid!)
  function drawEcoBottle(scaleVal, yOffset) {
    if (scaleVal <= 0.01) return;
    const s = minSide * scaleVal;
    const bCy = cy + yOffset;

    const bodyHalfW = s * 0.050;
    const neckHalfW = s * 0.021;
    const botY = bCy + s * 0.088;
    const shoulderY = bCy - s * 0.016;
    const neckTopY = bCy - s * 0.068;
    const cornerR = s * 0.018;

    ctx.save();
    // Single smooth symmetrical bottle silhouette
    ctx.beginPath();
    ctx.moveTo(cx - neckHalfW, neckTopY);
    ctx.lineTo(cx + neckHalfW, neckTopY);
    // Smooth right neck-to-shoulder curve
    ctx.bezierCurveTo(
      cx + neckHalfW,
      lerp(neckTopY, shoulderY, 0.58),
      cx + bodyHalfW,
      lerp(neckTopY, shoulderY, 0.62),
      cx + bodyHalfW,
      shoulderY
    );
    ctx.lineTo(cx + bodyHalfW, botY - cornerR);
    ctx.quadraticCurveTo(cx + bodyHalfW, botY, cx + bodyHalfW - cornerR, botY);
    ctx.lineTo(cx - bodyHalfW + cornerR, botY);
    ctx.quadraticCurveTo(cx - bodyHalfW, botY, cx - bodyHalfW, botY - cornerR);
    ctx.lineTo(cx - bodyHalfW, shoulderY);
    // Smooth left shoulder-to-neck curve
    ctx.bezierCurveTo(
      cx - bodyHalfW,
      lerp(neckTopY, shoulderY, 0.62),
      cx - neckHalfW,
      lerp(neckTopY, shoulderY, 0.58),
      cx - neckHalfW,
      neckTopY
    );
    ctx.closePath();

    ctx.save();
    ctx.clip();

    // Rich duotone eco-glass body (crisp contrast against alabaster background)
    ctx.fillStyle = PALETTE.glassL;
    ctx.fillRect(cx - bodyHalfW - 2, neckTopY - 2, bodyHalfW + 2, botY - neckTopY + 4);
    ctx.fillStyle = PALETTE.glassR;
    ctx.fillRect(cx, neckTopY - 2, bodyHalfW + 2, botY - neckTopY + 4);

    // Clean vertical specular highlight stripe strictly inset on left glass face
    const hlW = s * 0.009;
    const hlX = cx - bodyHalfW * 0.66;
    roundedRectPath(hlX, shoulderY + s * 0.006, hlW, botY - shoulderY - s * 0.022, hlW * 0.5);
    ctx.fillStyle = 'rgba(249, 251, 247, 0.58)';
    ctx.fill();

    // Crisp duotone emerald label band across center of bottle
    const labelTop = shoulderY + s * 0.024;
    const labelH = s * 0.048;
    ctx.fillStyle = PALETTE.emerald;
    ctx.fillRect(cx - bodyHalfW - 2, labelTop, bodyHalfW + 2, labelH);
    ctx.fillStyle = PALETTE.emeraldMid;
    ctx.fillRect(cx, labelTop, bodyHalfW + 2, labelH);

    // Clean lime diamond emblem centered on label
    drawDiamond(cx, labelTop + labelH * 0.5, s * 0.012, s * 0.016, PALETTE.lime, PALETTE.limeBright);

    ctx.restore();

    // Subtle crisp glass rim contour (uniform weight everywhere)
    ctx.strokeStyle = PALETTE.emerald;
    ctx.lineWidth = minSide * 0.003 * scaleVal;
    ctx.stroke();

    // Crisp Bottle Cap strictly above neck with uniform 0.005*s seam separation
    const capW = neckHalfW * 2.35;
    const capH = s * 0.020;
    const capY = neckTopY - capH - s * 0.005;
    ctx.save();
    roundedRectPath(cx - capW * 0.5, capY, capW, capH, capH * 0.38);
    ctx.clip();
    ctx.fillStyle = PALETTE.forestDark;
    ctx.fillRect(cx - capW * 0.5, capY, capW * 0.5, capH);
    ctx.fillStyle = PALETTE.spruce;
    ctx.fillRect(cx, capY, capW * 0.5, capH);
    ctx.restore();

    ctx.restore();
  }

  // Reusable Crisp 2D Botanical Seed Bud (Unified clipped silhouette — zero center seam!)
  function drawBotanicalSeed(centerX, centerY, scaleVal) {
    if (scaleVal <= 0.01) return;
    const rx = minSide * 0.052 * scaleVal;
    const ry = minSide * 0.072 * scaleVal;

    ctx.save();
    ctx.translate(centerX, centerY);

    ctx.beginPath();
    ctx.moveTo(0, -ry);
    ctx.bezierCurveTo(rx * 1.15, -ry * 0.25, rx * 0.95, ry * 0.85, 0, ry);
    ctx.bezierCurveTo(-rx * 0.95, ry * 0.85, -rx * 1.15, -ry * 0.25, 0, -ry);
    ctx.closePath();

    ctx.save();
    ctx.clip();
    ctx.fillStyle = PALETTE.forestDark;
    ctx.fillRect(-rx * 1.2, -ry * 1.1, rx * 1.2, ry * 2.2);
    ctx.fillStyle = PALETTE.emerald;
    ctx.fillRect(0, -ry * 1.1, rx * 1.2, ry * 2.2);
    ctx.restore();

    drawDiamond(0, ry * 0.08, rx * 0.34, ry * 0.42, PALETTE.lime, PALETTE.limeBright);
    ctx.restore();
  }

  // =========================================================================
  // SCENE 0: STAGGERED 3-RIBBON ORBITAL SWEEP & ECO-BOTTLE (0.00s – 6.67s)
  // =========================================================================
  if (currentScene === 0) {
    const p = sceneProgress;

    // 0.00 - 0.0975 (0.00s - 0.65s): Completely empty canvas (background only)
    if (p < 0.0975) {
      return;
    }

    // Staggered smooth zero-to-full orbital sweep for each of the 3 arrows
    const tEnds = [0, 1, 2].map((i) => easeOutQuart(mapRange(p, 0.0975 + i * 0.055, 0.31 + i * 0.055)));
    const rOffs = tEnds.map((u) => lerp(minSide * 0.045, 0, u));
    const alphas = [0, 1, 2].map((i) => easeOutCubic(mapRange(p, 0.0975 + i * 0.055, 0.175 + i * 0.055)));

    const bottleIn = easeOutQuart(mapRange(p, 0.30, 0.48));
    const rotAngle = getContinuousOrbitAngle(loopT);

    // Ground shadow
    const shProg = easeOutCubic(mapRange(p, 0.0975, 0.36));
    drawGroundShadow(cx, shadowBaseY, minSide * 0.165 * shProg, minSide * 0.014 * shProg, shProg);

    // 1. 3 Seamless Circular Economy Arrow Ribbons
    drawCircularRibbons(rotAngle, [0, 0, 0], tEnds, rOffs, alphas);

    // 2. Centered Eco-Bottle (gentle calm float settling cleanly to 0 before Scene 1 handoff)
    const floatDamp = 1 - easeInOutCubic(mapRange(p, 0.82, 0.98));
    const bottleFloat = Math.sin(loopT * 2.1) * minSide * 0.005 * bottleIn * floatDamp;
    drawEcoBottle(bottleIn, bottleFloat);

  // =========================================================================
  // SCENE 1: SEQUENCED CIRCULAR TRANSFORMATION (6.67s – 13.33s)
  // Bottle -> Center Core -> 6 Orbiting Eco-Facets -> Botanical Seed (ZERO overlap!)
  // =========================================================================
  } else if (currentScene === 1) {
    const p = sceneProgress;

    const rotAngle = getContinuousOrbitAngle(loopT);

    // Zero-pop staggered wipe-out of the 3 outer arrows along their orbital arc (tail catches up cleanly to tip!)
    const tStarts = [0, 1, 2].map((i) => easeInOutQuart(mapRange(p, 0.72 + i * 0.035, 0.88 + i * 0.035)));
    const rOffs = [0, 1, 2].map((i) => lerp(0, minSide * 0.018, tStarts[i]));
    const alphas = [0, 1, 2].map((i) => 1 - easeInCubic(mapRange(p, 0.83 + i * 0.035, 0.89 + i * 0.035)));

    // Strictly non-overlapping inner phase sequence:
    // Phase 1 [0.00..0.18]: Bottle scales cleanly down to zero
    const bottleScale = 1 - easeInCubic(mapRange(p, 0.04, 0.18));

    // Phase 2 [0.18..0.66]: 6 crisp geometric eco-diamonds expand outward, orbit in harmony, then return cleanly to center
    const polyExpand = easeOutQuart(mapRange(p, 0.18, 0.34));
    const polyReturn = easeInOutQuart(mapRange(p, 0.50, 0.66));
    const polyRadius = lerp(0, minSide * 0.092, polyExpand) * (1 - polyReturn);
    const polyScale = easeOutCubic(mapRange(p, 0.18, 0.26)) * (1 - easeInCubic(mapRange(p, 0.61, 0.66)));

    // Phase 3 [0.66..1.00]: Botanical Seed blooms cleanly from merged center, then glides smoothly to Scene 2 base!
    const seedBloom = easeOutQuart(mapRange(p, 0.66, 0.80));
    const seedGlide = easeInOutQuart(mapRange(p, 0.84, 1.0));

    // Ground shadow seamless from Scene 0 -> Scene 1 -> Scene 2
    const shRx = lerp(minSide * 0.165, minSide * 0.115, easeInOutCubic(mapRange(p, 0.72, 0.96)));
    drawGroundShadow(cx, shadowBaseY, shRx, minSide * 0.014, 1);

    // 1. Outer 3 Circular Economy Ribbons (silky wipe-out retract)
    drawCircularRibbons(rotAngle, tStarts, [1, 1, 1], rOffs, alphas);

    // 2. Phase 1: Eco-Bottle retracts cleanly before facets appear
    if (bottleScale > 0.01) {
      drawEcoBottle(bottleScale, 0);
    }

    // 3. Phase 2: 6 Non-Overlapping Recycled Facet Diamonds orbit counter-smoothly inside clear cavity
    if (polyScale > 0.01) {
      const polyCount = 6;
      const counterOrbit = -easeInOutSine(mapRange(p, 0.22, 0.64)) * (Math.PI * 0.667);
      const pRx = minSide * 0.015 * polyScale;
      const pRy = minSide * 0.023 * polyScale;

      for (let k = 0; k < polyCount; k++) {
        const a = counterOrbit - Math.PI * 0.5 + (k * Math.PI * 2) / polyCount;
        const px = cx + Math.cos(a) * polyRadius;
        const py = cy + Math.sin(a) * polyRadius;

        ctx.save();
        ctx.translate(px, py);
        ctx.rotate(a + Math.PI * 0.5);
        const cL = k % 2 === 0 ? PALETTE.emerald : PALETTE.lime;
        const cR = k % 2 === 0 ? PALETTE.emeraldMid : PALETTE.limeBright;
        drawDiamond(0, 0, pRx, pRy, cL, cR);
        ctx.restore();
      }
    }

    // 4. Phase 3: Botanical Seed emerges cleanly after facets complete merge, glides to seedBaseY
    if (seedBloom > 0.01) {
      const curSeedY = lerp(cy, seedBaseY, seedGlide);
      drawBotanicalSeed(cx, curSeedY, seedBloom);
    }

  // =========================================================================
  // SCENE 2: SYMMETRICAL 3-LEAF BOTANICAL BLOOM (13.33s – 20.00s)
  // =========================================================================
  } else {
    const p = sceneProgress;

    // 0.9025 - 1.00 (19.35s - 20.00s): Completely empty canvas (background only)
    if (p > 0.9025) {
      return;
    }

    // Cleanly sequenced seed -> plinth -> stem -> center leaf -> side leaves -> accents (ZERO accidental overlap!)
    const seedSettleOut = 1 - easeInCubic(mapRange(p, 0.02, 0.14));
    const baseIn = easeOutQuart(mapRange(p, 0.06, 0.20));
    const stemIn = easeOutQuart(mapRange(p, 0.14, 0.27));
    const centerLeafIn = easeOutQuart(mapRange(p, 0.21, 0.35));
    const sideLeavesIn = easeOutQuart(mapRange(p, 0.27, 0.41));
    const accentsIn = easeOutCubic(mapRange(p, 0.33, 0.44));

    const accentsOut = 1 - easeInCubic(mapRange(p, 0.68, 0.76));
    const sideLeavesOut = 1 - easeInCubic(mapRange(p, 0.72, 0.81));
    const centerLeafOut = 1 - easeInCubic(mapRange(p, 0.75, 0.84));
    const stemOut = 1 - easeInCubic(mapRange(p, 0.79, 0.87));
    const baseOut = 1 - easeInCubic(mapRange(p, 0.82, 0.9025));

    const baseVis = baseIn * baseOut;
    const stemVis = stemIn * stemOut;
    const centerLeafVis = centerLeafIn * centerLeafOut;
    const sideLeafVis = sideLeavesIn * sideLeavesOut;
    const accentVis = accentsIn * accentsOut;

    const soilBarY = cy + minSide * 0.228;
    const stemBotY = soilBarY - minSide * 0.008;
    const stemTopY = cy + minSide * 0.008;

    // Ground shadow seamless from Scene 1 -> fades cleanly to zero on exit
    const shScale = Math.max(seedSettleOut, baseVis);
    drawGroundShadow(cx, shadowBaseY, minSide * 0.115 * shScale, minSide * 0.014 * shScale, shScale);

    // Helper: Unified Clipped 2D Duotone Leaf with Clean Midrib & Vein Notches (zero hairline seam!)
    function drawDuotoneLeaf(originX, originY, angleRad, len, halfW, scaleProg, leftColor, rightColor) {
      if (scaleProg <= 0.01) return;
      const curL = len * scaleProg;
      const curW = halfW * scaleProg;

      ctx.save();
      ctx.translate(originX, originY);
      ctx.rotate(angleRad);

      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.bezierCurveTo(curW * 1.15, -curL * 0.34, curW * 0.92, -curL * 0.78, 0, -curL);
      ctx.bezierCurveTo(-curW * 0.92, -curL * 0.78, -curW * 1.15, -curL * 0.34, 0, 0);
      ctx.closePath();

      ctx.save();
      ctx.clip();
      ctx.fillStyle = leftColor;
      ctx.fillRect(-curW * 1.25, -curL * 1.05, curW * 1.25, curL * 1.1);
      ctx.fillStyle = rightColor;
      ctx.fillRect(0, -curL * 1.05, curW * 1.25, curL * 1.1);

      // Subtle ivory midrib & 2 clean angled veins strictly inset inside leaf
      const veinAlpha = easeOutCubic(mapRange(scaleProg, 0.35, 1.0));
      if (veinAlpha > 0.01) {
        ctx.globalAlpha = veinAlpha * 0.62;
        ctx.strokeStyle = PALETTE.ivory;
        ctx.lineWidth = minSide * 0.0038 * scaleProg;
        ctx.lineCap = 'round';

        ctx.beginPath();
        ctx.moveTo(0, -curL * 0.12);
        ctx.lineTo(0, -curL * 0.78);
        ctx.stroke();

        for (let v = 0; v < 2; v++) {
          const vy = -curL * (0.34 + v * 0.24);
          const vSpan = curW * (0.42 - v * 0.09);
          ctx.beginPath();
          ctx.moveTo(0, vy);
          ctx.lineTo(-vSpan, vy - curL * 0.10);
          ctx.moveTo(0, vy);
          ctx.lineTo(vSpan, vy - curL * 0.10);
          ctx.stroke();
        }
      }
      ctx.restore();
      ctx.restore();
    }

    // 1. Clean Ground Soil / Horizon Plinth Bar (Strictly below stem)
    if (baseVis > 0.005) {
      const bw = minSide * 0.185 * baseVis;
      const bh = minSide * 0.020 * Math.min(1, baseVis * 1.4);

      ctx.save();
      roundedRectPath(cx - bw * 0.5, soilBarY, bw, bh, bh * 0.5);
      ctx.clip();
      ctx.fillStyle = PALETTE.forestDark;
      ctx.fillRect(cx - bw * 0.5, soilBarY, bw * 0.5, bh);
      ctx.fillStyle = PALETTE.emeraldDark;
      ctx.fillRect(cx, soilBarY, bw * 0.5, bh);
      ctx.restore();

      const accW = bw * 0.34;
      const accH = bh * 0.32;
      roundedRectPath(cx - accW * 0.5, soilBarY + (bh - accH) * 0.5, accW, accH, accH * 0.5);
      ctx.fillStyle = PALETTE.lime;
      ctx.fill();
    }

    // 2. Botanical Seed settles cleanly into soil bar before stem grows upward (zero overlap!)
    if (seedSettleOut > 0.01) {
      const curSeedY = lerp(soilBarY - minSide * 0.012, seedBaseY, seedSettleOut);
      drawBotanicalSeed(cx, curSeedY, seedSettleOut);
    }

    // 3. Central Vertical Botanical Stem
    if (stemVis > 0.005) {
      const curTopY = lerp(stemBotY, stemTopY, stemVis);
      const stemW = minSide * 0.011 * Math.min(1, stemVis * 1.5);
      ctx.beginPath();
      ctx.moveTo(cx, stemBotY);
      ctx.lineTo(cx, curTopY);
      ctx.strokeStyle = PALETTE.forestDark;
      ctx.lineWidth = stemW;
      ctx.lineCap = 'round';
      ctx.stroke();
    }

    // 4. Symmetrical 3-Leaf Crown (Strictly separated attachment nodes & angles — zero leaf overlap!)
    const breezeMask = easeInOutCubic(mapRange(p, 0.32, 0.42)) * (1 - easeInOutCubic(mapRange(p, 0.65, 0.74)));
    const gentleBreeze = Math.sin(loopT * 2.2) * breezeMask;

    if (centerLeafVis > 0.005) {
      drawDuotoneLeaf(
        cx,
        stemTopY - minSide * 0.006,
        gentleBreeze * 0.03,
        minSide * 0.235,
        minSide * 0.068,
        centerLeafVis,
        PALETTE.emerald,
        PALETTE.lime
      );
    }

    if (sideLeafVis > 0.005) {
      const sideNodeY = cy + minSide * 0.114;
      const sideOffsetX = minSide * 0.017;
      const baseTilt = 0.96;

      drawDuotoneLeaf(
        cx - sideOffsetX,
        sideNodeY,
        -(baseTilt * sideLeafVis) + gentleBreeze * 0.052,
        minSide * 0.180,
        minSide * 0.052,
        sideLeafVis,
        PALETTE.emeraldDark,
        PALETTE.emeraldMid
      );

      drawDuotoneLeaf(
        cx + sideOffsetX,
        sideNodeY,
        baseTilt * sideLeafVis + gentleBreeze * 0.052,
        minSide * 0.180,
        minSide * 0.052,
        sideLeafVis,
        PALETTE.emeraldMid,
        PALETTE.limeBright
      );
    }

    // 5. 3 Crisp Diamond Vitality Accents Strictly Outside Leaf Crown
    if (accentVis > 0.005) {
      const accentSpecs = [
        { x: cx, y: cy - minSide * 0.285, phase: 0.0, cL: PALETTE.lime, cR: PALETTE.limeBright },
        { x: cx - minSide * 0.235, y: cy - minSide * 0.085, phase: 1.4, cL: PALETTE.emerald, cR: PALETTE.emeraldMid },
        { x: cx + minSide * 0.235, y: cy - minSide * 0.085, phase: 2.8, cL: PALETTE.emeraldMid, cR: PALETTE.lime }
      ];

      for (let a = 0; a < accentSpecs.length; a++) {
        const sp = accentSpecs[a];
        const pulse = 0.84 + 0.16 * Math.sin(loopT * 2.8 + sp.phase);
        const floatOff = Math.sin(loopT * 2.2 + sp.phase) * minSide * 0.007;
        const rx = minSide * 0.011 * accentVis * pulse;
        const ry = minSide * 0.017 * accentVis * pulse;
        drawDiamond(sp.x, sp.y + floatOff, rx, ry, sp.cL, sp.cR);
      }
    }
  }
}

// Konsep 3: Aero Ribbon — Kincir Angin & Aliran Udara
// 2D Flat Vector Single Icon Motion | 16:9 4K Ready | 20s Seamless Loop (3 Scenes)
// Recommended Export: 3840x2160, 60fps, 100 Mbps

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;

  // Color Palette — Pearl Sky, Cobalt Blue, Crisp Coral & Periwinkle (Zero Background Glow)
  const PALETTE = {
    bgTop: '#F3F7FA',
    bgBottom: '#E2EAF2',
    cobaltDeep: '#1C3F73',
    cobalt: '#2B5EA7',
    cobaltMid: '#4C7DC4',
    periwinkle: '#8FAEE0',
    periwinkleSoft: '#B9CEEE',
    coral: '#E86A58',
    coralSoft: '#F29182',
    cloudWhite: '#FAFCFE',
    cloudTint: '#DAE4F1',
    shadow: 'rgba(28, 63, 115, 0.075)'
  };

  // --- Easing & Math Helpers ---
  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function mapRange(v, inMin, inMax) {
    return clamp01((v - inMin) / (inMax - inMin));
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function easeInOutSine(u) {
    const x = clamp01(u);
    return -(Math.cos(Math.PI * x) - 1) * 0.5;
  }

  function easeOutCubic(u) {
    const x = 1 - clamp01(u);
    return 1 - x * x * x;
  }

  function easeInCubic(u) {
    const x = clamp01(u);
    return x * x * x;
  }

  function easeInOutCubic(u) {
    const x = clamp01(u);
    return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
  }

  function easeOutQuart(u) {
    const x = 1 - clamp01(u);
    return 1 - x * x * x * x;
  }

  function easeInOutQuart(u) {
    const x = clamp01(u);
    return x < 0.5 ? 8 * x * x * x * x : 1 - Math.pow(-2 * x + 2, 4) / 2;
  }

  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, Math.abs(w) * 0.5, Math.abs(h) * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  }

  function drawGroundShadow(x, y, rx, ry, alphaScale) {
    if (alphaScale <= 0.001 || rx <= 0.5 || ry <= 0.5) return;
    ctx.save();
    ctx.globalAlpha = alphaScale;
    ctx.fillStyle = PALETTE.shadow;
    ctx.beginPath();
    ctx.ellipse(x, y, rx, ry, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  // --- Clean Background (Flat Elegant Sky Gradient, Strictly Zero Glow / Zero Borders) ---
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
  bgGrad.addColorStop(0, PALETTE.bgTop);
  bgGrad.addColorStop(1, PALETTE.bgBottom);
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // Shared Architectural Turbine & Transition Geometry
  const hubY = cy - minSide * 0.068;
  const plinthY = cy + minSide * 0.252;
  const plinthH = minSide * 0.024;
  const shadowBaseY = cy + minSide * 0.312;
  const hubBaseR = minSide * 0.034;
  const badgeSeedR = minSide * 0.105;

  // C1-Continuous Aerodynamic Rotor Angle across Scene 0 (t=3.0s) -> Scene 1 (t=12.13s)
  // Smooth ease-in-out covering exactly 4 full revolutions (8 * PI) so velocity is 100% seamless across scene boundary!
  function getContinuousRotorAngle(curLoopT) {
    const tSpinStart = 3.0;
    const tSpinEnd = 12.1333;
    const u = mapRange(curLoopT, tSpinStart, tSpinEnd);
    return easeInOutCubic(u) * Math.PI * 8;
  }

  // Reusable Crisp 2D Wind Turbine Renderer (Exact identical geometry across Scene 0 & Scene 1)
  function drawWindTurbine(plinthProg, towerProg, hubProg, bladeProgs, rotorAngle, hubYPos, hubRadiusOverride) {
    const curHubR = hubRadiusOverride !== null ? hubRadiusOverride : hubBaseR * hubProg;

    // 1. Ground Architectural Plinth (Strictly below tower base)
    if (plinthProg > 0.005) {
      const pw = minSide * 0.22 * plinthProg;
      const ph = plinthH * Math.min(1, plinthProg * 1.4);
      const py = plinthY;

      ctx.save();
      roundedRectPath(cx - pw * 0.5, py, pw, ph, ph * 0.5);
      ctx.clip();
      ctx.fillStyle = PALETTE.cobalt;
      ctx.fillRect(cx - pw * 0.5, py, pw * 0.5, ph);
      ctx.fillStyle = PALETTE.cobaltDeep;
      ctx.fillRect(cx, py, pw * 0.5, ph);
      ctx.restore();

      // Center coral accent bar strictly inset inside plinth
      const accW = pw * 0.32;
      const accH = ph * 0.34;
      roundedRectPath(cx - accW * 0.5, py + (ph - accH) * 0.5, accW, accH, accH * 0.5);
      ctx.fillStyle = PALETTE.coral;
      ctx.fill();
    }

    // 2. Tapered Architectural Wind Tower (Strictly separated from plinth & hub by crisp seams)
    if (towerProg > 0.005) {
      const towerBotY = plinthY - minSide * 0.006;
      const towerFullTopY = hubY + hubBaseR + minSide * 0.008;
      const towerTopY = lerp(towerBotY, towerFullTopY, towerProg);
      const botHalfW = minSide * 0.028 * Math.min(1, towerProg * 1.6);
      const topHalfW = lerp(botHalfW, minSide * 0.013, towerProg);

      // Left sunlit facet
      ctx.beginPath();
      ctx.moveTo(cx - botHalfW, towerBotY);
      ctx.lineTo(cx, towerBotY);
      ctx.lineTo(cx, towerTopY);
      ctx.lineTo(cx - topHalfW, towerTopY);
      ctx.closePath();
      ctx.fillStyle = PALETTE.cloudWhite;
      ctx.fill();

      // Right shaded facet
      ctx.beginPath();
      ctx.moveTo(cx, towerBotY);
      ctx.lineTo(cx + botHalfW, towerBotY);
      ctx.lineTo(cx + topHalfW, towerTopY);
      ctx.lineTo(cx, towerTopY);
      ctx.closePath();
      ctx.fillStyle = PALETTE.cloudTint;
      ctx.fill();

      // Subtle architectural seam bands strictly clipped inside tower
      ctx.save();
      ctx.beginPath();
      ctx.moveTo(cx - botHalfW, towerBotY);
      ctx.lineTo(cx + botHalfW, towerBotY);
      ctx.lineTo(cx + topHalfW, towerTopY);
      ctx.lineTo(cx - topHalfW, towerTopY);
      ctx.closePath();
      ctx.clip();

      const bandH = minSide * 0.007;
      for (let b = 0; b < 2; b++) {
        const by = lerp(towerBotY, towerFullTopY, 0.32 + b * 0.34);
        if (by > towerTopY + bandH) {
          ctx.fillStyle = PALETTE.periwinkle;
          ctx.fillRect(cx - botHalfW, by, botHalfW * 2, bandH);
        }
      }
      ctx.restore();

      // Clean thin outer edge contour on tower for 4K crispness
      ctx.beginPath();
      ctx.moveTo(cx - botHalfW, towerBotY);
      ctx.lineTo(cx - topHalfW, towerTopY);
      ctx.lineTo(cx + topHalfW, towerTopY);
      ctx.lineTo(cx + botHalfW, towerBotY);
      ctx.closePath();
      ctx.strokeStyle = PALETTE.periwinkle;
      ctx.lineWidth = minSide * 0.003;
      ctx.stroke();
    }

    // 3. 3 Precision Duotone Aerodynamic Blades (120 deg apart, strictly clear of hub via collar neck)
    for (let i = 0; i < 3; i++) {
      const bProg = bladeProgs[i];
      if (bProg <= 0.005) continue;

      const angle = rotorAngle - Math.PI * 0.5 + (i * Math.PI * 2) / 3;
      const rootStart = curHubR + minSide * 0.008;
      const bladeFullLen = minSide * 0.205;
      const curLen = bladeFullLen * bProg;
      const rootEnd = rootStart + curLen;
      const maxHalfW = minSide * 0.022 * bProg;
      const shoulderX = rootStart + curLen * 0.24;

      ctx.save();
      ctx.translate(cx, hubYPos);
      ctx.rotate(angle);

      // Short collar stem connecting hub to blade root cleanly
      const stemH = minSide * 0.0085 * bProg;
      ctx.fillStyle = PALETTE.cobaltDeep;
      ctx.fillRect(curHubR + minSide * 0.002, -stemH * 0.5, minSide * 0.009, stemH);

      // Leading sunlit facet (Cloud White)
      ctx.beginPath();
      ctx.moveTo(rootStart, 0);
      ctx.quadraticCurveTo(shoulderX, -maxHalfW * 1.15, rootEnd, 0);
      ctx.lineTo(rootStart, 0);
      ctx.closePath();
      ctx.fillStyle = PALETTE.cloudWhite;
      ctx.fill();

      // Trailing aerodynamic facet (Periwinkle)
      ctx.beginPath();
      ctx.moveTo(rootStart, 0);
      ctx.lineTo(rootEnd, 0);
      ctx.quadraticCurveTo(shoulderX, maxHalfW * 0.72, rootStart, 0);
      ctx.closePath();
      ctx.fillStyle = PALETTE.periwinkle;
      ctx.fill();

      // Crisp Coral aviation tip accent strictly clipped inside blade silhouette
      ctx.save();
      ctx.beginPath();
      ctx.moveTo(rootStart, 0);
      ctx.quadraticCurveTo(shoulderX, -maxHalfW * 1.15, rootEnd, 0);
      ctx.quadraticCurveTo(shoulderX, maxHalfW * 0.72, rootStart, 0);
      ctx.closePath();
      ctx.clip();

      const stripeX = rootStart + curLen * 0.74;
      const stripeW = curLen * 0.11;
      ctx.fillStyle = PALETTE.coral;
      ctx.fillRect(stripeX, -maxHalfW * 1.5, stripeW, maxHalfW * 3);
      ctx.restore();

      // Crisp subtle cobalt outline
      ctx.beginPath();
      ctx.moveTo(rootStart, 0);
      ctx.quadraticCurveTo(shoulderX, -maxHalfW * 1.15, rootEnd, 0);
      ctx.quadraticCurveTo(shoulderX, maxHalfW * 0.72, rootStart, 0);
      ctx.closePath();
      ctx.strokeStyle = PALETTE.cobalt;
      ctx.lineWidth = minSide * 0.0028 * bProg;
      ctx.stroke();

      ctx.restore();
    }

    // 4. Nacelle Hub Disc (Duotone Cobalt + Crisp Coral Cap)
    if (curHubR > 0.8) {
      ctx.save();
      ctx.beginPath();
      ctx.arc(cx, hubYPos, curHubR, 0, Math.PI * 2);
      ctx.clip();
      ctx.fillStyle = PALETTE.cobalt;
      ctx.fillRect(cx - curHubR, hubYPos - curHubR, curHubR, curHubR * 2);
      ctx.fillStyle = PALETTE.cobaltDeep;
      ctx.fillRect(cx, hubYPos - curHubR, curHubR, curHubR * 2);
      ctx.restore();

      const capR = curHubR * 0.44 * Math.min(1, hubProg);
      if (capR > 0.6) {
        ctx.beginPath();
        ctx.arc(cx, hubYPos, capR, 0, Math.PI * 2);
        ctx.fillStyle = PALETTE.coral;
        ctx.fill();
      }
    }
  }

  // =========================================================================
  // SCENE 0: ARCHITECTURAL WIND TURBINE POP-UP (0.00s – 6.67s)
  // =========================================================================
  if (currentScene === 0) {
    const p = sceneProgress;

    // 0.00 - 0.0975 (0.00s - 0.65s): Completely empty canvas (background only)
    if (p < 0.0975) {
      return;
    }

    const plinthIn = easeOutQuart(mapRange(p, 0.0975, 0.23));
    const towerIn = easeOutQuart(mapRange(p, 0.14, 0.29));
    const hubIn = easeOutQuart(mapRange(p, 0.23, 0.34));
    const b0 = easeOutQuart(mapRange(p, 0.27, 0.39));
    const b1 = easeOutQuart(mapRange(p, 0.31, 0.43));
    const b2 = easeOutQuart(mapRange(p, 0.35, 0.47));

    const rotorAngle = getContinuousRotorAngle(loopT);

    // Ground shadow strictly below plinth
    drawGroundShadow(cx, shadowBaseY, minSide * 0.145 * plinthIn, minSide * 0.013 * plinthIn, plinthIn);

    drawWindTurbine(plinthIn, towerIn, hubIn, [b0, b1, b2], rotorAngle, hubY, null);

  // =========================================================================
  // SCENE 1: KINETIC WIND RIBBONS & AERODYNAMIC FLOW (6.67s – 13.33s)
  // =========================================================================
  } else if (currentScene === 1) {
    const p = sceneProgress;

    // Clean retraction choreography after steady spin
    const bladesRetract = 1 - easeInOutCubic(mapRange(p, 0.80, 0.90));
    const towerRetract = 1 - easeInCubic(mapRange(p, 0.82, 0.91));
    const plinthRetract = 1 - easeInCubic(mapRange(p, 0.84, 0.92));
    const handoffToShield = easeInOutQuart(mapRange(p, 0.89, 1.0));

    const curHubY = lerp(hubY, cy, handoffToShield);
    const curHubR = lerp(hubBaseR, badgeSeedR, handoffToShield);
    const capFade = 1 - easeOutCubic(mapRange(handoffToShield, 0.0, 0.65));

    const rotorAngle = getContinuousRotorAngle(loopT);

    // Ground shadow seamless from Scene 0 -> Scene 1 -> Scene 2
    const shRx = lerp(minSide * 0.145 * Math.max(plinthRetract, 0.72), minSide * 0.12, handoffToShield);
    const shRy = lerp(minSide * 0.013, minSide * 0.013, handoffToShield);
    drawGroundShadow(cx, shadowBaseY, shRx, shRy, 1);

    // 1. Flanking Zero-Pop Aero Wind Ribbons (Strictly outside rotor radius 0.247*minSide -> clear corridor >= 0.305*minSide!)
    const laneConfig = [
      { yOff: -minSide * 0.165, color: PALETTE.periwinkle, widthMul: 0.90, outerExtra: 0.00, curlSign: 1, startsL: [0.06, 0.36], startsR: [0.12, 0.42] },
      { yOff: -minSide * 0.068, color: PALETTE.cobalt, widthMul: 1.05, outerExtra: 0.03, curlSign: -1, startsL: [0.11, 0.41], startsR: [0.17, 0.47] },
      { yOff: minSide * 0.032, color: PALETTE.coralSoft, widthMul: 0.88, outerExtra: 0.01, curlSign: 1, startsL: [0.16, 0.45], startsR: [0.22, 0.50] }
    ];

    const passDur = 0.32;
    const corridorInnerX = minSide * 0.308; // Strictly outside blade tip radius (0.247*minSide) -> 0.061*minSide margin!
    const corridorOuterBase = minSide * 0.560;
    const baseStrokeW = minSide * 0.0095;

    ctx.save();
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    for (let side = -1; side <= 1; side += 2) {
      for (let l = 0; l < laneConfig.length; l++) {
        const cfg = laneConfig[l];
        const yBase = cy + cfg.yOff;
        const outerX = corridorOuterBase + minSide * cfg.outerExtra;
        const xFrom = side < 0 ? cx - outerX : cx + corridorInnerX;
        const xTo = side < 0 ? cx - corridorInnerX : cx + outerX;
        const starts = side < 0 ? cfg.startsL : cfg.startsR;

        for (let passIdx = 0; passIdx < starts.length; passIdx++) {
          const tStart = starts[passIdx];
          if (p <= tStart || p >= tStart + passDur) continue;

          const uPass = (p - tStart) / passDur;

          // Zero-to-zero trim path lifecycle (zero pop-in, zero pop-out)
          const headU = easeInOutSine(mapRange(uPass, 0.0, 0.72));
          const tailU = easeInOutSine(mapRange(uPass, 0.28, 1.0));
          if (headU - tailU <= 0.004) continue;

          const fadeIn = easeInOutCubic(mapRange(uPass, 0.0, 0.16));
          const fadeOut = 1 - easeInOutCubic(mapRange(uPass, 0.84, 1.0));
          const passAlpha = fadeIn * fadeOut;
          if (passAlpha <= 0.005) continue;

          const steps = 36;
          const waveAmp = minSide * 0.011;
          const gentleShift = p * Math.PI * 1.2;

          ctx.beginPath();
          for (let s = 0; s <= steps; s++) {
            const u = lerp(tailU, headU, s / steps);
            const rx = lerp(xFrom, xTo, u);
            const env = Math.sin(u * Math.PI);
            const ry = yBase + Math.sin(u * Math.PI * 1.5 - gentleShift) * waveAmp * cfg.curlSign * (0.5 + 0.5 * env);
            if (s === 0) ctx.moveTo(rx, ry);
            else ctx.lineTo(rx, ry);
          }

          ctx.strokeStyle = cfg.color;
          ctx.lineWidth = baseStrokeW * cfg.widthMul * (0.5 + 0.5 * passAlpha);
          ctx.globalAlpha = passAlpha;
          ctx.stroke();
        }
      }
    }
    ctx.restore();

    // 2. Wind Turbine (Identical seamless continuation from Scene 0)
    drawWindTurbine(
      plinthRetract,
      towerRetract,
      capFade,
      [bladesRetract, bladesRetract, bladesRetract],
      rotorAngle,
      curHubY,
      curHubR
    );

  // =========================================================================
  // SCENE 2: CLEAN WIND-POWER SHIELD & LEAF-BOLT EMBLEM (13.33s – 20.00s)
  // =========================================================================
  } else {
    const p = sceneProgress;

    // 0.9025 - 1.00 (19.35s - 20.00s): Completely empty canvas (background only)
    if (p > 0.9025) {
      return;
    }

    const shieldMorph = easeOutQuart(mapRange(p, 0.0, 0.22));
    const innerPlateIn = easeOutQuart(mapRange(p, 0.10, 0.26));
    const emblemIn = easeOutQuart(mapRange(p, 0.18, 0.34));
    const wingAccIn = easeOutCubic(mapRange(p, 0.24, 0.37));

    const wingAccOut = 1 - easeInCubic(mapRange(p, 0.70, 0.78));
    const emblemOut = 1 - easeInCubic(mapRange(p, 0.73, 0.82));
    const shieldScaleOut = 1 - easeInCubic(mapRange(p, 0.80, 0.9025));

    const plateVis = innerPlateIn * shieldScaleOut;
    const emblemVis = emblemIn * emblemOut;
    const wingVis = wingAccIn * wingAccOut;

    const breathMask = easeInOutCubic(mapRange(p, 0.25, 0.35)) * (1 - easeInOutCubic(mapRange(p, 0.70, 0.80)));
    const floatY = Math.sin(loopT * 2.2) * (minSide * 0.006) * breathMask;
    const shieldCenterY = cy + floatY;

    // Ground shadow
    drawGroundShadow(cx, shadowBaseY, minSide * 0.12 * shieldScaleOut, minSide * 0.013 * shieldScaleOut, shieldScaleOut);

    // Helper: Crisp Architectural Shield Path that seamlessly morphs from Circle (m=0) to Shield (m=1)
    function traceShieldPath(centerX, centerY, scale, morphAmt) {
      const m = clamp01(morphAmt);
      const r = badgeSeedR * scale;
      const halfW = lerp(r, minSide * 0.165 * scale, m);
      const topY = centerY - lerp(r, minSide * 0.192 * scale, m);
      const shoulderY = centerY - lerp(r * 0.35, minSide * 0.132 * scale, m);
      const waistY = centerY + lerp(r * 0.25, minSide * 0.025 * scale, m);
      const botY = centerY + lerp(r, minSide * 0.205 * scale, m);

      ctx.beginPath();
      // Top apex
      ctx.moveTo(centerX, topY);
      // Right upper crown
      ctx.bezierCurveTo(
        centerX + halfW * lerp(0.55, 0.42, m),
        topY + (shoulderY - topY) * lerp(0.05, 0.22, m),
        centerX + halfW * lerp(0.95, 0.88, m),
        shoulderY - (shoulderY - topY) * lerp(0.35, 0.10, m),
        centerX + halfW,
        shoulderY
      );
      // Right flank to lower point
      ctx.bezierCurveTo(
        centerX + halfW,
        waistY,
        centerX + halfW * lerp(0.65, 0.56, m),
        lerp(botY, waistY, 0.22),
        centerX,
        botY
      );
      // Left lower point to flank
      ctx.bezierCurveTo(
        centerX - halfW * lerp(0.65, 0.56, m),
        lerp(botY, waistY, 0.22),
        centerX - halfW,
        waistY,
        centerX - halfW,
        shoulderY
      );
      // Left upper crown back to apex
      ctx.bezierCurveTo(
        centerX - halfW * lerp(0.95, 0.88, m),
        shoulderY - (shoulderY - topY) * lerp(0.35, 0.10, m),
        centerX - halfW * lerp(0.55, 0.42, m),
        topY + (shoulderY - topY) * lerp(0.05, 0.22, m),
        centerX,
        topY
      );
      ctx.closePath();
    }

    // 1. Flanking Symmetrical Aero-Bar Accents (Strictly outside shield max width: |x - cx| >= 0.228*minSide)
    if (wingVis > 0.005) {
      const barYOffs = [-minSide * 0.052, minSide * 0.042];
      const barLens = [minSide * 0.075, minSide * 0.052];
      const barH = minSide * 0.011;
      const pulseShift = Math.sin(p * Math.PI * 5) * minSide * 0.008;

      for (let side = -1; side <= 1; side += 2) {
        for (let i = 0; i < 2; i++) {
          const bw = barLens[i] * wingVis;
          const innerEdge = minSide * 0.228 + i * minSide * 0.016 + pulseShift;
          const bx = side < 0 ? cx - innerEdge - bw : cx + innerEdge;
          const by = shieldCenterY + barYOffs[i] - barH * 0.5;

          roundedRectPath(bx, by, bw, barH, barH * 0.5);
          ctx.fillStyle = i === 0 ? PALETTE.periwinkle : PALETTE.coralSoft;
          ctx.fill();
        }
      }
    }

    // 2. Outer Duotone Shield Body
    if (shieldScaleOut > 0.005) {
      ctx.save();
      traceShieldPath(cx, shieldCenterY, shieldScaleOut, shieldMorph);
      ctx.clip();

      const maxSpan = minSide * 0.25;
      ctx.fillStyle = PALETTE.cobalt;
      ctx.fillRect(cx - maxSpan, shieldCenterY - maxSpan, maxSpan, maxSpan * 2);
      ctx.fillStyle = PALETTE.cobaltDeep;
      ctx.fillRect(cx, shieldCenterY - maxSpan, maxSpan, maxSpan * 2);
      ctx.restore();
    }

    // 3. Inset Clean Inner Crest Plate (Uniform border margin inside outer shield)
    if (plateVis > 0.005) {
      const innerScale = 0.80 * plateVis;
      ctx.save();
      traceShieldPath(cx, shieldCenterY, innerScale, shieldMorph);
      ctx.clip();

      const maxSpan = minSide * 0.22;
      ctx.fillStyle = PALETTE.cloudWhite;
      ctx.fillRect(cx - maxSpan, shieldCenterY - maxSpan, maxSpan, maxSpan * 2);
      ctx.fillStyle = '#ECF2F9';
      ctx.fillRect(cx, shieldCenterY - maxSpan, maxSpan, maxSpan * 2);

      // Clean diagonal specular sheen sweeping smoothly once across inner plate
      const sheenP = mapRange(p, 0.42, 0.64);
      if (sheenP > 0 && sheenP < 1) {
        const sx = lerp(cx - minSide * 0.22, cx + minSide * 0.22, easeInOutCubic(sheenP));
        const sw = minSide * 0.042;
        ctx.beginPath();
        ctx.moveTo(sx - sw + minSide * 0.06, shieldCenterY - minSide * 0.22);
        ctx.lineTo(sx + sw + minSide * 0.06, shieldCenterY - minSide * 0.22);
        ctx.lineTo(sx + sw - minSide * 0.06, shieldCenterY + minSide * 0.22);
        ctx.lineTo(sx - sw - minSide * 0.06, shieldCenterY + minSide * 0.22);
        ctx.closePath();
        ctx.fillStyle = 'rgba(255, 255, 255, 0.65)';
        ctx.fill();
      }
      ctx.restore();
    }

    // 4. Clean Energy Lightning Bolt + Stylized Wind-Leaf Crest (Strictly separated, zero messy intersection)
    if (emblemVis > 0.005) {
      const s = minSide * emblemVis;
      const boltX = cx - s * 0.030;
      const boltY = shieldCenterY - s * 0.004;

      // Crisp 6-vertex 2D Duotone Lightning Bolt (zero self-intersection, clipped duotone split)
      ctx.save();
      ctx.translate(boltX, boltY);
      ctx.beginPath();
      ctx.moveTo(s * 0.016, -s * 0.092);
      ctx.lineTo(s * 0.004, -s * 0.008);
      ctx.lineTo(s * 0.042, -s * 0.008);
      ctx.lineTo(-s * 0.016, s * 0.092);
      ctx.lineTo(-s * 0.004, s * 0.006);
      ctx.lineTo(-s * 0.042, s * 0.006);
      ctx.closePath();

      ctx.save();
      ctx.clip();
      ctx.fillStyle = PALETTE.coral;
      ctx.fillRect(-s * 0.06, -s * 0.11, s * 0.12, s * 0.22);

      // Sunlit upper facet cleanly clipped inside bolt silhouette
      ctx.fillStyle = PALETTE.coralSoft;
      ctx.fillRect(-s * 0.06, -s * 0.11, s * 0.12, s * 0.11);
      ctx.restore();
      ctx.restore();

      // Clean Stylized Aero-Leaf tucked cleanly to upper-right with explicit open clearance from bolt
      const leafOriginX = cx + s * 0.042;
      const leafOriginY = shieldCenterY + s * 0.038;
      const leafSway = Math.sin(p * Math.PI * 4) * 0.04 * emblemVis;

      ctx.save();
      ctx.translate(leafOriginX, leafOriginY);
      ctx.rotate(0.42 + leafSway);

      const leafL = s * 0.084;
      const leafW = s * 0.028;

      // Left half of aero-leaf
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.quadraticCurveTo(-leafW, -leafL * 0.48, 0, -leafL);
      ctx.closePath();
      ctx.fillStyle = PALETTE.periwinkle;
      ctx.fill();

      // Right half of aero-leaf
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.quadraticCurveTo(leafW, -leafL * 0.48, 0, -leafL);
      ctx.closePath();
      ctx.fillStyle = PALETTE.cobalt;
      ctx.fill();

      ctx.restore();
    }
  }
}

// Konsep 2: Hydro Kinetic — Siklus Air & Turbin Bersih
// 2D Flat Vector Single Icon Motion | 16:9 4K Ready | 20s Seamless Loop (3 Scenes)
// Recommended Export: 3840x2160, 60fps, 100 Mbps

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;

  // Color Palette — Crisp Glacial Light & Oceanic Duotone (Zero Background Glow)
  const PALETTE = {
    bgTop: '#EFF6F9',
    bgBottom: '#DCECF2',
    oceanDeep: '#17446B',
    slateBlue: '#245882',
    cerulean: '#0E8AA8',
    aquaMid: '#26A9C4',
    mintFoam: '#6AD4C5',
    mintLight: '#9BE5DA',
    dropletTintL: '#D5ECF4',
    dropletTintR: '#E6F5FA',
    iceWhite: '#F7FCFE',
    shadow: 'rgba(23, 68, 107, 0.075)'
  };

  // --- Easing & Math Helpers ---
  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function mapRange(v, inMin, inMax) {
    return clamp01((v - inMin) / (inMax - inMin));
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function easeInOutSine(u) {
    const x = clamp01(u);
    return -(Math.cos(Math.PI * x) - 1) * 0.5;
  }

  function easeOutCubic(u) {
    const x = 1 - clamp01(u);
    return 1 - x * x * x;
  }

  function easeInCubic(u) {
    const x = clamp01(u);
    return x * x * x;
  }

  function easeInOutCubic(u) {
    const x = clamp01(u);
    return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
  }

  function easeOutQuart(u) {
    const x = 1 - clamp01(u);
    return 1 - x * x * x * x;
  }

  function easeInOutQuart(u) {
    const x = clamp01(u);
    return x < 0.5 ? 8 * x * x * x * x : 1 - Math.pow(-2 * x + 2, 4) / 2;
  }

  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, Math.abs(w) * 0.5, Math.abs(h) * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  }

  function drawGroundShadow(x, y, rx, ry, alphaScale) {
    if (alphaScale <= 0.001 || rx <= 0.5 || ry <= 0.5) return;
    ctx.save();
    ctx.globalAlpha = alphaScale;
    ctx.fillStyle = PALETTE.shadow;
    ctx.beginPath();
    ctx.ellipse(x, y, rx, ry, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  // Smooth parametric teardrop path that seamlessly morphs into a pure circle (morphCircle: 0=drop, 1=circle)
  function traceDropletPath(centerX, centerY, radius, morphCircle) {
    const m = clamp01(morphCircle);
    const tipHeight = lerp(radius * 2.02, radius, m);
    const topY = centerY - tipHeight;
    const bottomY = centerY + radius;

    const k = 0.55228475;
    const topCtrlX = lerp(radius * 0.14, radius * k, m);
    const topCtrlY = lerp(topY + radius * 0.42, topY, m);
    const sideUpperCtrlY = lerp(centerY - radius * 0.72, centerY - radius * k, m);

    ctx.beginPath();
    ctx.moveTo(centerX, topY);
    ctx.bezierCurveTo(
      centerX + topCtrlX,
      topCtrlY,
      centerX + radius,
      sideUpperCtrlY,
      centerX + radius,
      centerY
    );
    ctx.bezierCurveTo(
      centerX + radius,
      centerY + radius * k,
      centerX + radius * k,
      bottomY,
      centerX,
      bottomY
    );
    ctx.bezierCurveTo(
      centerX - radius * k,
      bottomY,
      centerX - radius,
      centerY + radius * k,
      centerX - radius,
      centerY
    );
    ctx.bezierCurveTo(
      centerX - radius,
      sideUpperCtrlY,
      centerX - topCtrlX,
      topCtrlY,
      centerX,
      topY
    );
    ctx.closePath();
  }

  // --- Clean Background (Flat Elegant Glacial Gradient, Strictly Zero Glow / Zero Borders) ---
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
  bgGrad.addColorStop(0, PALETTE.bgTop);
  bgGrad.addColorStop(1, PALETTE.bgBottom);
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // Shared Transition Geometry
  const handoffCircleRadius = minSide * 0.11;
  const turbineHubRadius = minSide * 0.068;
  const filterTopCapY = cy - minSide * 0.155;
  const shadowBaseY = cy + minSide * 0.328;

  // =========================================================================
  // SCENE 0: LAYERED WATER DROPLET & INTERNAL WAVES (0.00s – 6.67s)
  // =========================================================================
  if (currentScene === 0) {
    const p = sceneProgress;

    // 0.00 - 0.0975 (0.00s - 0.65s): Completely empty canvas (background only)
    if (p < 0.0975) {
      return;
    }

    const dropIn = easeOutQuart(mapRange(p, 0.0975, 0.27));
    const waveFill = easeOutCubic(mapRange(p, 0.15, 0.34));
    const morphToCore = easeInOutQuart(mapRange(p, 0.82, 1.0));

    const activeBreath = easeInOutCubic(mapRange(p, 0.28, 0.36)) * (1 - easeInOutCubic(mapRange(p, 0.76, 0.84)));
    const floatY = Math.sin(loopT * 2.1) * (minSide * 0.007) * activeBreath;

    const baseR = minSide * 0.162;
    const dropR = lerp(baseR * dropIn, handoffCircleRadius, morphToCore);
    const dropCenterY = lerp(cy + minSide * 0.055 + floatY, cy, morphToCore);

    // Ground shadow cleanly below droplet
    const shR = lerp(minSide * 0.145 * dropIn, minSide * 0.105, morphToCore);
    drawGroundShadow(cx, shadowBaseY, shR, minSide * 0.014 * dropIn, dropIn);

    // 1. Flanking Horizontal Stream Dashes (Strictly separated outside droplet width)
    const dashVis = easeOutCubic(mapRange(p, 0.24, 0.36)) * (1 - easeInCubic(mapRange(p, 0.74, 0.82)));
    if (dashVis > 0.005) {
      const dashYOffsets = [-minSide * 0.055, minSide * 0.045];
      const dashLengths = [minSide * 0.072, minSide * 0.052];
      const dashH = minSide * 0.011;

      for (let side = -1; side <= 1; side += 2) {
        for (let i = 0; i < 2; i++) {
          const drift = Math.sin(loopT * 2.4 + i * 1.4 + side) * (minSide * 0.012);
          const len = dashLengths[i] * dashVis;
          const innerEdge = minSide * 0.242 + i * minSide * 0.016 + drift * side;
          const xPos = side < 0 ? cx - innerEdge - len : cx + innerEdge;
          const yPos = cy + dashYOffsets[i] - dashH * 0.5;

          roundedRectPath(xPos, yPos, len, dashH, dashH * 0.5);
          ctx.fillStyle = i === 0 ? PALETTE.cerulean : PALETTE.mintFoam;
          ctx.fill();
        }
      }
    }

    // 2. Main Hero Water Droplet with Clipped Dual-Layer Liquid Waves
    if (dropR > 1) {
      ctx.save();
      traceDropletPath(cx, dropCenterY, dropR, morphToCore);
      ctx.save();
      ctx.clip();

      const boxTop = dropCenterY - dropR * 2.1;
      const boxH = dropR * 3.2;
      ctx.fillStyle = PALETTE.dropletTintL;
      ctx.fillRect(cx - dropR * 1.1, boxTop, dropR * 1.1, boxH);
      ctx.fillStyle = PALETTE.dropletTintR;
      ctx.fillRect(cx, boxTop, dropR * 1.1, boxH);

      function fillWaveLayer(baseY, amp, freq, phase, color) {
        const left = cx - dropR * 1.15;
        const right = cx + dropR * 1.15;
        const steps = 28;
        ctx.beginPath();
        ctx.moveTo(left, dropCenterY + dropR * 1.15);
        for (let s = 0; s <= steps; s++) {
          const u = s / steps;
          const wx = lerp(left, right, u);
          const wy = baseY + Math.sin(u * Math.PI * freq + phase) * amp;
          ctx.lineTo(wx, wy);
        }
        ctx.lineTo(right, dropCenterY + dropR * 1.15);
        ctx.closePath();
        ctx.fillStyle = color;
        ctx.fill();
      }

      const liquidLevelBack = lerp(dropCenterY + dropR * 1.05, dropCenterY - dropR * 0.24, waveFill);
      const liquidLevelFront = lerp(dropCenterY + dropR * 1.10, dropCenterY - dropR * 0.08, waveFill);
      const morphedLevelBack = lerp(liquidLevelBack, dropCenterY - dropR * 1.15, morphToCore);
      const morphedLevelFront = lerp(liquidLevelFront, dropCenterY - dropR * 1.15, morphToCore);
      const waveAmp = minSide * 0.016 * (1 - morphToCore);

      fillWaveLayer(morphedLevelBack, waveAmp, 2.0, loopT * 2.6, PALETTE.oceanDeep);
      fillWaveLayer(morphedLevelFront, waveAmp * 0.9, 2.2, -loopT * 3.1 + 1.2, PALETTE.cerulean);

      if (morphToCore < 0.85) {
        const left = cx - dropR * 1.15;
        const right = cx + dropR * 1.15;
        const steps = 28;
        ctx.beginPath();
        for (let s = 0; s <= steps; s++) {
          const u = s / steps;
          const wx = lerp(left, right, u);
          const wy = morphedLevelFront + Math.sin(u * Math.PI * 2.2 - loopT * 3.1 + 1.2) * (waveAmp * 0.9);
          if (s === 0) ctx.moveTo(wx, wy);
          else ctx.lineTo(wx, wy);
        }
        ctx.strokeStyle = PALETTE.mintFoam;
        ctx.lineWidth = minSide * 0.0085 * (1 - morphToCore);
        ctx.stroke();
      }

      const bubbleVis = easeOutCubic(mapRange(p, 0.22, 0.34)) * (1 - easeInCubic(mapRange(p, 0.74, 0.84)));
      if (bubbleVis > 0.01) {
        const cols = [-0.42, 0.04, 0.44];
        const radii = [0.011, 0.014, 0.0095];
        for (let b = 0; b < 3; b++) {
          const cycle = (loopT * 0.36 + b * 0.33) % 1;
          const bx = cx + cols[b] * dropR;
          const by = lerp(dropCenterY + dropR * 0.78, dropCenterY + dropR * 0.14, easeOutCubic(cycle));
          const bEnv = Math.sin(cycle * Math.PI) * bubbleVis;
          const br = minSide * radii[b] * bEnv;
          if (br > 0.6) {
            ctx.beginPath();
            ctx.arc(bx, by, br, 0, Math.PI * 2);
            ctx.fillStyle = PALETTE.mintLight;
            ctx.fill();
          }
        }
      }

      if (morphToCore > 0.01) {
        ctx.globalAlpha = morphToCore;
        ctx.fillStyle = PALETTE.oceanDeep;
        ctx.fillRect(cx - dropR, dropCenterY - dropR, dropR, dropR * 2);
        ctx.fillStyle = PALETTE.slateBlue;
        ctx.fillRect(cx, dropCenterY - dropR, dropR, dropR * 2);
        ctx.globalAlpha = 1;
      }

      if (morphToCore < 0.85) {
        ctx.save();
        ctx.globalAlpha = (1 - morphToCore) * 0.85;
        ctx.beginPath();
        ctx.arc(cx, dropCenterY, dropR * 0.77, Math.PI * 0.96, Math.PI * 1.24, false);
        ctx.strokeStyle = PALETTE.iceWhite;
        ctx.lineWidth = minSide * 0.011 * dropIn;
        ctx.lineCap = 'round';
        ctx.stroke();
        ctx.restore();
      }

      ctx.restore();

      ctx.strokeStyle = PALETTE.cerulean;
      ctx.lineWidth = minSide * 0.0045 * dropIn * (1 - morphToCore);
      if (morphToCore < 0.99) {
        ctx.stroke();
      }
      ctx.restore();
    }

  // =========================================================================
  // SCENE 1: PRECISION HYDROELECTRIC TURBINE (6.67s – 13.33s)
  // =========================================================================
  } else if (currentScene === 1) {
    const p = sceneProgress;

    const bladesOut = easeOutQuart(mapRange(p, 0.0, 0.22));
    const bladesIn = 1 - easeInOutCubic(mapRange(p, 0.80, 0.93));
    const bladeReveal = bladesOut * bladesIn;

    const handoffToFilter = easeInOutQuart(mapRange(p, 0.90, 1.0));
    const hubCenterY = lerp(cy, filterTopCapY, handoffToFilter);
    const hubR = lerp(lerp(handoffCircleRadius, turbineHubRadius, bladesOut), minSide * 0.042, handoffToFilter);

    // Smooth hydrodynamic spin: exactly 2 full revolutions across [0.10, 0.88]
    const spinProgress = easeInOutCubic(mapRange(p, 0.10, 0.88));
    const rotorAngle = spinProgress * Math.PI * 4;

    // Ground shadow strictly below rotor envelope (seamless from Scene 0 -> Scene 1 -> Scene 2)
    const shRx = lerp(lerp(minSide * 0.105, minSide * 0.15, bladesOut), minSide * 0.08, handoffToFilter);
    const shRy = lerp(minSide * 0.014, minSide * 0.013, handoffToFilter);
    drawGroundShadow(cx, shadowBaseY, shRx, shRy, 1);

    // 1. Flanking Smooth Streamline Ribbons (Zero-Pop Trim-Path Lifecycle, Strictly Outside Rotor)
    // Each pass starts at length 0 & alpha 0, glides seamlessly along a clean S-streamline, and tapers cleanly back to 0.
    const laneConfig = [
      { yOff: -minSide * 0.092, color: PALETTE.cerulean, widthMul: 0.90, outerExtra: 0.0, waveDir: 1, startsL: [0.14, 0.40], startsR: [0.20, 0.46] },
      { yOff: 0, color: PALETTE.mintFoam, widthMul: 1.05, outerExtra: 0.025, waveDir: -1, startsL: [0.19, 0.45], startsR: [0.25, 0.51] },
      { yOff: minSide * 0.092, color: PALETTE.aquaMid, widthMul: 0.90, outerExtra: 0.0, waveDir: 1, startsL: [0.24, 0.50], startsR: [0.30, 0.54] }
    ];

    const passDur = 0.34;
    const streamInnerX = minSide * 0.335; // Rotor max radius is 0.275*minSide -> strict 0.06*minSide clearance
    const streamOuterBase = minSide * 0.560;
    const baseStrokeW = minSide * 0.010;

    ctx.save();
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    for (let side = -1; side <= 1; side += 2) {
      for (let l = 0; l < laneConfig.length; l++) {
        const cfg = laneConfig[l];
        const yBase = cy + cfg.yOff;
        const outerX = streamOuterBase + minSide * cfg.outerExtra;
        const xFrom = side < 0 ? cx - outerX : cx + streamInnerX;
        const xTo = side < 0 ? cx - streamInnerX : cx + outerX;
        const starts = side < 0 ? cfg.startsL : cfg.startsR;

        for (let passIdx = 0; passIdx < starts.length; passIdx++) {
          const tStart = starts[passIdx];
          if (p <= tStart || p >= tStart + passDur) continue;

          const uPass = (p - tStart) / passDur;

          // Zero-to-zero trim path: head smoothly advances [0.00 -> 0.72], tail smoothly follows [0.28 -> 1.00]
          const headU = easeInOutSine(mapRange(uPass, 0.0, 0.72));
          const tailU = easeInOutSine(mapRange(uPass, 0.28, 1.0));
          const spanU = headU - tailU;

          if (spanU <= 0.004) continue;

          // Smooth opacity & subtle thickness taper at exact entry and exit — zero sudden appearance
          const fadeIn = easeInOutCubic(mapRange(uPass, 0.0, 0.16));
          const fadeOut = 1 - easeInOutCubic(mapRange(uPass, 0.84, 1.0));
          const passAlpha = fadeIn * fadeOut;
          if (passAlpha <= 0.005) continue;

          const steps = 36;
          const waveAmp = minSide * 0.0105;
          const calmDrift = p * Math.PI * 1.4;

          ctx.beginPath();
          for (let s = 0; s <= steps; s++) {
            const u = lerp(tailU, headU, s / steps);
            const rx = lerp(xFrom, xTo, u);
            // Smooth gentle S-streamline that stays calm, clean, and gracefully aligned with flow direction
            const waveEnv = Math.sin(u * Math.PI);
            const ry = yBase + Math.sin(u * Math.PI * 1.6 - calmDrift) * waveAmp * cfg.waveDir * (0.55 + 0.45 * waveEnv);
            if (s === 0) ctx.moveTo(rx, ry);
            else ctx.lineTo(rx, ry);
          }

          ctx.strokeStyle = cfg.color;
          ctx.lineWidth = baseStrokeW * cfg.widthMul * (0.5 + 0.5 * passAlpha);
          ctx.globalAlpha = passAlpha;
          ctx.stroke();
        }
      }
    }
    ctx.restore();

    // 2. 4 Precision Curved Hydrofoil Turbine Blades (Each strictly inside its 90° quadrant)
    if (bladeReveal > 0.005) {
      const bladeCount = 4;
      const spokeInner = hubR + minSide * 0.004;
      const bladeInner = hubR + minSide * 0.022;
      const bladeOuter = lerp(bladeInner, minSide * 0.275, bladeReveal);
      const bladeSpan = bladeOuter - bladeInner;

      for (let i = 0; i < bladeCount; i++) {
        const angle = rotorAngle + (i * Math.PI * 2) / bladeCount;
        ctx.save();
        ctx.translate(cx, hubCenterY);
        ctx.rotate(angle);

        const spokeH = minSide * 0.014 * bladeReveal;
        ctx.fillStyle = PALETTE.oceanDeep;
        ctx.fillRect(spokeInner, -spokeH * 0.5, bladeInner - spokeInner + minSide * 0.006, spokeH);

        const midX = bladeInner + bladeSpan * 0.52;
        const tipX = bladeOuter;
        const tipY = -minSide * 0.028 * bladeReveal;
        const upperCtrlY = -minSide * 0.068 * bladeReveal;
        const lowerCtrlY = minSide * 0.028 * bladeReveal;
        const spineCtrlY = -minSide * 0.018 * bladeReveal;

        ctx.beginPath();
        ctx.moveTo(bladeInner, 0);
        ctx.quadraticCurveTo(midX, upperCtrlY, tipX, tipY);
        ctx.quadraticCurveTo(midX, spineCtrlY, bladeInner, 0);
        ctx.closePath();
        ctx.fillStyle = PALETTE.cerulean;
        ctx.fill();

        ctx.beginPath();
        ctx.moveTo(bladeInner, 0);
        ctx.quadraticCurveTo(midX, spineCtrlY, tipX, tipY);
        ctx.quadraticCurveTo(midX, lowerCtrlY, bladeInner, 0);
        ctx.closePath();
        ctx.fillStyle = PALETTE.aquaMid;
        ctx.fill();

        ctx.beginPath();
        ctx.moveTo(bladeInner + bladeSpan * 0.16, -minSide * 0.008 * bladeReveal);
        ctx.quadraticCurveTo(
          midX,
          upperCtrlY * 0.68,
          lerp(bladeInner, tipX, 0.82),
          tipY * 0.78
        );
        ctx.strokeStyle = PALETTE.mintFoam;
        ctx.lineWidth = minSide * 0.0055 * bladeReveal;
        ctx.lineCap = 'round';
        ctx.stroke();

        ctx.restore();
      }
    }

    // 3. Central Turbine Hub (Duotone Disc + Inner Hexagonal Cap)
    ctx.save();
    ctx.beginPath();
    ctx.arc(cx, hubCenterY, hubR, 0, Math.PI * 2);
    ctx.clip();
    ctx.fillStyle = PALETTE.oceanDeep;
    ctx.fillRect(cx - hubR, hubCenterY - hubR, hubR, hubR * 2);
    ctx.fillStyle = PALETTE.slateBlue;
    ctx.fillRect(cx, hubCenterY - hubR, hubR, hubR * 2);
    ctx.restore();

    const hexVis = bladesOut * (1 - handoffToFilter);
    if (hexVis > 0.01) {
      const hexR = hubR * 0.52 * hexVis;
      ctx.save();
      ctx.translate(cx, hubCenterY);
      ctx.rotate(rotorAngle);
      ctx.beginPath();
      for (let k = 0; k < 6; k++) {
        const a = (k * Math.PI) / 3;
        const hx = Math.cos(a) * hexR;
        const hy = Math.sin(a) * hexR;
        if (k === 0) ctx.moveTo(hx, hy);
        else ctx.lineTo(hx, hy);
      }
      ctx.closePath();
      ctx.fillStyle = PALETTE.iceWhite;
      ctx.fill();

      ctx.beginPath();
      ctx.arc(0, 0, hexR * 0.42, 0, Math.PI * 2);
      ctx.fillStyle = PALETTE.mintFoam;
      ctx.fill();
      ctx.restore();
    }

  // =========================================================================
  // SCENE 2: MULTI-STAGE PURE WATER FILTRATION PRISM (13.33s – 20.00s)
  // =========================================================================
  } else {
    const p = sceneProgress;

    // 0.9025 - 1.00 (19.35s - 20.00s): Completely empty canvas (background only)
    if (p > 0.9025) {
      return;
    }

    const capScaleOut = 1 - easeInCubic(mapRange(p, 0.84, 0.9025));
    const stage1Vis = easeOutQuart(mapRange(p, 0.02, 0.16)) * (1 - easeInCubic(mapRange(p, 0.80, 0.88)));
    const stage2Vis = easeOutQuart(mapRange(p, 0.09, 0.22)) * (1 - easeInCubic(mapRange(p, 0.76, 0.84)));
    const stage3Vis = easeOutQuart(mapRange(p, 0.15, 0.27)) * (1 - easeInCubic(mapRange(p, 0.72, 0.80)));
    const poolVis = easeOutCubic(mapRange(p, 0.20, 0.32)) * (1 - easeInCubic(mapRange(p, 0.69, 0.78)));

    drawGroundShadow(cx, shadowBaseY, minSide * 0.16 * Math.max(poolVis, capScaleOut * 0.5), minSide * 0.013, capScaleOut);

    function drawFilterChamber(yTop, h, topW, botW, leftColor, rightColor, accentColor, vis, pulseAmt) {
      if (vis <= 0.005) return;
      const curTopW = topW * vis;
      const curBotW = botW * vis;
      const curH = h * vis;
      const yMid = yTop + h * 0.5;
      const y0 = yMid - curH * 0.5;
      const y1 = yMid + curH * 0.5;

      ctx.beginPath();
      ctx.moveTo(cx - curTopW * 0.5, y0);
      ctx.lineTo(cx, y0);
      ctx.lineTo(cx, y1);
      ctx.lineTo(cx - curBotW * 0.5, y1);
      ctx.closePath();
      ctx.fillStyle = leftColor;
      ctx.fill();

      ctx.beginPath();
      ctx.moveTo(cx, y0);
      ctx.lineTo(cx + curTopW * 0.5, y0);
      ctx.lineTo(cx + curBotW * 0.5, y1);
      ctx.lineTo(cx, y1);
      ctx.closePath();
      ctx.fillStyle = rightColor;
      ctx.fill();

      if (pulseAmt > 0.01) {
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(cx - curTopW * 0.5, y0);
        ctx.lineTo(cx + curTopW * 0.5, y0);
        ctx.lineTo(cx + curBotW * 0.5, y1);
        ctx.lineTo(cx - curBotW * 0.5, y1);
        ctx.closePath();
        ctx.clip();
        ctx.globalAlpha = pulseAmt * 0.28;
        ctx.fillStyle = PALETTE.iceWhite;
        ctx.fillRect(cx - curTopW * 0.5, y0, curTopW, curH);
        ctx.restore();
      }

      const dotCount = 3;
      const dotR = minSide * 0.0055 * vis;
      const dotSpread = curBotW * 0.42;
      ctx.fillStyle = accentColor;
      for (let d = 0; d < dotCount; d++) {
        const dx = cx + ((d / (dotCount - 1)) - 0.5) * dotSpread;
        ctx.beginPath();
        ctx.arc(dx, yMid, dotR, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    const gap = minSide * 0.015;
    const stageH = minSide * 0.068;

    const capMorph = easeOutQuart(mapRange(p, 0.0, 0.14));
    const capW = lerp(minSide * 0.084, minSide * 0.135, capMorph) * capScaleOut;
    const capH = lerp(minSide * 0.084, minSide * 0.026, capMorph) * capScaleOut;
    if (capW > 1 && capH > 1) {
      ctx.save();
      roundedRectPath(cx - capW * 0.5, filterTopCapY - capH * 0.5, capW, capH, capH * 0.5);
      ctx.clip();
      ctx.fillStyle = PALETTE.oceanDeep;
      ctx.fillRect(cx - capW * 0.5, filterTopCapY - capH * 0.5, capW * 0.5, capH);
      ctx.fillStyle = PALETTE.slateBlue;
      ctx.fillRect(cx, filterTopCapY - capH * 0.5, capW * 0.5, capH);
      ctx.restore();
    }

    const pulseCycle = (loopT * 0.55) % 1;
    function stagePulse(stageIdx) {
      const center = 0.18 + stageIdx * 0.24;
      const dist = Math.abs(pulseCycle - center);
      return Math.max(0, 1 - dist / 0.18);
    }

    const yStage1 = filterTopCapY + minSide * 0.013 + gap;
    drawFilterChamber(
      yStage1,
      stageH,
      minSide * 0.34,
      minSide * 0.265,
      PALETTE.oceanDeep,
      PALETTE.slateBlue,
      PALETTE.aquaMid,
      stage1Vis,
      stagePulse(0)
    );

    const yStage2 = yStage1 + stageH + gap;
    drawFilterChamber(
      yStage2,
      stageH,
      minSide * 0.252,
      minSide * 0.182,
      PALETTE.cerulean,
      PALETTE.aquaMid,
      PALETTE.iceWhite,
      stage2Vis,
      stagePulse(1)
    );

    const yStage3 = yStage2 + stageH + gap;
    drawFilterChamber(
      yStage3,
      stageH * 0.92,
      minSide * 0.168,
      minSide * 0.095,
      PALETTE.mintFoam,
      PALETTE.mintLight,
      PALETTE.oceanDeep,
      stage3Vis,
      stagePulse(2)
    );

    const nozzleBottomY = yStage3 + stageH * 0.92;
    const poolTopY = cy + minSide * 0.258;
    const dropActive = easeOutCubic(mapRange(p, 0.26, 0.33)) * (1 - easeInCubic(mapRange(p, 0.66, 0.72)));

    if (dropActive > 0.01) {
      const dropPhase = (loopT * 0.78) % 1;
      const fallU = easeInCubic(dropPhase);
      const smallDropR = minSide * 0.0175 * dropActive * Math.sin(clamp01(dropPhase * 1.15) * Math.PI);
      const startDropY = nozzleBottomY + minSide * 0.036;
      const endDropY = poolTopY - minSide * 0.022;
      const curDropY = lerp(startDropY, endDropY, fallU);

      if (smallDropR > 0.8) {
        ctx.save();
        traceDropletPath(cx, curDropY, smallDropR, 0);
        ctx.fillStyle = PALETTE.cerulean;
        ctx.fill();

        ctx.save();
        ctx.clip();
        ctx.fillStyle = PALETTE.mintFoam;
        ctx.fillRect(cx, curDropY - smallDropR * 2.2, smallDropR * 1.2, smallDropR * 3.4);
        ctx.restore();
        ctx.restore();
      }
    }

    if (poolVis > 0.005) {
      const rippleBreath = Math.sin(loopT * 4.9) * (minSide * 0.012) * dropActive;
      const bar1W = (minSide * 0.26 + rippleBreath) * poolVis;
      const bar1H = minSide * 0.015;
      const bar2W = (minSide * 0.175 - rippleBreath * 0.6) * poolVis;
      const bar2H = minSide * 0.011;

      roundedRectPath(cx - bar1W * 0.5, poolTopY, bar1W, bar1H, bar1H * 0.5);
      ctx.fillStyle = PALETTE.cerulean;
      ctx.fill();

      const bar2Y = poolTopY + bar1H + minSide * 0.011;
      roundedRectPath(cx - bar2W * 0.5, bar2Y, bar2W, bar2H, bar2H * 0.5);
      ctx.fillStyle = PALETTE.mintFoam;
      ctx.fill();
    }
  }
}

// Konsep 1: Solar Origami — Transformasi Energi Surya
// 2D Flat Vector Single Icon Motion | 16:9 4K Ready | 20s Seamless Loop (3 Scenes)
// Recommended Export: 3840x2160, 60fps, 100 Mbps

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;

  // Color Palette — Light & Elegant Editorial (Zero Background Glow)
  const PALETTE = {
    bgTop: '#FAF7F0',
    bgBottom: '#EFE6D5',
    slateDark: '#1F3447',
    slateMid: '#2C4962',
    slateLight: '#3D6180',
    amberGold: '#E59A1A',
    amberBright: '#F4B942',
    amberSoft: '#FAE3A7',
    terracotta: '#D96B27',
    terracottaSoft: '#E88B4D',
    cream: '#FCF9F2',
    leafDark: '#3E7051',
    leafLight: '#5C9970',
    shadow: 'rgba(31, 52, 71, 0.075)'
  };

  // --- Easing & Math Helpers ---
  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function mapRange(v, inMin, inMax) {
    return clamp01((v - inMin) / (inMax - inMin));
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function easeOutCubic(u) {
    const x = 1 - clamp01(u);
    return 1 - x * x * x;
  }

  function easeInCubic(u) {
    const x = clamp01(u);
    return x * x * x;
  }

  function easeInOutCubic(u) {
    const x = clamp01(u);
    return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
  }

  function easeOutQuart(u) {
    const x = 1 - clamp01(u);
    return 1 - x * x * x * x;
  }

  function easeInOutQuart(u) {
    const x = clamp01(u);
    return x < 0.5 ? 8 * x * x * x * x : 1 - Math.pow(-2 * x + 2, 4) / 2;
  }

  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, Math.abs(w) * 0.5, Math.abs(h) * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  }

  function drawDiamond(x, y, rx, ry, fillLeft, fillRight) {
    ctx.beginPath();
    ctx.moveTo(x, y - ry);
    ctx.lineTo(x, y + ry);
    ctx.lineTo(x - rx, y);
    ctx.closePath();
    ctx.fillStyle = fillLeft;
    ctx.fill();

    ctx.beginPath();
    ctx.moveTo(x, y - ry);
    ctx.lineTo(x + rx, y);
    ctx.lineTo(x, y + ry);
    ctx.closePath();
    ctx.fillStyle = fillRight;
    ctx.fill();
  }

  function drawGroundShadow(x, y, rx, ry, alphaScale) {
    if (alphaScale <= 0.001 || rx <= 0.5 || ry <= 0.5) return;
    ctx.save();
    ctx.globalAlpha = alphaScale;
    ctx.fillStyle = PALETTE.shadow;
    ctx.beginPath();
    ctx.ellipse(x, y, rx, ry, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  // --- Clean Background (Flat Elegant Gradient, Strictly Zero Glow / Zero Borders) ---
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
  bgGrad.addColorStop(0, PALETTE.bgTop);
  bgGrad.addColorStop(1, PALETTE.bgBottom);
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // Shared Transition Geometry
  const seedRadius = minSide * 0.11;
  const sunCoreRadius = minSide * 0.135;
  const bulbDomeCenterY = cy - minSide * 0.062;
  const bulbDomeRadius = minSide * 0.138;
  const shadowBaseY = cy + minSide * 0.305;

  // =========================================================================
  // SCENE 0: SOLAR PANEL ORIGAMI UNFOLD (0.00s – 6.67s)
  // =========================================================================
  if (currentScene === 0) {
    const p = sceneProgress;

    // 0.00 - 0.0975 (0.00s - 0.65s): Completely empty canvas (background only)
    if (p < 0.0975) {
      return;
    }

    // Sub-timings
    const centerIn = easeOutQuart(mapRange(p, 0.0975, 0.21));
    const wingsOut = easeOutQuart(mapRange(p, 0.175, 0.31));
    const standIn = easeOutCubic(mapRange(p, 0.14, 0.27));

    // Exit / Morph into Seed (0.80 -> 1.00)
    const sparksFadeOut = 1 - easeInCubic(mapRange(p, 0.76, 0.83));
    const wingsFoldIn = 1 - easeInOutCubic(mapRange(p, 0.80, 0.90));
    const standRetract = 1 - easeInCubic(mapRange(p, 0.81, 0.89));
    const morphToSeed = easeInOutQuart(mapRange(p, 0.89, 1.0));

    const wingOpen = wingsOut * wingsFoldIn;
    const standOpen = standIn * standRetract;

    // Subtle balanced breathing float while unfolded
    const activeBreath = easeInOutCubic(mapRange(p, 0.28, 0.36)) * (1 - easeInOutCubic(mapRange(p, 0.76, 0.84)));
    const floatY = Math.sin(loopT * 2.2) * (minSide * 0.007) * activeBreath;
    const panelCenterY = lerp(cy - minSide * 0.025 + floatY, cy, morphToSeed);

    // Dimensions — strictly proportional & non-overlapping
    const colW = minSide * 0.125;
    const panelH = minSide * 0.275;
    const framePad = minSide * 0.015;
    const cellGap = minSide * 0.012;
    const cellCorner = minSide * 0.008;
    const frameCorner = minSide * 0.018;

    // Ground shadow strictly separated below pedestal (seamless handoff to Scene 1)
    const shadowRx = centerIn * lerp(minSide * 0.175 * (0.55 + 0.45 * wingOpen), minSide * 0.11, morphToSeed);
    const shadowRy = centerIn * lerp(minSide * 0.016 * (0.55 + 0.45 * wingOpen), minSide * 0.013, morphToSeed);
    drawGroundShadow(cx, shadowBaseY, shadowRx, shadowRy, centerIn);

    // 1. Floating Geometric Solar Quanta (Strictly ABOVE panel with generous clearance)
    if (p > 0.28 && p < 0.84) {
      const sparkMaster = easeOutCubic(mapRange(p, 0.28, 0.37)) * sparksFadeOut;
      const sparkCount = 5;
      const sparkSpan = minSide * 0.32;
      const sparkBaseY = (cy - minSide * 0.025) - panelH * 0.5 - minSide * 0.068;

      for (let i = 0; i < sparkCount; i++) {
        const uNorm = sparkCount === 1 ? 0.5 : i / (sparkCount - 1);
        const sx = cx + (uNorm - 0.5) * sparkSpan;
        const localPhase = ((loopT * 0.42 + i * 0.21) % 1);
        const travel = easeInOutCubic(localPhase);
        const archOffset = Math.sin(uNorm * Math.PI) * minSide * 0.022;
        const sy = sparkBaseY - archOffset - travel * (minSide * 0.065);
        const env = Math.sin(localPhase * Math.PI);
        const sScale = env * sparkMaster;

        if (sScale > 0.01) {
          const rx = minSide * 0.011 * sScale;
          const ry = minSide * 0.017 * sScale;
          const leftC = i % 2 === 0 ? PALETTE.amberGold : PALETTE.terracotta;
          const rightC = i % 2 === 0 ? PALETTE.amberBright : PALETTE.terracottaSoft;
          drawDiamond(sx, sy, rx, ry, leftC, rightC);
        }
      }
    }

    // 2. Pedestal & Architectural Mounting Neck (Strictly below panel bottom)
    if (standOpen > 0.005 && morphToSeed < 0.98) {
      ctx.save();
      const panelBottomY = panelCenterY + panelH * 0.5;
      const neckTopY = panelBottomY + minSide * 0.008;
      const neckH = minSide * 0.056 * standOpen;
      const neckW = minSide * 0.028;

      // Neck pillar (duotone split)
      ctx.fillStyle = PALETTE.slateDark;
      ctx.fillRect(cx - neckW * 0.5, neckTopY, neckW * 0.5, neckH);
      ctx.fillStyle = PALETTE.slateMid;
      ctx.fillRect(cx, neckTopY, neckW * 0.5, neckH);

      // Horizontal base foot (strictly below neck with crisp seam)
      const footY = neckTopY + neckH + minSide * 0.006;
      const footW = minSide * 0.195 * standOpen;
      const footH = minSide * 0.022;
      roundedRectPath(cx - footW * 0.5, footY, footW, footH, footH * 0.5);
      ctx.fillStyle = PALETTE.slateDark;
      ctx.fill();

      // Subtle warm amber accent strip centered on foot
      const accentW = footW * 0.36;
      const accentH = footH * 0.32;
      roundedRectPath(cx - accentW * 0.5, footY + (footH - accentH) * 0.5, accentW, accentH, accentH * 0.5);
      ctx.fillStyle = PALETTE.amberGold;
      ctx.fill();
      ctx.restore();
    }

    // Helper to draw one origami solar column with exact 3-row precision cell grid
    function drawSolarColumn(xLeft, w, yTop, h, foldRatio, sideType, sweepProgress) {
      if (w <= 0.5 || h <= 0.5) return;
      ctx.save();

      // Outer column frame
      const cornerR = sideType === 0 ? frameCorner : frameCorner * 0.9;
      roundedRectPath(xLeft, yTop, w, h, cornerR);
      ctx.fillStyle = sideType === 0 ? PALETTE.slateDark : (foldRatio < 0.5 ? PALETTE.slateDark : '#233B50');
      ctx.fill();

      // Clip interior for crisp cells and diagonal sheen
      const innerPadX = framePad * Math.min(1, w / colW);
      const innerPadY = framePad;
      const innerX = xLeft + innerPadX;
      const innerY = yTop + innerPadY;
      const innerW = Math.max(0, w - innerPadX * 2);
      const innerH = Math.max(0, h - innerPadY * 2);

      if (innerW > 2 && innerH > 2) {
        const rows = 3;
        const cellH = (innerH - cellGap * (rows - 1)) / rows;
        const cRad = Math.min(cellCorner, innerW * 0.25, cellH * 0.25);

        for (let r = 0; r < rows; r++) {
          const cyCell = innerY + r * (cellH + cellGap);
          roundedRectPath(innerX, cyCell, innerW, cellH, cRad);
          ctx.save();
          ctx.clip();

          // Duotone diagonal cell facets
          ctx.fillStyle = PALETTE.slateMid;
          ctx.fillRect(innerX, cyCell, innerW, cellH);

          ctx.beginPath();
          ctx.moveTo(innerX, cyCell);
          ctx.lineTo(innerX + innerW, cyCell);
          ctx.lineTo(innerX, cyCell + cellH);
          ctx.closePath();
          ctx.fillStyle = PALETTE.slateLight;
          ctx.fill();

          // Crisp horizontal micro-busbar
          const barH = Math.max(1.2, minSide * 0.0022);
          ctx.fillStyle = 'rgba(252, 249, 242, 0.28)';
          ctx.fillRect(innerX, cyCell + cellH * 0.5 - barH * 0.5, innerW, barH);

          // Diagonal sunlight reflection sweep (strictly clipped inside cell)
          if (sweepProgress > 0 && sweepProgress < 1) {
            const bandCenter = lerp(cx - minSide * 0.36, cx + minSide * 0.36, sweepProgress);
            const bandW = minSide * 0.055;
            const skew = minSide * 0.06;
            ctx.beginPath();
            ctx.moveTo(bandCenter - bandW * 0.5 + skew, yTop);
            ctx.lineTo(bandCenter + bandW * 0.5 + skew, yTop);
            ctx.lineTo(bandCenter + bandW * 0.5 - skew, yTop + h);
            ctx.lineTo(bandCenter - bandW * 0.5 - skew, yTop + h);
            ctx.closePath();
            ctx.fillStyle = 'rgba(250, 227, 167, 0.36)';
            ctx.fill();
          }

          ctx.restore();
        }
      }

      ctx.restore();
    }

    // Compute light sweep cycles cleanly during middle window
    let sweepP = -1;
    if (p >= 0.34 && p <= 0.54) {
      sweepP = easeInOutCubic(mapRange(p, 0.34, 0.54));
    } else if (p >= 0.58 && p <= 0.78) {
      sweepP = easeInOutCubic(mapRange(p, 0.58, 0.78));
    }

    // 3. Panel Assembly vs Morphing Seed
    if (morphToSeed < 0.001) {
      const centerW = colW * centerIn;
      const centerH = panelH * centerIn;
      const centerX = cx - centerW * 0.5;
      const topY = panelCenterY - centerH * 0.5;

      // Exact seam gap between hinged origami wings (zero accidental overlap)
      const hingeGap = minSide * 0.008 * wingOpen;
      const wingW = colW * wingOpen;

      // Left origami wing (anchored cleanly outside left edge of center column)
      if (wingW > 1) {
        drawSolarColumn(centerX - hingeGap - wingW, wingW, topY, centerH, wingOpen, -1, sweepP);
      }
      // Right origami wing (anchored cleanly outside right edge of center column)
      if (wingW > 1) {
        drawSolarColumn(centerX + centerW + hingeGap, wingW, topY, centerH, wingOpen, 1, sweepP);
      }
      // Center main column
      drawSolarColumn(centerX, centerW, topY, centerH, 1, 0, sweepP);

      // Subtle warm gold hinge pins in the clean gap
      if (wingOpen > 0.25) {
        const pinAlpha = mapRange(wingOpen, 0.25, 0.75);
        const pinW = hingeGap * 0.72;
        const pinH = minSide * 0.032;
        ctx.save();
        ctx.globalAlpha = pinAlpha;
        ctx.fillStyle = PALETTE.amberGold;
        const leftPinX = centerX - hingeGap * 0.5 - pinW * 0.5;
        const rightPinX = centerX + centerW + hingeGap * 0.5 - pinW * 0.5;
        roundedRectPath(leftPinX, panelCenterY - minSide * 0.072 - pinH * 0.5, pinW, pinH, pinW * 0.5);
        ctx.fill();
        roundedRectPath(leftPinX, panelCenterY + minSide * 0.072 - pinH * 0.5, pinW, pinH, pinW * 0.5);
        ctx.fill();
        roundedRectPath(rightPinX, panelCenterY - minSide * 0.072 - pinH * 0.5, pinW, pinH, pinW * 0.5);
        ctx.fill();
        roundedRectPath(rightPinX, panelCenterY + minSide * 0.072 - pinH * 0.5, pinW, pinH, pinW * 0.5);
        ctx.fill();
        ctx.restore();
      }
    } else {
      // Smooth geometric morph from center solar column into the golden solar seed disc
      const curW = lerp(colW, seedRadius * 2, morphToSeed);
      const curH = lerp(panelH, seedRadius * 2, morphToSeed);
      const curRad = lerp(frameCorner, seedRadius, morphToSeed);

      ctx.save();
      roundedRectPath(cx - curW * 0.5, panelCenterY - curH * 0.5, curW, curH, curRad);
      ctx.save();
      ctx.clip();

      // Base morph layer: slate fades cleanly into amber gold
      ctx.fillStyle = PALETTE.slateDark;
      ctx.fillRect(cx - curW * 0.5, panelCenterY - curH * 0.5, curW, curH);

      // Cross-dissolve panel cells out cleanly
      const cellsAlpha = 1 - easeOutCubic(mapRange(morphToSeed, 0, 0.45));
      if (cellsAlpha > 0.01) {
        ctx.globalAlpha = cellsAlpha;
        drawSolarColumn(cx - curW * 0.5, curW, panelCenterY - curH * 0.5, curH, 1, 0, -1);
        ctx.globalAlpha = 1;
      }

      // Golden solar core rises cleanly inside morph shape
      const goldAlpha = easeInOutCubic(mapRange(morphToSeed, 0.15, 0.85));
      if (goldAlpha > 0.01) {
        ctx.globalAlpha = goldAlpha;
        ctx.fillStyle = PALETTE.amberGold;
        ctx.fillRect(cx - curW * 0.5, panelCenterY - curH * 0.5, curW, curH);

        // Duotone sunlit right half
        ctx.fillStyle = PALETTE.amberBright;
        ctx.fillRect(cx, panelCenterY - curH * 0.5, curW * 0.5, curH);
        ctx.globalAlpha = 1;
      }
      ctx.restore();
      ctx.restore();
    }

  // =========================================================================
  // SCENE 1: GEOMETRIC DUOTONE SUN BLOSSOM (6.67s – 13.33s)
  // =========================================================================
  } else if (currentScene === 1) {
    const p = sceneProgress;

    const bloomIn = easeOutQuart(mapRange(p, 0.0, 0.22));
    const raysTuckOut = 1 - easeInOutCubic(mapRange(p, 0.80, 0.94));
    const rayReveal = bloomIn * raysTuckOut;

    const handoffToBulb = easeInOutQuart(mapRange(p, 0.88, 1.0));
    const coreY = lerp(cy, bulbDomeCenterY, handoffToBulb);
    const coreR = lerp(lerp(seedRadius, sunCoreRadius, bloomIn), bulbDomeRadius, handoffToBulb);

    // Calm stepped rotation (2 clean 30-degree steps with generous hold — zero mechanical jitter)
    const step1 = easeInOutQuart(mapRange(p, 0.24, 0.46));
    const step2 = easeInOutQuart(mapRange(p, 0.52, 0.74));
    const rayAngleOffset = (step1 + step2) * (Math.PI / 6);

    // Subtle harmonic length breathing strictly preserving radial gap
    const breathPhase = Math.sin(p * Math.PI * 4) * (minSide * 0.009) * rayReveal;

    // Ground shadow cleanly below rays (seamless from Scene 0 -> Scene 1 -> Scene 2)
    const shWidth = lerp(lerp(minSide * 0.11, minSide * 0.145, bloomIn), minSide * 0.11, handoffToBulb);
    const shHeight = lerp(lerp(minSide * 0.013, minSide * 0.015, bloomIn), minSide * 0.013, handoffToBulb);
    drawGroundShadow(cx, shadowBaseY, shWidth, shHeight, 1);

    // 1. 12 Faceted Duotone Origami Sun Rays (Strictly non-overlapping, explicit gap from core)
    if (rayReveal > 0.005) {
      const rayCount = 12;
      const radialGap = minSide * 0.022;
      const rInner = coreR + radialGap;

      for (let i = 0; i < rayCount; i++) {
        const isPrimary = i % 2 === 0;
        const baseOuter = isPrimary ? minSide * 0.295 : minSide * 0.252;
        const breathDelta = isPrimary ? breathPhase : -breathPhase * 0.75;
        const rOuter = lerp(rInner, baseOuter + breathDelta, rayReveal);
        const rMid = lerp(rInner, rOuter, 0.44);

        // Max half-width strictly capped well below half-sector width to ensure generous spacing
        const halfW = (isPrimary ? minSide * 0.025 : minSide * 0.019) * rayReveal;
        const angle = (i * (Math.PI * 2)) / rayCount - Math.PI * 0.5 + rayAngleOffset;

        ctx.save();
        ctx.translate(cx, coreY);
        ctx.rotate(angle);

        // Left facet of kite ray
        ctx.beginPath();
        ctx.moveTo(rInner, 0);
        ctx.lineTo(rMid, -halfW);
        ctx.lineTo(rOuter, 0);
        ctx.closePath();
        ctx.fillStyle = isPrimary ? PALETTE.terracotta : PALETTE.amberGold;
        ctx.fill();

        // Right facet of kite ray
        ctx.beginPath();
        ctx.moveTo(rInner, 0);
        ctx.lineTo(rOuter, 0);
        ctx.lineTo(rMid, halfW);
        ctx.closePath();
        ctx.fillStyle = isPrimary ? PALETTE.amberGold : PALETTE.amberBright;
        ctx.fill();

        ctx.restore();
      }
    }

    // 2. 6 Outer Geometric Diamond Accents (Strictly outside rays: r >= 0.34 * minSide)
    const accentIn = easeOutCubic(mapRange(p, 0.16, 0.30));
    const accentOut = 1 - easeInCubic(mapRange(p, 0.74, 0.84));
    const accentVis = accentIn * accentOut;

    if (accentVis > 0.005) {
      const accentCount = 6;
      const baseR = minSide * 0.342 + Math.sin(p * Math.PI * 4) * minSide * 0.008;
      for (let i = 0; i < accentCount; i++) {
        const angle = (i * (Math.PI * 2)) / accentCount - Math.PI * 0.5 + rayAngleOffset;
        const ax = cx + Math.cos(angle) * baseR;
        const ay = coreY + Math.sin(angle) * baseR;
        const aRx = minSide * 0.009 * accentVis;
        const aRy = minSide * 0.015 * accentVis;

        ctx.save();
        ctx.translate(ax, ay);
        ctx.rotate(angle + Math.PI * 0.5);
        drawDiamond(0, 0, aRx, aRy, PALETTE.terracotta, PALETTE.amberBright);
        ctx.restore();
      }
    }

    // 3. Central Duotone Sun Core Disc
    ctx.save();
    ctx.beginPath();
    ctx.arc(cx, coreY, coreR, 0, Math.PI * 2);
    ctx.closePath();
    ctx.clip();

    // Left half gold, right half sunlit gold (blends cleanly toward warm bulb glass on handoff)
    ctx.fillStyle = PALETTE.amberGold;
    ctx.fillRect(cx - coreR, coreY - coreR, coreR * 2, coreR * 2);

    ctx.fillStyle = PALETTE.amberBright;
    ctx.fillRect(cx, coreY - coreR, coreR, coreR * 2);

    // Exact duotone glass color shift during final handoff to Scene 2
    if (handoffToBulb > 0.01) {
      ctx.globalAlpha = handoffToBulb;
      ctx.fillStyle = PALETTE.amberSoft;
      ctx.fillRect(cx - coreR, coreY - coreR, coreR, coreR * 2);
      ctx.fillStyle = '#F7D788';
      ctx.fillRect(cx, coreY - coreR, coreR, coreR * 2);
      ctx.globalAlpha = 1;
    }

    // Crisp inner geometric 4-point emblem (fades cleanly before Scene 2 handoff)
    const emblemAlpha = easeOutCubic(mapRange(p, 0.08, 0.24)) * (1 - easeInCubic(mapRange(p, 0.78, 0.90)));
    if (emblemAlpha > 0.01) {
      const starR = coreR * 0.44 * emblemAlpha;
      const starW = coreR * 0.16 * emblemAlpha;
      const innerRot = -rayAngleOffset * 0.5;
      ctx.save();
      ctx.translate(cx, coreY);
      ctx.rotate(innerRot);
      ctx.globalAlpha = emblemAlpha;

      // Vertical diamond
      drawDiamond(0, 0, starW, starR, PALETTE.cream, '#FFFDF9');
      // Horizontal diamond
      ctx.rotate(Math.PI * 0.5);
      drawDiamond(0, 0, starW, starR, '#FFFDF9', PALETTE.cream);

      // Center accent dot
      ctx.beginPath();
      ctx.arc(0, 0, coreR * 0.11 * emblemAlpha, 0, Math.PI * 2);
      ctx.fillStyle = PALETTE.terracotta;
      ctx.fill();
      ctx.restore();
    }
    ctx.restore();

  // =========================================================================
  // SCENE 2: CLEAN ENERGY ECO-BULB & BOTANICAL FILAMENT (13.33s – 20.00s)
  // =========================================================================
  } else {
    const p = sceneProgress;

    // 0.9025 - 1.00 (19.35s - 20.00s): Completely empty canvas (background only)
    if (p > 0.9025) {
      return;
    }

    // Entry & Reverse-Exit timings
    const neckIn = easeOutQuart(mapRange(p, 0.0, 0.18));
    const baseIn = easeOutQuart(mapRange(p, 0.08, 0.24));
    const leafIn = easeOutQuart(mapRange(p, 0.14, 0.30));
    const outerRayIn = easeOutCubic(mapRange(p, 0.22, 0.36));

    const outerRayOut = 1 - easeInCubic(mapRange(p, 0.70, 0.79));
    const leafOut = 1 - easeInCubic(mapRange(p, 0.73, 0.82));
    const baseOut = 1 - easeInCubic(mapRange(p, 0.76, 0.85));
    const bulbScaleOut = 1 - easeInCubic(mapRange(p, 0.82, 0.9025));

    const neckVis = neckIn * bulbScaleOut;
    const baseVis = baseIn * baseOut;
    const leafVis = leafIn * leafOut;
    const outerRayVis = outerRayIn * outerRayOut;

    const domeR = bulbDomeRadius * bulbScaleOut;
    const domeY = bulbDomeCenterY;
    const neckBottomY = domeY + domeR * 1.48;
    const neckHalfW = domeR * 0.48;

    // Ground shadow
    drawGroundShadow(cx, shadowBaseY, minSide * 0.11 * bulbScaleOut, minSide * 0.013 * bulbScaleOut, bulbScaleOut);

    // 1. 5 Clean Radial Rounded Light Bars Outside Upper Dome (No circular HUD strokes!)
    if (outerRayVis > 0.005) {
      const barCount = 5;
      const barStartR = bulbDomeRadius + minSide * 0.042;
      const barPulse = Math.sin(p * Math.PI * 5) * minSide * 0.008;
      const barLen = (minSide * 0.056 + barPulse) * outerRayVis;
      const barThick = minSide * 0.013;

      for (let i = 0; i < barCount; i++) {
        // Fan cleanly from -150 deg to -30 deg above the bulb
        const deg = -150 + i * 30;
        const rad = (deg * Math.PI) / 180;
        ctx.save();
        ctx.translate(cx, domeY);
        ctx.rotate(rad);
        roundedRectPath(barStartR, -barThick * 0.5, barLen, barThick, barThick * 0.5);
        ctx.fillStyle = i % 2 === 0 ? PALETTE.amberGold : PALETTE.terracotta;
        ctx.fill();
        ctx.restore();
      }
    }

    // 2. Bulb Glass Silhouette (Seamless dome + tapered lower neck)
    if (domeR > 1) {
      ctx.save();
      ctx.beginPath();
      // Upper circular dome from ~38 deg to ~142 deg going counter-clockwise over the top
      const joinAngle = Math.PI * 0.22;
      const rightX = cx + Math.cos(joinAngle) * domeR;
      const rightY = domeY + Math.sin(joinAngle) * domeR;
      const leftX = cx - Math.cos(joinAngle) * domeR;
      const leftY = rightY;

      if (neckVis > 0.01) {
        const curNeckBottom = lerp(domeY + domeR, neckBottomY, neckVis);
        ctx.arc(cx, domeY, domeR, joinAngle, Math.PI - joinAngle, true);
        ctx.bezierCurveTo(
          leftX,
          lerp(leftY, curNeckBottom, 0.45),
          cx - neckHalfW,
          lerp(leftY, curNeckBottom, 0.65),
          cx - neckHalfW,
          curNeckBottom
        );
        ctx.lineTo(cx + neckHalfW, curNeckBottom);
        ctx.bezierCurveTo(
          cx + neckHalfW,
          lerp(rightY, curNeckBottom, 0.65),
          rightX,
          lerp(rightY, curNeckBottom, 0.45),
          rightX,
          rightY
        );
      } else {
        ctx.arc(cx, domeY, domeR, 0, Math.PI * 2);
      }
      ctx.closePath();

      // Clip interior for duotone glass fill, specular sheen, and botanical filament
      ctx.save();
      ctx.clip();

      // Clean warm sunlit glass body (duotone split)
      ctx.fillStyle = PALETTE.amberSoft;
      ctx.fillRect(cx - domeR * 1.1, domeY - domeR * 1.1, domeR * 2.2, domeR * 2.8);

      ctx.fillStyle = '#F7D788';
      ctx.fillRect(cx, domeY - domeR * 1.1, domeR * 1.1, domeR * 2.8);

      // Subtle crisp curved specular reflection along upper-left edge
      ctx.beginPath();
      ctx.arc(cx, domeY, domeR * 0.80, Math.PI * 1.06, Math.PI * 1.38, false);
      ctx.strokeStyle = 'rgba(252, 249, 242, 0.72)';
      ctx.lineWidth = minSide * 0.011 * bulbScaleOut;
      ctx.lineCap = 'round';
      ctx.stroke();

      // Smooth diagonal glass sheen sweep at mid-scene
      const glassSweep = mapRange(p, 0.42, 0.64);
      if (glassSweep > 0 && glassSweep < 1) {
        const sx = lerp(cx - domeR * 1.4, cx + domeR * 1.4, easeInOutCubic(glassSweep));
        const sw = domeR * 0.28;
        ctx.beginPath();
        ctx.moveTo(sx - sw + domeR * 0.4, domeY - domeR);
        ctx.lineTo(sx + sw + domeR * 0.4, domeY - domeR);
        ctx.lineTo(sx + sw - domeR * 0.4, neckBottomY);
        ctx.lineTo(sx - sw - domeR * 0.4, neckBottomY);
        ctx.closePath();
        ctx.fillStyle = 'rgba(255, 253, 249, 0.35)';
        ctx.fill();
      }

      // 3. Botanical Eco-Leaf Filament (Strictly inset inside bulb cavity, zero wall collision)
      if (leafVis > 0.01) {
        const stemBaseY = neckBottomY;
        const stemTopY = lerp(stemBaseY, domeY + domeR * 0.02, leafVis);
        const stemW = minSide * 0.0085 * bulbScaleOut;

        // Central vertical stem
        ctx.beginPath();
        ctx.moveTo(cx, stemBaseY);
        ctx.lineTo(cx, stemTopY);
        ctx.strokeStyle = PALETTE.leafDark;
        ctx.lineWidth = stemW;
        ctx.lineCap = 'round';
        ctx.stroke();

        // Symmetrical gentle botanical sway
        const sway = Math.sin(p * Math.PI * 4) * 0.055 * leafVis;
        const leafLen = domeR * 0.56 * leafVis;
        const leafW = domeR * 0.25 * leafVis;
        const nodeY = lerp(stemBaseY, domeY + domeR * 0.26, leafVis);

        // Helper for crisp 2D duotone leaf
        function drawEcoLeaf(dir) {
          ctx.save();
          ctx.translate(cx, nodeY);
          const openAngle = dir * (0.58 * leafVis + sway);
          ctx.rotate(openAngle);

          // Upper half of leaf
          ctx.beginPath();
          ctx.moveTo(0, 0);
          ctx.quadraticCurveTo(dir * leafW, -leafLen * 0.48, 0, -leafLen);
          ctx.closePath();
          ctx.fillStyle = dir < 0 ? PALETTE.leafLight : PALETTE.leafDark;
          ctx.fill();

          // Lower/inner half of leaf
          ctx.beginPath();
          ctx.moveTo(0, 0);
          ctx.quadraticCurveTo(-dir * leafW * 0.72, -leafLen * 0.48, 0, -leafLen);
          ctx.closePath();
          ctx.fillStyle = dir < 0 ? PALETTE.leafDark : PALETTE.leafLight;
          ctx.fill();

          ctx.restore();
        }

        drawEcoLeaf(-1);
        drawEcoLeaf(1);

        // Clean diamond energy bud strictly above leaf junction
        const budY = domeY - domeR * 0.36;
        const budScale = easeOutCubic(mapRange(leafVis, 0.35, 1.0));
        if (budScale > 0.01) {
          drawDiamond(
            cx,
            budY,
            minSide * 0.016 * budScale,
            minSide * 0.025 * budScale,
            PALETTE.terracotta,
            PALETTE.amberGold
          );
        }
      }

      ctx.restore();

      // Clean outer subtle border on glass silhouette (fades in smoothly after Scene 1 handoff)
      const borderAlpha = easeOutCubic(mapRange(p, 0.0, 0.12)) * bulbScaleOut;
      if (borderAlpha > 0.01) {
        ctx.save();
        ctx.globalAlpha = borderAlpha;
        ctx.strokeStyle = PALETTE.amberGold;
        ctx.lineWidth = minSide * 0.0045 * bulbScaleOut;
        ctx.stroke();
        ctx.restore();
      }
      ctx.restore();
    }

    // 4. Precision 3-Bar Screw Base (Strictly spaced vertically below bulb neck, zero overlap)
    if (baseVis > 0.005) {
      const barGap = minSide * 0.009;
      const barH = minSide * 0.018 * baseVis;
      const startY = neckBottomY + minSide * 0.010;
      const barWidths = [neckHalfW * 1.96, neckHalfW * 1.72, neckHalfW * 1.44];

      for (let i = 0; i < 3; i++) {
        const localProgress = easeOutCubic(mapRange(baseVis, i * 0.14, 0.72 + i * 0.14));
        if (localProgress <= 0.01) continue;
        const bw = barWidths[i] * localProgress;
        const by = startY + i * (minSide * 0.018 + barGap);

        // Left dark half + right mid half via clip
        ctx.save();
        roundedRectPath(cx - bw * 0.5, by, bw, barH, barH * 0.5);
        ctx.clip();
        ctx.fillStyle = PALETTE.slateDark;
        ctx.fillRect(cx - bw * 0.5, by, bw * 0.5, barH);
        ctx.fillStyle = PALETTE.slateMid;
        ctx.fillRect(cx, by, bw * 0.5, barH);
        ctx.restore();
      }

      // Bottom contact cap (strictly below 3rd screw bar)
      const capProgress = easeOutCubic(mapRange(baseVis, 0.45, 1.0));
      if (capProgress > 0.01) {
        const capY = startY + 3 * (minSide * 0.018 + barGap);
        const capW = neckHalfW * 0.88 * capProgress;
        const capH = minSide * 0.017 * capProgress;
        ctx.beginPath();
        ctx.moveTo(cx - capW * 0.5, capY);
        ctx.lineTo(cx + capW * 0.5, capY);
        ctx.lineTo(cx + capW * 0.30, capY + capH);
        ctx.lineTo(cx - capW * 0.30, capY + capH);
        ctx.closePath();
        ctx.fillStyle = PALETTE.terracotta;
        ctx.fill();
      }
    }
  }
}
